#!/usr/bin/env bash
# OpenCode Cockpit as one file.  Generated by tools/make_oneshot.py from the tracked files of the repository: do not edit.
#
#     bash opencode-cockpit.sh [FOLDER]     write the 43 files into FOLDER (default: opencode-cockpit)
#
# Needs bash, and sha256sum or shasum.  It calls no git and opens no connection, refuses a FOLDER that already holds
# files, writes nothing outside FOLDER, and ends by checking the SHA-256 of every file it wrote.
# Every file below is a plain here-document, so this file can be read before it is run.
set -eu
dest=${1:-opencode-cockpit}
case "$dest" in -*) echo "usage: bash opencode-cockpit.sh [FOLDER]" >&2; exit 2;; esac
if [ -e "$dest" ] && [ -n "$(ls -A "$dest" 2>/dev/null)" ]; then
  echo "opencode-cockpit.sh: $dest already holds files; give a new or empty folder" >&2; exit 2
fi
if command -v sha256sum >/dev/null 2>&1; then sum256() { sha256sum "$1" | cut -d' ' -f1; }
elif command -v shasum >/dev/null 2>&1; then sum256() { shasum -a 256 "$1" | cut -d' ' -f1; }
else echo "opencode-cockpit.sh: needs sha256sum or shasum to check what it writes" >&2; exit 2; fi
chop() { printf '%s' "$(cat "$1")" > "$1.oc-tmp" && mv "$1.oc-tmp" "$1"; }     # drop the newline a here-document adds
mkdir -p "$dest"; cd "$dest"
mkdir -p '.github/workflows' 'cockpit' 'cockpit/schema' 'icons' 'tests' 'tests/fake_bin' 'tools' 'web'
cat > '.github/workflows/test.yml' <<'OC_EOF_0'
name: test
on:
  push:
  pull_request:
permissions:
  contents: read
jobs:
  test:
    runs-on: ${{ matrix.os }}
    strategy:
      fail-fast: false
      matrix:
        include:
          - {os: ubuntu-24.04, python: '3.9'}      # the oldest Python this is written for; the newest runner image has no build of it
          - {os: ubuntu-latest, python: '3.12'}
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
      - uses: actions/setup-python@v5
        with:
          python-version: ${{ matrix.python }}
      - name: Tests (standard library only, one file at a time)
        run: |
          for t in tests/test_*.py; do echo "== $t"; python "$t" || exit 1; done
      - name: Icons are what icons/ gives
        run: python tools/make_icons.py --check
      - name: Nothing private in the files or the history
        run: python tools/privacy_scan.py --history
OC_EOF_0
cat > '.gitignore' <<'OC_EOF_1'
runs/
__pycache__/
*.pyc
.DS_Store
OC_EOF_1
