#!/usr/bin/env python3
"""Independent referee for a dispatch log.  Reads only the log (a list of events), keeps its own minimal
bookkeeping, and shares no code with the dispatcher: it does not trust what the dispatcher thinks the state is,
nor what an event says about itself (a "cascade" flag, the addressee of a notice, who answered a question).
   python3 -I check.py log.jsonl        exit 0 = no invariant broken, 1 = broken, 2 = could not read
Invariants:
  I1 one writer: seq 1,2,3… no gaps, clock never goes back
  I2 one live lease per order, and only on an order that is waiting for one
  I3 fencing: tokens only go up; every act under a lease carries the live token and comes from its holder; no lease outlives its expiry
  I4 writers do not overlap: live leases have disjoint write scopes (an order and those above or below it excepted), and every
     write is inside its order and outside every open order under it, however deep
  I5 an intent takes effect once
  I6 nobody decides on a stale view: writes are based on the latest revision, changes on the latest state of the order,
     a cancellation on the latest state of everything it takes along
  I7 shared pools are never over-committed: not by a grant, not by shrinking the pool, not by a negative need, and no
     sub-order asks for what the orders above it hold while they wait for it
  I8 chain of command: who may issue, change, cancel, claim, answer; sub-orders stay inside the parent's scope and budget;
     when an order ends, everything under it ends with it and nothing under it acts afterwards
  I9 nothing starts before what it depends on is done (and released, if the order says so) or while a blocking question
     is open; nothing waits for what cannot finish; when a pinned input moves, the issuer is told
  I10 no judge, no order: every order names a judge who is not the doer and never joins the doer, and only that judge closes it"""
import json, sys

IDS = ['I%d' % i for i in range(1, 11)]
STATEFUL = {'order.issued', 'order.amended', 'order.cancelled', 'lease.granted', 'lease.released', 'lease.expired', 'artifact.rev',
            'report.progress', 'report.submitted', 'order.succeeded', 'order.failed', 'order.dead'}
ENDED = ('CANCELLED', 'FAILED', 'DEAD')


def inside(scope, key):
    if scope == key:
        return True
    return scope[-1:] == '/' and key[:len(scope)] == scope


def clash(a, b):
    return inside(a, b) or inside(b, a)


def check(events):
    bad = {i: [] for i in IDS}
    boss, pools, orders, live, rev, last_token, seen_cause = {}, {}, {}, {}, {}, {}, set()
    asks, handed_in, ended_by, orphans, last_write = {}, {}, {}, {}, None

    def flag(i, e, why):
        bad[i].append('seq %s %s: %s' % (e.get('seq'), e.get('kind'), why))

    def above(a, b):                      # a is b or a is above b
        hops = 0
        while b is not None and hops < 100:
            if a == b:
                return True
            b, hops = boss.get(b), hops + 1
        return False

    def ups(x):                           # the orders above x, nearest first
        out, x = [], (orders.get(x) or {}).get('parent')
        while x is not None and x in orders and x not in out:
            out.append(x)
            x = orders[x]['parent']
        return out

    def kin(x, y):                        # one is an ancestor of the other
        return x == y or x in ups(y) or y in ups(x)

    def open_(o):
        return o['st'] in ('PENDING', 'LEASED', 'JUDGING')

    def below(x):                         # every open order under x, however deep
        return [y for y, c in orders.items() if open_(c) and x in ups(y)]

    def waits(start):                     # everything these cannot finish before
        seen, todo = set(), list(start)
        while todo:
            x = todo.pop()
            if x in seen or x not in orders or orders[x]['st'] == 'SUCCEEDED':
                continue
            seen.add(x)
            todo += orders[x]['after'] + [y for y, c in orders.items() if c['parent'] == x and open_(c)]
        return seen

    def held_up(oid):                     # blocking questions about this order that nobody has answered
        return [a for a, q in asks.items() if q['st'] == 'OPEN' and q['blocking'] and q['about'] == oid]

    def under(e, oid, token, i='I3'):
        l = live.get(oid)
        if l is None:
            flag(i, e, 'acts on %s with token %s but no lease is live' % (oid, token))
        elif l['token'] != token:
            flag(i, e, 'token %s is not the live token %s on %s' % (token, l['token'], oid))
        elif l['holder'] != e.get('by'):
            flag(i, e, '%s is not the holder of %s' % (e.get('by'), oid))

    def orphaned(e, oid, what):           # an order acts although something above it has ended
        gone = [x for x in ups(oid) if not open_(orders[x])]
        if gone:
            flag('I8', e, '%s %s although %s above it is %s' % (oid, what, gone[0], orders[gone[0]]['st']))

    def end(e, oid):                      # an order ended without success: what is under it must end in the same request
        ended_by[oid] = e.get('cause')
        for y in below(oid):
            orphans.setdefault(y, (oid, e.get('cause')))

    def leftovers(e, cause):
        for y, (top, c) in sorted(orphans.items()):
            if c != cause:
                if open_(orders[y]):
                    flag('I8', e, '%s is still open after %s above it ended' % (y, top))
                del orphans[y]

    def overdue(e):                       # a lease past its time that is still live
        for x, l in live.items():
            if l['expires'] <= e['t'] and not l.get('late'):
                flag('I3', e, 'lease on %s (expired at %s) is still live at %s' % (x, l['expires'], e['t']))
                l['late'] = True

    prev_t = None
    for idx, e in enumerate(events):
        k, by, oid = e.get('kind'), e.get('by'), e.get('order')
        if e.get('seq') != idx + 1:
            flag('I1', e, 'expected seq %d' % (idx + 1))
        if prev_t is not None and e.get('t') < prev_t:
            flag('I1', e, 'clock went back')
        prev_t = e.get('t')
        if (e.get('cause'), e.get('n')) in seen_cause:
            flag('I5', e, 'intent %s took effect again' % e.get('cause'))
        seen_cause.add((e.get('cause'), e.get('n')))
        leftovers(e, e.get('cause'))
        if idx and e.get('cause') != events[idx - 1].get('cause'):
            overdue(events[idx - 1])          # a request is over: whatever it did, it may not leave a lease live past its time
        if k not in ('lease.expired', 'order.dead') and not (k == 'order.cancelled' and e.get('cascade')):
            overdue(e)                        # inside one request the clock ends leases one after another and a dead order takes what is under it:
                                              # those steps are not judged one by one
        o = orders.get(oid) if isinstance(oid, str) else None
        if o is not None and k in ('order.amended', 'order.cancelled', 'lease.granted', 'order.succeeded', 'order.failed') and not e.get('cascade'):
            newest = max([o['touched']] + ([orders[y]['touched'] for y in below(oid)] if k == 'order.cancelled' else []))
            if e.get('basis', 0) < newest:
                flag('I6', e, 'decided on seq %s but %s%s last changed at seq %s' % (e.get('basis', 0), oid, '' if newest == o['touched'] else ' (or something under it)', newest))

        if k == 'org.set':
            if not str(by).startswith('human:'):
                flag('I8', e, 'only a person sets the chain of command')
            boss[e['actor']] = e.get('superior')
            if above(e['actor'], e.get('superior')):
                flag('I8', e, 'the chain of command loops at %s' % e['actor'])
            for x, c in sorted(orders.items()):
                if open_(c) and c['judge'] and above(c['to'], c['judge']):
                    flag('I10', e, 'the judge of the open order %s now works for the doer' % x)
        elif k == 'pool.set':
            if not str(by).startswith('human:'):
                flag('I8', e, 'only a person sets a pool')
            pools[e['pool']] = e['cap']
            used = sum(orders[x]['needs'].get(e['pool'], 0) for x in live)
            if used > e['cap']:
                flag('I7', e, 'pool %s cut to %s while live leases hold %s' % (e['pool'], e['cap'], used))
        elif k == 'order.issued':
            b = e['body']
            acc = b.get('accept') or {}
            if not acc.get('judge') or not acc.get('criteria'):
                flag('I10', e, 'order %s has no judge or no criteria' % b['id'])
            elif above(b['to'], acc['judge']):
                flag('I10', e, 'the judge of %s works for the doer' % b['id'])
            if any(not u.get('owner') for u in b.get('unverified') or []):
                flag('I10', e, 'an unverifiable part of %s has no owner' % b['id'])
            needs = dict(b.get('needs') or {})
            if any(isinstance(n, bool) or not isinstance(n, int) or n < 0 for n in needs.values()):
                flag('I7', e, 'order %s needs a negative or non-whole amount: %s' % (b['id'], needs))
            chain = []
            if b.get('parent') is None:
                if not str(by).startswith('human:') or not above(by, b['to']):
                    flag('I8', e, 'top-level order %s was opened by %s, who is not a person above %s' % (b['id'], by, b['to']))
            else:
                p, u = orders.get(b['parent']), e.get('under') or {}
                if p is None or u.get('order') != b['parent']:
                    flag('I8', e, 'sub-order %s is not under a lease on its parent' % b['id'])
                else:
                    chain = [b['parent']] + ups(b['parent'])
                    under(e, b['parent'], u.get('token'))
                    if not above(by, b['to']):
                        flag('I8', e, '%s ordered %s, who is not below it' % (by, b['to']))
                    if any(not any(inside(w, x) for w in p['writes']) for x in b.get('writes') or []):
                        flag('I8', e, 'sub-order %s writes outside its parent' % b['id'])
                    spent = sum(c['budget'] for c in orders.values() if c['parent'] == b['parent'] and c['st'] != 'CANCELLED')
                    if spent + b.get('budget', 0) > p['budget']:
                        flag('I8', e, 'sub-orders of %s exceed its budget' % b['parent'])
                    gone = [x for x in chain if not open_(orders[x])]
                    if gone:
                        flag('I8', e, 'sub-order %s was issued under %s, which is %s' % (b['id'], gone[0], orders[gone[0]]['st']))
                    for pool, n in sorted(needs.items()):
                        held = sum(orders[x]['needs'].get(pool, 0) for x in chain if open_(orders[x]))
                        if isinstance(n, int) and n > 0 and held + n > pools.get(pool, 0):
                            flag('I7', e, 'sub-order %s needs %s of %s while the orders above it hold %s of %s' % (b['id'], n, pool, held, pools.get(pool, 0)))
            after = list(b.get('after') or [])
            lost = [a for a in after if a not in orders or orders[a]['st'] in ENDED]
            if lost:
                flag('I9', e, '%s comes after %s, which does not exist or ended without succeeding' % (b['id'], lost[0]))
            loop = sorted(waits(after) & set(chain))
            if loop:
                flag('I9', e, '%s waits for %s, which cannot finish before %s does' % (b['id'], loop[0], b['id']))
            for r in b.get('reads') or []:    # an input to be handed in, from inside what the orders above write: someone who can finish first has to hand it in
                if r.get('released') and not any(x >= r['rev'] for x in handed_in.get(r['key'], ())) and any(inside(w, r['key']) for x in chain for w in orders[x]['writes']):
                    if not any(open_(c) and any(inside(w, r['key']) for w in c['writes']) and not (waits([y]) & set(chain)) for y, c in orders.items()):
                        flag('I9', e, '%s waits for %s to be handed in, and no open order can hand it in before %s ends' % (b['id'], r['key'], b['id']))
            if b['id'] in orders:
                flag('I1', e, 'order id %s issued twice' % b['id'])
            orders[b['id']] = {'parent': b.get('parent'), 'to': b['to'], 'issuer': by, 'writes': list(b.get('writes') or []),
                               'reads': list(b.get('reads') or []), 'after': after, 'needs': needs, 'outs': [],
                               'budget': b.get('budget', 0), 'judge': acc.get('judge'), 'st': 'PENDING', 'touched': e['seq'], 'holder': None}
            if b.get('parent') in orders:          # a new sub-order is news about the order it is under
                orders[b['parent']]['touched'] = e['seq']
        elif k == 'artifact.rev':
            cur = rev.get(e['key'], 0)
            if e.get('seen') != cur or e.get('rev') != cur + 1:
                flag('I6', e, '%s written on top of revision %s, but it was at %s' % (e['key'], e.get('seen'), cur))
            rev[e['key']] = e.get('rev')
            last_write = (e.get('cause'), e['key'], e.get('rev'))
            if o is None:
                flag('I3', e, 'write without an order')
            else:
                under(e, oid, e.get('token'))
                orphaned(e, oid, 'wrote')
                handed = [w for y in below(oid) for w in orders[y]['writes']]
                if not any(inside(w, e['key']) for w in o['writes']) or any(inside(w, e['key']) for w in handed):
                    flag('I4', e, '%s is outside what %s may write' % (e['key'], oid))
            want = sorted(x for x, c in orders.items() if open_(c) and any(r['key'] == e['key'] and r['rev'] < e['rev'] for r in c['reads']))
            told = sorted(n['order'] for n in events[idx + 1:idx + 1 + len(want) + 2] if n.get('kind') == 'notice.input-moved' and n.get('cause') == e.get('cause') and n.get('key') == e['key'])
            if want != told:
                flag('I9', e, 'input %s moved; should tell %s, told %s' % (e['key'], want, told))
        elif k == 'notice.input-moved':
            if last_write != (e.get('cause'), e.get('key'), e.get('rev')):
                flag('I9', e, 'a notice that %s moved, with no such write behind it' % e.get('key'))
            if o is None:
                flag('I9', e, 'a notice about an order nobody issued')
            elif e.get('to') != o['issuer']:
                flag('I9', e, 'the notice about %s went to %s, not to its issuer %s' % (oid, e.get('to'), o['issuer']))
        elif k == 'ask.raised':
            about, blocking = e.get('about'), bool(e.get('blocking'))
            if e.get('ask') in asks:
                flag('I1', e, 'question id %s used twice' % e.get('ask'))
            if blocking and about is not None:
                c = orders.get(about)
                if c is None or not (above(c['to'], by) or above(by, c['to']) or by == c['judge']):
                    flag('I8', e, '%s holds %s with a question but is not on it, above it, or its judge' % (by, about))
            asks[e.get('ask')] = {'st': 'OPEN', 'to': e.get('to'), 'blocking': blocking, 'about': about}
        elif k == 'ask.answered':
            q = asks.get(e.get('ask'))
            if q is None or q['st'] != 'OPEN':
                flag('I8', e, 'answered a question that is not open')
            elif not above(by, q['to']):
                flag('I8', e, '%s answered a question that was put to %s' % (by, q['to']))
            if q is not None:
                q['st'] = 'ANSWERED'
        elif o is None:
            flag('I1', e, 'event about an order nobody issued')
        elif k in ('order.amended', 'order.cancelled'):
            if e.get('cascade'):              # an event cannot vouch for itself: something above must have ended in this same request
                if k != 'order.cancelled' or not any(ended_by.get(x) == e.get('cause') for x in ups(oid)):
                    flag('I8', e, '%s was cancelled as a cascade, but nothing above it ended in the same request' % oid)
            elif not above(by, o['issuer']):
                flag('I8', e, '%s may not change %s' % (by, oid))
            if not open_(o):
                flag('I8', e, '%s was changed after it had ended (%s)' % (oid, o['st']))
            if k == 'order.amended' and set(e.get('patch') or {}) - {'priority', 'due'}:
                flag('I8', e, 'the inputs of %s were changed' % oid)
            if k == 'order.cancelled':
                o['st'] = 'CANCELLED'
                live.pop(oid, None)
                orphans.pop(oid, None)
                end(e, oid)
        elif k == 'lease.granted':
            if oid in live:
                flag('I2', e, '%s already has a live lease (holder %s)' % (oid, live[oid]['holder']))
            elif o['st'] != 'PENDING':        # judged, closed or cancelled work does not get a new doer
                flag({'JUDGING': 'I2', 'LEASED': 'I2', 'SUCCEEDED': 'I10', 'FAILED': 'I10'}.get(o['st'], 'I8'), e, '%s was leased while %s' % (oid, o['st']))
            if e['token'] <= last_token.get(oid, 0):
                flag('I3', e, 'token on %s did not go up' % oid)
            last_token[oid] = max(e['token'], last_token.get(oid, 0))
            if not above(o['to'], by):
                flag('I8', e, '%s is not on the team %s was sent to' % (by, oid))
            if o['judge'] and (by == o['judge'] or above(o['to'], o['judge'])):
                flag('I10', e, '%s is done by, or together with, its own judge %s' % (oid, o['judge']))
            orphaned(e, oid, 'was leased')
            if any(orders.get(a, {}).get('st') != 'SUCCEEDED' for a in o['after']) or any(rev.get(r['key'], 0) < r['rev'] for r in o['reads']):
                flag('I9', e, '%s started before what it depends on was done' % oid)
            if any(r.get('released') and not any(x >= r['rev'] for x in handed_in.get(r['key'], ())) for r in o['reads']):
                flag('I9', e, '%s started on an input that no finished order has handed in' % oid)
            if held_up(oid):
                flag('I9', e, '%s started while the blocking question %s about it was open' % (oid, held_up(oid)[0]))
            for x in live:
                if x != oid and not kin(x, oid) and any(clash(a, w) for a in orders[x]['writes'] for w in o['writes']):
                    flag('I4', e, '%s and %s may write the same place at the same time' % (oid, x))
            for p, n in o['needs'].items():
                if n + sum(orders[x]['needs'].get(p, 0) for x in live if x != oid) > pools.get(p, 0):
                    flag('I7', e, 'pool %s over-committed' % p)
            live[oid] = {'holder': by, 'token': e['token'], 'expires': e['expires']}
            o['st'], o['holder'] = 'LEASED', by
        elif k in ('lease.renewed', 'lease.released', 'report.progress', 'report.submitted'):
            under(e, oid, e.get('token'))
            if k == 'lease.renewed' and oid in live:
                live[oid]['expires'] = e['expires']
            if k == 'lease.released':
                live.pop(oid, None)
                o['st'] = 'PENDING'
            if k == 'report.submitted':
                orphaned(e, oid, 'was handed in')
                if below(oid):
                    flag('I8', e, '%s was handed in while %s under it is still open' % (oid, sorted(below(oid))[0]))
                if held_up(oid):
                    flag('I9', e, '%s was handed in while the blocking question %s about it was open' % (oid, held_up(oid)[0]))
                o['outs'] = [x for x in e.get('outputs') or [] if isinstance(x, dict)]
                if any(rev.get(x.get('key'), 0) < x.get('rev', 0) for x in o['outs']):
                    flag('I9', e, '%s hands in a revision that does not exist' % oid)
                live.pop(oid, None)
                o['st'] = 'JUDGING'
        elif k == 'lease.expired':
            l = live.pop(oid, None)
            if l is None or l['token'] != e.get('token') or l['expires'] > e['t']:
                flag('I3', e, 'expired a lease that was not live or not yet due')
            o['st'] = 'PENDING'
        elif k in ('order.succeeded', 'order.failed'):
            if o['st'] != 'JUDGING':
                flag('I10', e, '%s was closed without a submission to judge' % oid)
            if by != o['judge'] or by == o['holder'] or above(o['to'], by):
                flag('I10', e, '%s closed %s, but its judge is %s and the judge never does the work' % (by, oid, o['judge']))
            if k == 'order.succeeded':
                o['st'] = 'SUCCEEDED'
                for x in o['outs']:
                    handed_in.setdefault(x.get('key'), []).append(x.get('rev', 0))
            else:
                o['st'] = 'PENDING' if e.get('retry') else 'FAILED'
                if not e.get('retry'):
                    end(e, oid)
        elif k == 'order.dead':
            o['st'] = 'DEAD'
            live.pop(oid, None)
            end(e, oid)
        if o is not None and k in STATEFUL:
            o['touched'] = e['seq']
            if not open_(o) and o['parent'] in orders:       # ... and so is a sub-order ending
                orders[o['parent']]['touched'] = e['seq']
    if events:
        leftovers(events[-1], None)       # whatever was left under an ended order when the log stops
        overdue(events[-1])               # ... and a ledger may not stop half way through the clock's request
    return bad


def main(argv):
    try:
        events = [json.loads(line) for line in open(argv[0], encoding='utf-8') if line.strip()]
    except (IndexError, OSError, ValueError) as x:
        print('could not read the log: %s' % x)
        return 2
    bad = check(events)
    for i in IDS:
        print('%-3s %s' % (i, 'ok' if not bad[i] else '%d broken; first: %s' % (len(bad[i]), bad[i][0])))
    return 1 if any(bad.values()) else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
