#!/usr/bin/env python3
"""The way in from outside: ask a run folder for its state, or hand one dispatch/1 envelope to the dispatcher.

    python3 -I cli.py state <run> [--since N] [--limit N] [--at K] [--now T]   read only: rebuilt from <run>/ledger.jsonl, writes nothing
    python3 -I cli.py send  <run> <message.json | -> [--now T]                 one envelope in, the reply out
    python3 -I cli.py serve <run> --port P [--origin URL ...] [--now T]        HTTP on 127.0.0.1 only: GET /state, POST /message, OPTIONS

send exit codes: 0 taken, 1 refused by a rule (or another writer holds the run), 2 could not read it / not JSON / bad-shape.
state exit codes: 0, or 2 when the ledger cannot be read.

The dispatcher stays the only thing that decides and the only thing that makes events; this file only replays the ledger
into a Dispatcher, hands it the envelope, and appends whatever events the dispatcher added (the same line format gitws.save
writes).  One writer per run folder: send and serve hold an exclusive flock on <run>/.dispatch.lock while they write;
a second writer is turned away with the holder's description.  state takes no lock and opens nothing for writing.
serve never starts an agent or any other process.  Standard library only.

Which ledger: state says it as source.ledger (see fingerprint() below; null while the ledger has no rows), which is of the
first row only: two ledgers that begin with the same row and go on differently share it.  What a request is held against
is the chain (see chain() below): one value per row, each made from the value before it and that row's bytes, so the value
at row k stands for the first k rows.  state --at K (GET /state?at=K) gives it as source.at = {row, chain}; chain is null
when the ledger has no row K.  state --since N (GET /state?since=N) gives, beside `log`, `log_chain`: the value at each of
those rows, in the same order.  A POST /message may say which rows its envelope was built on in the header
X-Dispatch-Ledger: <k>:<the chain value at row k>.  When this run folder's ledger has fewer than k rows, or another value
at row k, or the header is not in that form (the bare fingerprint that was sent before is not), the answer is
412 {"cli": "other-ledger"} and the envelope is neither handed to the dispatcher nor written.  A k below the head with the
right value passes: the first k rows are these, and whether the envelope is out of date is the dispatcher's to say (basis).
Without the header nothing is compared."""
import argparse, fcntl, hashlib, json, os, re, sys, time
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import parse_qs, urlsplit

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import dispatcher  # noqa: E402

V = dispatcher.V
LEDGER, LOCK = 'ledger.jsonl', '.dispatch.lock'
MAX_BODY = 64 * 1024
BIND = '127.0.0.1'
LEDGER_HEADER = 'X-Dispatch-Ledger'
NAMED = re.compile('([1-9][0-9]{0,8}):([0-9a-f]{16})')     # <k>:<the chain value at row k>, held against the whole value (fullmatch)


class LedgerError(Exception):
    """The ledger cannot be read as one: a line that is not JSON, or numbers that do not run 1, 2, 3, ..."""


class Busy(Exception):
    def __init__(self, holder):
        Exception.__init__(self, 'another writer holds this run folder')
        self.holder = holder


class Moved(Exception):
    """The ledger changed under a writer that holds the lock: someone wrote without it."""


class OtherLedger(Exception):
    """The sender said which rows it built its envelope on (`named`: "<k>:<the chain value at row k>") and this run folder's
    ledger, which has `rows` rows, is not that: it has another value at row k (`held`), or fewer than k rows (`held` is
    None), or `named` is not in that form at all (`row` and `value` are None too)."""

    def __init__(self, named, rows, row=None, value=None, held=None):
        has = 'no rows yet' if rows == 0 else '%d row%s' % (rows, '' if rows == 1 else 's')
        if row is None:
            text = ('the request names %r, which is not <row>:<the chain value at that row> (a row number from 1 with no '
                    'leading zero, a colon, 16 lowercase hex digits); this ledger has %s' % (named, has))
        elif held is None:
            text = 'the request names row %d with chain value %r; this ledger is shorter than that: it has %s' % (row, value, has)
        else:
            text = 'the request names row %d with chain value %r; this ledger has %r at row %d' % (row, value, held, row)
        Exception.__init__(self, text + '; nothing was sent')
        self.named, self.rows, self.row, self.value, self.held = named, rows, row, value, held


def fingerprint(data):
    """Which ledger these bytes are: the first 16 hex digits of sha256 over the first line, without the b'\\n' that ends it.
    None for a ledger with no rows.  Not the folder's name (two runs can both sit in a folder called r4), not the whole
    file (it grows) and not the row parsed and written out again: the bytes of the first row, which stay as they are once
    written.  The same ledger copied elsewhere has the same fingerprint; so do two ledgers that begin with the very same
    row and go on differently, which is why a request is held against chain() below and not against this.  It is the
    first value of that chain."""
    return hashlib.sha256(data.split(b'\n', 1)[0]).hexdigest()[:16] if data else None


def chain(data, last=None):
    """One value per row of these ledger bytes: which ledger the rows up to and including that row are.  The rows are
    data.split(b'\n')[:-1], as bytes, without the b'\n' that ends each.  The first value is fingerprint(data); each later
    one is the first 16 hex digits of sha256 over the value before it (as ASCII), b'\n', and that row's bytes.  So two
    ledgers have the same value at row k only when their first k rows are the same bytes: one that begins with the same
    row and goes on differently has another value from the row where it differs.  [] for no bytes.
    `last`: the value of the row just before these bytes, when they are rows appended to a ledger that has rows already
    (the writer goes on from the value it holds, with the bytes it appends)."""
    out = []
    for line in data.split(b'\n')[:-1]:
        last = hashlib.sha256((last.encode('ascii') + b'\n' if last is not None else b'') + line).hexdigest()[:16]
        out.append(last)
    return out


def read_ledger(run, fp=False, chained=False):
    """Every event, in order.  A run folder with no ledger yet is a blank one (an empty ledger).
    With fp=True: (events, fingerprint).  With chained=True: (events, fingerprint, chain).  All from the same one read of
    the file."""
    path = os.path.join(run, LEDGER)
    if not os.path.isdir(run):
        raise LedgerError('no such run folder: %s' % run)
    if not os.path.exists(path):
        if chained:
            return [], None, []
        return ([], None) if fp else []
    with open(path, 'rb') as f:
        data = f.read()
    if data and not data.endswith(b'\n'):
        raise LedgerError('%s does not end with a newline: the last line may be half written' % path)
    events = []
    for i, line in enumerate(data.split(b'\n')[:-1], 1):
        try:
            e = json.loads(line.decode('utf-8'))
        except ValueError as x:
            raise LedgerError('%s line %d is not JSON: %s' % (path, i, x))
        if not isinstance(e, dict) or e.get('seq') != i:
            raise LedgerError('%s line %d: expected an event with seq %d' % (path, i, i))
        events.append(e)
    if chained:
        return events, fingerprint(data), chain(data)
    return (events, fingerprint(data)) if fp else events


def state(run, now, since=None, limit=dispatcher.PAGE, at=None):
    """What state.query {} would answer, replayed from the file, plus a short summary.  The clock is not run: a lease
    whose time is up stays in `state` (the dispatcher records it as expired on the next request) and is flagged here.
    `at`: a row number; source.at then says which ledger the first `at` rows are, {row, chain} (see chain(); chain is None
    when the ledger has no such row), from the same one read of the file as everything else here.  Without it source has
    no `at`.
    `since`: with the rows after it (`log`) comes `log_chain`, one chain value per row of `log` in the same order, each
    taken by that row's seq, from that same one read.  Without it there is neither."""
    events, fp, links = read_ledger(run, chained=True)
    d = dispatcher.Dispatcher(events=events)
    s, snap = d.s, d.snapshot()
    out = {'v': V, 'run': os.path.abspath(run), 'rows': len(events), 'now': now,
           'source': {'head': s.head, 't': s.now, 'stale': False, 'from': LEDGER, 'ledger': fp}, 'state': snap,
           'summary': {
               'org': snap['org'],
               'orders': [dict({'id': oid, 'state': o['state'], 'holder': (s.leases.get(oid) or {}).get('holder'), 'to': o['to'],
                                'parent': o.get('parent'), 'title': o.get('title', ''), 'attempt': o['attempt'],
                                'judge': (o.get('accept') or {}).get('judge')},
                               **{k: o[k] for k in ('skills', 'knowledge') if k in o}) for oid, o in sorted(s.orders.items())],
               'leases': [{'order': oid, 'holder': l['holder'], 'token': l['token'], 'expires': l['expires'], 'expired': l['expires'] <= now}
                          for oid, l in sorted(s.leases.items())],
               'waiting_for_human': [a for _, a in sorted(snap['asks'].items()) if str(a.get('to', '')).startswith('human:')]}}
    if since is not None:
        limit = max(0, min(limit, dispatcher.PAGE))
        log = d.log[since:since + limit]
        out.update(log=log, log_chain=[links[e['seq'] - 1] for e in log], more=since + limit < len(d.log),
                   next=log[-1]['seq'] if log else since)
    if at is not None:
        out['source']['at'] = {'row': at, 'chain': links[at - 1] if 1 <= at <= len(links) else None}
    return out


def take_lock(run, info):
    fd = os.open(os.path.join(run, LOCK), os.O_RDWR | os.O_CREAT, 0o644)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        try:
            holder = json.loads(os.read(fd, 4096).decode('utf-8') or '{}')
        except ValueError:
            holder = {}
        os.close(fd)
        raise Busy(holder)
    os.ftruncate(fd, 0)
    os.lseek(fd, 0, os.SEEK_SET)
    os.write(fd, json.dumps(info, ensure_ascii=False).encode('utf-8'))
    return fd


class Writer:
    """The one writer of a run folder while it lives: holds the lock, keeps the dispatcher in memory, and appends what each
    request added to the ledger before the reply goes out.  `chain` is the chain of the ledger it read (see chain()), from
    the same read as the events the dispatcher was rebuilt from, and carried on with the bytes of every row it has appended
    since: the file is not read again to learn it."""

    def __init__(self, run, info):
        if not os.path.isdir(run):
            raise LedgerError('no such run folder: %s' % run)
        self.run, self.path = run, os.path.join(run, LEDGER)
        self.fd = take_lock(run, dict(info, pid=os.getpid(), since=int(time.time())))
        try:
            events, _, self.chain = read_ledger(run, chained=True)
            self.d = dispatcher.Dispatcher(events=events)
        except Exception:
            self.close()
            raise
        self.mark = self._stat()

    def _stat(self):
        try:
            st = os.stat(self.path)
            return (st.st_ino, st.st_size, st.st_mtime_ns)
        except FileNotFoundError:
            return None

    def hold(self, named):
        """Raise OtherLedger unless `named` is "<k>:<c>" and this writer's ledger has a row k whose chain value is c."""
        at = NAMED.fullmatch(named) if isinstance(named, str) else None
        if at is None:
            raise OtherLedger(named, len(self.chain))
        k, c = int(at.group(1)), at.group(2)
        held = self.chain[k - 1] if k <= len(self.chain) else None
        if held != c:
            raise OtherLedger(named, len(self.chain), k, c, held)

    def submit(self, m, now, named=None):
        """`named`: which rows the sender built this envelope on, "<k>:<the chain value at row k>", or None when it did not
        say.  It is held against the chain this writer keeps (of the ledger it read and has written since, checked just
        above to be what is still on disk), under the lock and before the dispatcher sees the envelope: OtherLedger means
        nothing was handed over and nothing was written.  A k below the head with the right value passes."""
        if self._stat() != self.mark:
            raise Moved('%s changed since this writer read it: someone wrote without the lock; nothing was sent' % self.path)
        if named is not None:
            self.hold(named)
        before = len(self.d.log)
        reply = self.d.submit(m, now)
        new = self.d.log[before:]                  # the request's own events, and the clock's (kept even when the request is refused)
        if new:
            data = ''.join(json.dumps(e, ensure_ascii=False) + '\n' for e in new).encode('utf-8')
            more = chain(data, self.chain[-1] if self.chain else None)     # of the very bytes appended below
            fd = os.open(self.path, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
            try:
                while data:
                    data = data[os.write(fd, data):]
                os.fsync(fd)
            finally:
                os.close(fd)
            self.chain = self.chain + more
        self.mark = self._stat()
        return reply

    def close(self):
        if self.fd is not None:
            fcntl.flock(self.fd, fcntl.LOCK_UN)
            os.close(self.fd)
            self.fd = None


def exit_code(reply):
    if reply.get('ok'):
        return 0
    return 2 if reply.get('code') == 'bad-shape' else 1


def busy_text(holder):
    how = ' (POST to %s/message instead)' % holder['url'] if holder.get('url') else ''
    return 'another writer holds this run folder: %s%s' % (json.dumps(holder, ensure_ascii=False), how)


def dump(v, f=sys.stdout):
    f.write(json.dumps(v, ensure_ascii=False, indent=1) + '\n')
    f.flush()


# ---- HTTP

class Handler(BaseHTTPRequestHandler):
    server_version = 'dispatch-cli/1'
    timeout = 10

    def log_message(self, fmt, *args):
        if not self.server.quiet:
            sys.stderr.write('%s %s\n' % (self.log_date_time_string(), fmt % args))

    def _origin_ok(self):
        o = self.headers.get('Origin')
        return o is None or o in self.server.origins

    def _host_ok(self):
        h = self.headers.get('Host')
        port = self.server.server_address[1]
        return h is None or h in ('%s:%d' % (BIND, port), 'localhost:%d' % port)

    def _send(self, code, body, extra=()):
        data = json.dumps(body, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Vary', 'Origin')
        o = self.headers.get('Origin')
        if o is not None and o in self.server.origins:
            self.send_header('Access-Control-Allow-Origin', o)
        for k, v in extra:
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(data)

    def _gate(self):
        if not self._host_ok():
            self._send(403, {'cli': 'bad-host', 'detail': 'only 127.0.0.1 or localhost on this port'})
            return False
        if not self._origin_ok():
            self._send(403, {'cli': 'bad-origin', 'detail': 'this origin is not on the --origin list'})
            return False
        return True

    def do_OPTIONS(self):
        if not self._gate():
            return
        if urlsplit(self.path).path not in ('/state', '/message'):
            return self._send(404, {'cli': 'not-found'})
        self.send_response(204)
        self.send_header('Vary', 'Origin')
        o = self.headers.get('Origin')
        if o is not None and o in self.server.origins:
            self.send_header('Access-Control-Allow-Origin', o)
        for k, v in (('Access-Control-Allow-Methods', 'GET, POST, OPTIONS'), ('Access-Control-Allow-Headers', 'Content-Type, ' + LEDGER_HEADER),
                     ('Access-Control-Max-Age', '600'), ('Allow', 'GET, POST, OPTIONS')):
            self.send_header(k, v)
        self.end_headers()

    def do_GET(self):
        if not self._gate():
            return
        u = urlsplit(self.path)
        if u.path != '/state':
            return self._send(404, {'cli': 'not-found'})
        q = parse_qs(u.query)
        try:
            since = int(q['since'][0]) if 'since' in q else None
            limit = int(q['limit'][0]) if 'limit' in q else dispatcher.PAGE
            at = int(q['at'][0]) if 'at' in q else None
            if since is not None and since < 0:
                raise ValueError(since)
            if at is not None and at < 0:
                raise ValueError(at)
        except ValueError:
            return self._send(400, {'cli': 'bad-query', 'detail': 'since, limit and at are non-negative integers'})
        try:
            self._send(200, state(self.server.run, self.server.clock(), since, limit, at))
        except LedgerError as x:
            self._send(500, {'cli': 'bad-ledger', 'detail': str(x)})

    def _message_allowed(self, message):
        """HTTP applications may refuse an envelope before it reaches the ledger writer."""
        return True

    def do_POST(self):
        if not self._gate():
            return
        if urlsplit(self.path).path != '/message':
            return self._send(404, {'cli': 'not-found'})
        n = self.headers.get('Content-Length')
        if n is None or not n.isdigit():
            return self._send(411, {'cli': 'length-required', 'detail': 'send a Content-Length (no chunked bodies)'})
        if int(n) > MAX_BODY:
            self.close_connection = True
            return self._send(413, {'cli': 'too-large', 'detail': 'one envelope is at most %d bytes' % MAX_BODY})
        raw = self.rfile.read(int(n))
        try:
            m = json.loads(raw.decode('utf-8'))
        except ValueError as x:
            return self._send(400, {'cli': 'bad-json', 'detail': str(x)})
        if not self._message_allowed(m):
            return
        # which rows this envelope was built on, when the sender says: as HTTP reads a field value, the spaces and tabs
        # around it are not part of it and a field sent twice is one value joined by ", " (so never <k>:<chain value>)
        named = self.headers.get_all(LEDGER_HEADER)
        named = None if named is None else ', '.join(v.strip(' \t') for v in named)
        try:
            self._send(200, self.server.writer.submit(m, self.server.clock(), named))
        except Moved as x:
            self._send(409, {'cli': 'moved', 'detail': str(x)})
        except OtherLedger as x:
            self._send(412, {'cli': 'other-ledger', 'detail': str(x)})


class Server(HTTPServer):
    """One request at a time (no threads): the HTTP side is serialized as the dispatcher is."""

    def __init__(self, run, port, origins, clock=None, quiet=False):
        self.run, self.origins, self.quiet = run, set(origins), quiet
        self.clock = clock or (lambda: int(time.time()))
        HTTPServer.__init__(self, (BIND, port), Handler)
        try:
            self.writer = Writer(run, {'mode': 'serve', 'url': 'http://%s:%d' % (BIND, self.server_address[1])})
        except Exception:
            self.server_close()
            raise

    def server_close(self):
        HTTPServer.server_close(self)
        if getattr(self, 'writer', None) is not None:
            self.writer.close()


def check_origin(o):
    u = urlsplit(o)
    if o == '*' or u.scheme not in ('http', 'https') or not u.netloc or u.path or u.query or u.fragment:
        raise argparse.ArgumentTypeError('an origin is scheme://host[:port] with nothing after it, and never *: %r' % o)
    return o


def main(argv):
    p = argparse.ArgumentParser(prog='cli.py', description=__doc__.split('\n')[0])
    sub = p.add_subparsers(dest='cmd')
    a = sub.add_parser('state', help='read only: the state rebuilt from <run>/ledger.jsonl')
    a.add_argument('run')
    a.add_argument('--since', type=int)
    a.add_argument('--limit', type=int, default=dispatcher.PAGE)
    a.add_argument('--at', type=int, help='a row number: source.at then says which ledger the first AT rows are (see chain())')
    a.add_argument('--now', type=int, help='the clock used to flag leases whose time is up (default: wall clock, seconds)')
    a = sub.add_parser('send', help='hand one envelope to the dispatcher and print its reply')
    a.add_argument('run')
    a.add_argument('message', help='a file with one JSON envelope, or - for stdin')
    a.add_argument('--now', type=int, help="the dispatcher's clock for this request (default: wall clock, seconds)")
    a = sub.add_parser('serve', help='HTTP on 127.0.0.1: GET /state, POST /message')
    a.add_argument('run')
    a.add_argument('--port', type=int, required=True)
    a.add_argument('--origin', action='append', default=[], type=check_origin, help='a browser origin allowed to call (repeatable)')
    a.add_argument('--now', type=int, help='a fixed clock (tests); default: wall clock, seconds')
    a.add_argument('--quiet', action='store_true')
    args = p.parse_args(argv)
    now = (lambda: args.now) if getattr(args, 'now', None) is not None else (lambda: int(time.time()))

    if args.cmd == 'state':
        if args.since is not None and args.since < 0:
            p.error('--since is a non-negative integer')
        if args.at is not None and args.at < 0:
            p.error('--at is a non-negative integer')
        try:
            dump(state(args.run, now(), args.since, args.limit, args.at))
        except LedgerError as x:
            print('cli: %s' % x, file=sys.stderr)
            return 2
        return 0

    if args.cmd == 'send':
        try:
            raw = sys.stdin.read() if args.message == '-' else open(args.message, encoding='utf-8').read()
            m = json.loads(raw)
        except (OSError, ValueError) as x:
            print('cli: could not read one JSON envelope from %s: %s; nothing was sent' % (args.message, x), file=sys.stderr)
            return 2
        try:
            w = Writer(args.run, {'mode': 'send'})
        except Busy as x:
            dump({'cli': 'busy', 'detail': busy_text(x.holder), 'holder': x.holder})
            return 1
        except LedgerError as x:
            print('cli: %s; nothing was sent' % x, file=sys.stderr)
            return 2
        try:
            reply = w.submit(m, now())
        finally:
            w.close()
        dump(reply)
        if not reply.get('ok'):
            print('cli: refused: %s %s' % (reply.get('code'), reply.get('detail', '')), file=sys.stderr)
        return exit_code(reply)

    if args.cmd == 'serve':
        try:
            srv = Server(args.run, args.port, args.origin, clock=now, quiet=args.quiet)
        except Busy as x:
            print('cli: %s' % busy_text(x.holder), file=sys.stderr)
            return 1
        except (LedgerError, OSError) as x:
            print('cli: %s' % x, file=sys.stderr)
            return 2
        print('serving %s on http://%s:%d (GET /state, POST /message); origins: %s' % (
            os.path.abspath(args.run), BIND, srv.server_address[1], ', '.join(sorted(srv.origins)) or 'none'), flush=True)
        try:
            srv.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            srv.server_close()
        return 0

    p.print_help()
    return 2


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
