#!/usr/bin/env python3
"""Central dispatcher: the only writer of an append-only log; state = fold(log).
A human click, a typed prompt and an agent's request all arrive as the same envelope (an "intent").
Every envelope is checked against schema/message.json at the door.  The dispatcher either appends events and acks,
or nacks with a reason code and leaves nothing of that request in the log (the clock's own lease.expired /
order.dead lines, cause "clock:*", are not part of any request and stay).  One request at a time: submit() is serialized.
Every protection is a named guard so that a test can take it away (see tests/sim.py, tests/test_dispatch.py).
Standard library only.  The message and event formats are the JSON schemas in schema/."""
import copy, hashlib, importlib.util, json, os, re, threading

V = 'dispatch/1'
GUARDS = ('dedupe', 'one-lease', 'fence', 'in-scope', 'scope', 'basis', 'expect', 'capacity',
          'authority', 'subset', 'members', 'deps', 'judge', 'notice')
KINDS = ('org.set', 'pool.set', 'order.issue', 'order.amend', 'order.cancel', 'order.propose', 'claim.request',
         'lease.renew', 'lease.release', 'artifact.put', 'report.progress', 'report.submit', 'verdict',
         'ask.raise', 'ask.answer', 'state.query')
OPEN = ('PENDING', 'LEASED', 'JUDGING')
# whatever a decision about an order can hang on moves its `touched`; a renewal is only a heartbeat and does not.
# A sub-order being issued, or ending, is such a thing for the order directly above it (the second review pass: an
# ended sub-order is no longer among the open ones a cancel looks at, and an amend never looked below at all)
TOUCH = ('order.issued', 'order.amended', 'order.cancelled', 'lease.granted', 'lease.released', 'lease.expired',
         'artifact.rev', 'report.progress', 'report.submitted', 'order.succeeded', 'order.failed', 'order.dead')
MAX_TTL, MAX_ATTEMPTS, PAGE = 3600, 3, 500
DEFAULTS = {'parent': None, 'title': '', 'goal': '', 'writes': [], 'reads': [], 'after': [], 'needs': {}, 'budget': 0,
            'priority': 0, 'due': None, 'accept': {}, 'unverified': []}
# three shape faults have a rule and a reason of their own, so the door lets them through to it:
# no judge / criteria / owner -> the judge guard (no-judge); a patch that touches more than priority and due -> immutable
LEFT_TO_RULES = re.compile(r'^\$\.body(\.accept)?: missing (accept|judge|criteria)$|^\$\.body\.unverified\[\d+\]: missing (what|owner)$|^\$\.body\.patch: unexpected ')


def _validator():
    spec = importlib.util.spec_from_file_location('dispatch_validate', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'schema', 'validate.py'))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


validate = _validator()


class Nack(Exception):
    def __init__(self, code, detail=''):
        Exception.__init__(self, code)
        self.code, self.detail = code, detail


def must(cond, code, detail=''):
    if not cond:
        raise Nack(code, detail)


def covers(scope, key):
    """'a/b/' covers everything under it; 'a/b' covers exactly itself."""
    return key == scope or (scope.endswith('/') and key.startswith(scope))


def overlap(a, b):
    return covers(a, b) or covers(b, a)


def digest(m):
    return hashlib.sha256(json.dumps({k: v for k, v in m.items() if k != 'ts'}, sort_keys=True, ensure_ascii=False).encode()).hexdigest()[:16]


class State:
    def __init__(self):
        self.org, self.pools, self.orders, self.leases, self.arts, self.asks, self.seen = {}, {}, {}, {}, {}, {}, {}
        self.released = {}                          # key -> the revisions some SUCCEEDED order handed in
        self.head, self.now = 0, 0


def apply(s, e):
    """The only place state changes.  Replaying the log through this rebuilds everything."""
    k, s.head, s.now = e['kind'], e['seq'], e['t']
    s.seen.setdefault(e['cause'], {'h': e.get('h'), 'seqs': []})['seqs'].append(e['seq'])
    o = s.orders.get(e.get('order'))
    if k == 'org.set':
        s.org[e['actor']] = e['superior']
    elif k == 'pool.set':
        s.pools[e['pool']] = e['cap']
    elif k == 'order.issued':
        s.orders[e['body']['id']] = dict(e['body'], issuer=e['by'], state='PENDING', attempt=1, token=0, touched=e['seq'])
        if e['body'].get('parent') in s.orders:
            s.orders[e['body']['parent']]['touched'] = e['seq']
    elif k == 'artifact.rev':
        s.arts[e['key']] = e['rev']
    elif k == 'ask.raised':
        s.asks[e['ask']] = {'id': e['ask'], 'by': e['by'], 'to': e['to'], 'text': e['text'], 'about': e.get('about'),
                            'proposal': e.get('proposal'), 'blocking': e.get('blocking', False), 'state': 'OPEN', 'touched': e['seq']}
    elif k == 'ask.answered':
        s.asks[e['ask']].update(state='ANSWERED', answer=e['answer'], touched=e['seq'])
    elif o is None:
        return
    elif k == 'order.amended':
        o.update(e['patch'])
    elif k == 'order.cancelled':
        o['state'] = 'CANCELLED'
        s.leases.pop(o['id'], None)
    elif k == 'lease.granted':
        o['state'], o['token'] = 'LEASED', e['token']
        s.leases[o['id']] = {'holder': e['by'], 'token': e['token'], 'expires': e['expires']}
    elif k == 'lease.renewed':
        if o['id'] in s.leases:
            s.leases[o['id']]['expires'] = e['expires']
    elif k in ('lease.released', 'lease.expired'):
        if s.leases.pop(o['id'], None) is not None or o['state'] == 'LEASED':
            o['state'] = 'PENDING'
            o['attempt'] += k == 'lease.expired'
    elif k == 'report.progress':
        o['pct'], o['note'] = e.get('pct'), e.get('note')
    elif k == 'report.submitted':
        s.leases.pop(o['id'], None)
        o['state'], o['outputs'], o['submitter'] = 'JUDGING', e['outputs'], e['by']
    elif k == 'order.succeeded':
        o['state'] = 'SUCCEEDED'
        for x in o.get('outputs') or []:
            if x['rev'] not in s.released.setdefault(x['key'], []):
                s.released[x['key']].append(x['rev'])
    elif k == 'order.failed':
        o['state'] = 'PENDING' if e['retry'] else 'FAILED'
        o['attempt'] += bool(e['retry'])
    elif k == 'order.dead':
        o['state'] = 'DEAD'
    if o is not None and k in TOUCH:
        o['touched'] = e['seq']
        if o['state'] not in OPEN and o.get('parent') in s.orders:
            s.orders[o['parent']]['touched'] = e['seq']


class Dispatcher:
    def __init__(self, guards=GUARDS, events=()):
        self.g, self.s, self.log, self._lock = set(guards), State(), [], threading.RLock()
        for e in copy.deepcopy(list(events)):       # the ledger is the dispatcher's own; whoever handed these in may go on changing theirs
            self.log.append(e)
            apply(self.s, e)

    # ---- plumbing
    def need(self, guard, cond, code, detail=''):
        if guard in self.g and not cond:
            raise Nack(code, detail)

    def _begin(self, cause, h, by, now):
        self._cause, self._h, self._by, self._now, self._n, self._seqs = cause, h, by, now, 0, []

    def _emit(self, kind, **payload):
        e = {'seq': self.s.head + 1, 't': self._now, 'kind': kind, 'cause': self._cause, 'n': self._n, 'by': self._by}
        if self._n == 0 and self._h:
            e['h'] = self._h
        e.update(payload)
        self._n += 1
        self._seqs.append(e['seq'])
        self.log.append(e)
        apply(self.s, e)

    def _undo(self, mark):
        """A request that is refused, or that crashes half way, leaves none of its own events behind."""
        if len(self.log) > mark:
            del self.log[mark:]
            self.s = State()
            for e in self.log:
                apply(self.s, e)

    def _again(self, seqs):
        """What the first answer to this id carried, rebuilt from the events it caused (the first reply may have been lost)."""
        out = {}
        for e in (self.log[q - 1] for q in seqs if 0 < q <= len(self.log)):
            if e['kind'] in ('lease.granted', 'lease.renewed'):
                out['lease'] = {'order': e['order'], 'token': e['token'], 'expires': e['expires']}
            elif e['kind'] == 'artifact.rev':
                out['rev'] = e['rev']
        return out

    def chain(self, actor):
        out = []
        while actor in self.s.org and self.s.org[actor] and self.s.org[actor] not in out:
            actor = self.s.org[actor]
            out.append(actor)
        return out

    def over(self, a, b):
        """a is b, or a is somewhere above b in the chain of command."""
        return a == b or a in self.chain(b)

    def _order(self, b):
        must(b.get('order') in self.s.orders, 'unknown', 'no such order')
        return self.s.orders[b['order']]

    def _lease(self, m):
        le = m.get('lease') or {}
        must(le.get('order') in self.s.orders, 'unknown', 'a write under a lease names the order and the token')
        l = self.s.leases.get(le['order'])
        self.need('fence', l is not None and l['token'] == le.get('token') and l['holder'] == m['from'], 'fenced', 'not the current lease')
        return self.s.orders[le['order']], le.get('token')

    def _family(self, oid):
        fam, up = {oid}, self.s.orders[oid].get('parent')
        while up in self.s.orders and up not in fam:
            fam.add(up)
            up = self.s.orders[up].get('parent')
        grew = True
        while grew:
            more = {o['id'] for o in self.s.orders.values() if o.get('parent') in fam and o['id'] not in fam and self._below(o['id'], oid)}
            grew = bool(more)
            fam |= more
        return fam

    def _below(self, oid, top):
        seen = set()
        while oid in self.s.orders and oid not in seen:
            if oid == top:
                return True
            seen.add(oid)
            oid = self.s.orders[oid].get('parent')
        return False

    def _above(self, oid):
        """The order and everything above it, nearest first."""
        out = []
        while oid in self.s.orders and oid not in out:
            out.append(oid)
            oid = self.s.orders[oid].get('parent')
        return out

    def _open_below(self, oid):
        """Every open order anywhere under this one (not only its direct sub-orders)."""
        return [x for x in sorted(self.s.orders) if x != oid and self.s.orders[x]['state'] in OPEN and self._below(x, oid)]

    def _waits_on(self, start):
        """Everything the orders in `start` cannot finish before: what they come after, and their own open sub-orders."""
        s, seen, todo = self.s, set(), list(start)
        while todo:
            x = todo.pop()
            if x in seen or x not in s.orders or s.orders[x]['state'] == 'SUCCEEDED':
                continue
            seen.add(x)
            todo += s.orders[x]['after'] + [c['id'] for c in s.orders.values() if c.get('parent') == x and c['state'] in OPEN]
        return seen

    def _can_hand_in(self, key, ups):
        """The open orders that could hand `key` in before the orders in `ups` end: it is theirs to write, and they wait for none of those."""
        return sorted(x['id'] for x in self.s.orders.values() if x['state'] in OPEN and any(covers(w, key) for w in x['writes'])
                      and not (self._waits_on([x['id']]) & set(ups)))

    def _questions(self, oid):
        return [a for a in self.s.asks.values() if a['state'] == 'OPEN' and a['blocking'] and a['about'] == oid]

    def tick(self, now):
        """Leases end on the dispatcher's clock, never on the holder's.  An order that dies takes what is under it along."""
        with self._lock:
            now = max(now, self.s.now)
            self._begin('clock:%d' % (self.s.head + 1), None, 'dispatcher', now)
            for oid, l in sorted(self.s.leases.items()):
                if oid in self.s.leases and l['expires'] <= now:
                    self._emit('lease.expired', order=oid, token=l['token'])
                    if self.s.orders[oid]['attempt'] > MAX_ATTEMPTS:
                        self._emit('order.dead', order=oid)
                        for x in self._open_below(oid):
                            self._emit('order.cancelled', order=x, cascade=True)
            return now

    def submit(self, m, now):
        """One request in, one reply out, nothing else in between.  Refused or crashed: none of its events stay.
        What comes in is copied before it is used and what goes out is a copy: changing a message after it was sent,
        or a reply after it was received, changes nothing in here."""
        with self._lock:
            return copy.deepcopy(self._submit(m, now))

    def _submit(self, m, now):
        now = self.tick(now)
        mark = len(self.log)
        mid = m['id'] if isinstance(m, dict) and isinstance(m.get('id'), str) else ''
        try:
            must(isinstance(m, dict), 'bad-shape', 'a message is one JSON object')
            m = copy.deepcopy(m)
            errs = [x for x in validate.errors(m, validate.load('message')) if not LEFT_TO_RULES.match(x)]
            must(not errs, 'bad-shape', errs[0] if errs else '')
            must(not m['id'].startswith('clock:'), 'bad-shape', 'ids that start with clock: are the dispatcher\'s own')
            h, old = digest(m), self.s.seen.get(m['id'])
            if old and 'dedupe' in self.g:
                must(old['h'] == h, 'id-reuse', 'same id, different content')
                return dict({'v': V, 're': mid, 'ok': True, 'dup': True, 'seq': self.s.head, 'events': old['seqs']}, **self._again(old['seqs']))
            self._begin(m['id'], h, m['from'], now)
            extra = getattr(self, 'do_' + m['kind'].replace('.', '_'))(m, m['body']) or {}
            return dict({'v': V, 're': mid, 'ok': True, 'seq': self.s.head, 'events': self._seqs}, **extra)
        except Nack as x:
            self._undo(mark)
            return {'v': V, 're': mid, 'ok': False, 'seq': self.s.head, 'code': x.code, 'detail': x.detail}
        except Exception as x:                      # a bug in a handler must not leave half a request in the log
            self._undo(mark)
            return {'v': V, 're': mid, 'ok': False, 'seq': self.s.head, 'code': 'internal', 'detail': '%s; nothing was written' % type(x).__name__}

    # ---- setup: who reports to whom, and how much of each shared thing there is
    def do_org_set(self, m, b):
        s, org = self.s, dict(self.s.org, **{b['actor']: b.get('superior')})
        self.need('authority', m['from'].startswith('human:'), 'no-authority')

        def ups(x):
            out = []
            while org.get(x) and org[x] not in out:
                x = org[x]
                out.append(x)
            return out
        must(b['actor'] not in ups(b['actor']), 'bad-shape', 'the chain of command cannot loop')
        for o in sorted((o for o in s.orders.values() if o['state'] in OPEN), key=lambda o: o['id']):
            j = (o.get('accept') or {}).get('judge')
            self.need('judge', not j or not (j == o['to'] or o['to'] in ups(j)), 'no-judge',
                      '%s judges the open order %s and cannot be placed under its addressee' % (j, o['id']))
        self._emit('org.set', actor=b['actor'], superior=b.get('superior'))

    def do_pool_set(self, m, b):
        self.need('authority', m['from'].startswith('human:'), 'no-authority')
        used = sum(self.s.orders[x]['needs'].get(b['pool'], 0) for x in self.s.leases)
        self.need('capacity', b['cap'] >= used, 'over-capacity', '%d of %s are in use under leases; wait for them or cancel first' % (used, b['pool']))
        self._emit('pool.set', pool=b['pool'], cap=b['cap'])

    # ---- orders
    def do_order_issue(self, m, b):
        s = self.s
        must(b['id'] not in s.orders, 'exists')
        o = dict(DEFAULTS, **b)
        acc = o['accept'] if isinstance(o['accept'], dict) else {}
        self.need('judge', bool(acc.get('judge')) and bool(acc.get('criteria')) and not self.over(o['to'], acc.get('judge'))
                  and all(isinstance(u, dict) and u.get('what') and u.get('owner') for u in o['unverified']), 'no-judge',
                  'name a judge who is not the addressee, the criteria, and an owner for whatever cannot be checked')
        self.need('deps', all(a in s.orders for a in o['after']), 'unknown', 'it comes after an order that does not exist')
        self.need('deps', not any(s.orders[a]['state'] in ('CANCELLED', 'FAILED', 'DEAD') for a in o['after'] if a in s.orders), 'closed',
                  'it comes after an order that ended without succeeding, so it could never start')
        extra = {}
        if o['parent'] is None:
            self.need('authority', m['from'].startswith('human:') and self.over(m['from'], o['to']), 'no-authority',
                      'only a person opens a top-level order, and only for someone under them')
        else:
            must(o['parent'] in s.orders and s.orders[o['parent']]['state'] in OPEN, 'no-parent')
            must((m.get('lease') or {}).get('order') == o['parent'], 'fenced', 'a sub-order is issued under the lease on its parent')
            po, tok = self._lease(m)
            self.need('authority', self.over(m['from'], o['to']), 'no-authority', 'orders go down the chain; sideways requests go up as proposals')
            kids = [c for c in s.orders.values() if c.get('parent') == po['id'] and c['state'] != 'CANCELLED']
            self.need('subset', all(any(covers(w, x) for w in po['writes']) for x in o['writes'])
                      and sum(c['budget'] for c in kids) + o['budget'] <= po['budget'], 'not-subset', 'scope and budget stay inside the parent')
            ups = self._above(po['id'])
            self.need('deps', not (self._waits_on(o['after']) & set(ups)), 'dependency-cycle',
                      'it would wait for an order that cannot finish before it does')
            for r in o['reads']:                    # an input to be handed in, from inside what the orders above write: they hand in only when they pass,
                if r.get('released') and not any(x >= r['rev'] for x in s.released.get(r['key'], ())) \
                        and any(covers(w, r['key']) for x in ups for w in s.orders[x]['writes']):      # and they cannot pass while this one is open
                    self.need('deps', bool(self._can_hand_in(r['key'], ups)), 'dependency-cycle',
                              'nothing that can finish before this order does hands in %s: issue the order that produces it first' % r['key'])
            for pool, n in sorted(o['needs'].items()):
                held = sum(s.orders[x]['needs'].get(pool, 0) for x in ups if s.orders[x]['state'] in OPEN)
                self.need('capacity', n == 0 or held + n <= s.pools.get(pool, 0), 'hold-and-wait',
                          'the orders above it hold %d of %s while they wait for it; with %d more the pool of %d is never enough' % (held, pool, n, s.pools.get(pool, 0)))
            extra = {'under': {'order': po['id'], 'token': tok}}
        self._emit('order.issued', body=o, **extra)

    def do_order_amend(self, m, b):
        o, patch = self._order(b), b.get('patch') or {}
        must(o['state'] in OPEN, 'closed')
        must(patch and set(patch) <= {'priority', 'due'}, 'immutable', 'the goal and inputs of an order never change: cancel it and issue a new one')
        self.need('basis', m.get('basis', 0) >= o['touched'], 'stale', 'the order changed after you last looked')
        self.need('authority', self.over(m['from'], o['issuer']), 'no-authority')
        self._emit('order.amended', order=o['id'], patch=patch, basis=m.get('basis', 0))

    def do_order_cancel(self, m, b):
        o = self._order(b)
        must(o['state'] in OPEN, 'closed')
        doomed = self._open_below(o['id'])
        newest = max([o['touched']] + [self.s.orders[x]['touched'] for x in doomed])       # a cancel takes the whole tree, so the whole tree is what you must have seen
        self.need('basis', m.get('basis', 0) >= newest, 'stale', 'the order, or something under it, changed after you last looked')
        self.need('authority', self.over(m['from'], o['issuer']), 'no-authority')
        self._emit('order.cancelled', order=o['id'], basis=m.get('basis', 0), reason=str(b.get('reason', ''))[:200])
        for x in doomed:
            self._emit('order.cancelled', order=x, cascade=True)

    def do_order_propose(self, m, b):
        to = b.get('to_superior') or (self.chain(m['from']) or [None])[0]
        must(to and isinstance(b.get('order'), dict), 'bad-shape', 'a proposal carries the order it wants and goes to a superior')
        self._emit('ask.raised', ask=m['id'], to=to, text=str(b.get('text', ''))[:500], proposal=b['order'])

    # ---- leases
    def do_claim_request(self, m, b):
        s, o = self.s, self._order(b)
        must(o['state'] in ('PENDING', 'LEASED'), 'closed')
        self.need('one-lease', o['state'] == 'PENDING', 'held', 'someone holds it')
        self.need('basis', m.get('basis', 0) >= o['touched'], 'stale', 'the order changed after you last looked')
        self.need('members', self.over(o['to'], m['from']), 'not-addressee')
        judge = (o.get('accept') or {}).get('judge')
        self.need('judge', m['from'] != judge and not self.over(o['to'], judge), 'no-judge', 'whoever judges an order does not also do it')
        self.need('deps', all(s.orders.get(a, {}).get('state') == 'SUCCEEDED' for a in o['after'])
                  and all(s.arts.get(r['key'], 0) >= r['rev'] for r in o['reads'])
                  and all(any(x >= r['rev'] for x in s.released.get(r['key'], ())) for r in o['reads'] if r.get('released'))
                  and not self._questions(o['id']), 'not-ready', 'something it depends on is not finished, not released, or a blocking question is open')
        fam, others = self._family(o['id']), [x for x in s.leases if x != o['id']]
        self.need('scope', not any(overlap(a, w) for x in others if x not in fam for a in s.orders[x]['writes'] for w in o['writes']),
                  'scope-overlap', 'another lease is writing there')
        for pool, n in sorted(o['needs'].items()):
            used = sum(s.orders[x]['needs'].get(pool, 0) for x in others)
            self.need('capacity', used + n <= s.pools.get(pool, 0), 'over-capacity', pool)
        tok, exp = o['token'] + 1, self._now + max(1, min(b.get('ttl', MAX_TTL), MAX_TTL))
        self._emit('lease.granted', order=o['id'], token=tok, expires=exp, basis=m.get('basis', 0))
        return {'lease': {'order': o['id'], 'token': tok, 'expires': exp}}

    def do_lease_renew(self, m, b):
        o, tok = self._lease(m)
        exp = self._now + max(1, min(b.get('ttl', MAX_TTL), MAX_TTL))
        self._emit('lease.renewed', order=o['id'], token=tok, expires=exp)
        return {'lease': {'order': o['id'], 'token': tok, 'expires': exp}}

    def do_lease_release(self, m, b):
        o, tok = self._lease(m)
        self._emit('lease.released', order=o['id'], token=tok, reason=str(b.get('reason', ''))[:200])

    # ---- work under a lease
    def do_artifact_put(self, m, b):
        s, key = self.s, b['key']
        o, tok = self._lease(m)
        below = [s.orders[x] for x in self._open_below(o['id'])]
        self.need('in-scope', any(covers(w, key) for w in o['writes']) and not any(covers(w, key) for c in below for w in c['writes']),
                  'out-of-scope', 'outside this order, or handed down to an open order under it')
        cur = s.arts.get(key, 0)
        self.need('expect', b.get('expect') == cur, 'stale', 'someone wrote revision %d after the one you read' % cur)
        self._emit('artifact.rev', key=key, seen=b.get('expect'), rev=cur + 1, order=o['id'], token=tok, note=str(b.get('note', ''))[:200])
        if 'notice' in self.g:
            for x in sorted(s.orders.values(), key=lambda x: x['id']):
                pins = [r['rev'] for r in x['reads'] if r['key'] == key and r['rev'] < cur + 1]
                if x['state'] in OPEN and pins:
                    self._emit('notice.input-moved', order=x['id'], key=key, pinned=pins[0], rev=cur + 1, to=x['issuer'])
        return {'rev': cur + 1}

    def do_report_progress(self, m, b):
        o, tok = self._lease(m)
        self._emit('report.progress', order=o['id'], token=tok, note=str(b.get('note', ''))[:500], pct=b.get('pct'))

    def do_report_submit(self, m, b):
        o, tok = self._lease(m)
        outs = b.get('outputs') or []
        must(all(self.s.arts.get(x['key'], 0) >= x['rev'] for x in outs), 'bad-output', 'outputs name revisions that exist')
        must(not self._open_below(o['id']), 'children-open', 'orders under it are still open')
        self.need('deps', not self._questions(o['id']), 'not-ready', 'a blocking question about it is still open')
        self._emit('report.submitted', order=o['id'], token=tok, outputs=outs, evidence=str(b.get('evidence', ''))[:500])

    def do_verdict(self, m, b):
        o = self._order(b)
        must(o['state'] == 'JUDGING', 'not-judging')
        self.need('basis', m.get('basis', 0) >= o['touched'], 'stale', 'the order changed after you last looked')
        self.need('judge', m['from'] == (o.get('accept') or {}).get('judge') and m['from'] != o.get('submitter') and not self.over(o['to'], m['from']),
                  'not-judge', 'only the judge named on the order decides, and never on its own work')
        if b.get('pass') is True:
            self._emit('order.succeeded', order=o['id'], basis=m.get('basis', 0))
        else:
            self._emit('order.failed', order=o['id'], retry=bool(b.get('retry')) and o['attempt'] < MAX_ATTEMPTS, basis=m.get('basis', 0), reason=str(b.get('reason', ''))[:300])

    # ---- questions to whoever is above
    def do_ask_raise(self, m, b):
        to, about, blocking = b.get('to') or (self.chain(m['from']) or [None])[0], b.get('order'), bool(b.get('blocking'))
        must(to and b.get('text'), 'bad-shape', 'a question needs text and someone above to answer')
        must(about is None or about in self.s.orders, 'unknown')
        if about is not None and blocking:                       # a blocking question holds the order, so not just anyone may ask one
            o = self.s.orders[about]
            self.need('authority', self.over(o['to'], m['from']) or self.over(m['from'], o['to']) or m['from'] == (o.get('accept') or {}).get('judge'),
                      'no-authority', 'only someone on the order, above it, or its judge can hold it with a question')
        self._emit('ask.raised', ask=m['id'], to=to, text=str(b['text'])[:500], about=about, blocking=blocking)

    def do_ask_answer(self, m, b):
        a = self.s.asks.get(b.get('ask'))
        must(a is not None, 'unknown')
        must(a['state'] == 'OPEN', 'closed')
        self.need('basis', m.get('basis', 0) >= a['touched'], 'stale')
        self.need('authority', self.over(m['from'], a['to']), 'no-authority')
        self._emit('ask.answered', ask=a['id'], answer=str(b.get('answer', ''))[:500])

    # ---- reading: one source, and every answer says how fresh it is
    def snapshot(self):
        s = self.s
        used = {p: sum(s.orders[x]['needs'].get(p, 0) for x in s.leases) for p in s.pools}
        return copy.deepcopy({'orders': s.orders, 'leases': s.leases, 'pools': {p: {'cap': c, 'used': used[p]} for p, c in s.pools.items()}, 'artifacts': s.arts,
                              'asks': {k: v for k, v in s.asks.items() if v['state'] == 'OPEN'}, 'org': s.org})

    def why(self, oid):
        """Everything that keeps an order from starting right now, from the same state everyone reads.  Never empty."""
        s, o, fam = self.s, self.s.orders[oid], self._family(oid)
        if o['state'] != 'PENDING':
            return [dict({'because': 'state', 'state': o['state']}, **{k: v for k, v in (s.leases.get(oid) or {}).items() if k != 'token'})]
        out = [{'because': 'after', 'order': a, 'state': s.orders.get(a, {}).get('state')} for a in o['after'] if s.orders.get(a, {}).get('state') != 'SUCCEEDED']
        out += [{'because': 'input', 'key': r['key'], 'pinned': r['rev'], 'have': s.arts.get(r['key'], 0)} for r in o['reads'] if s.arts.get(r['key'], 0) < r['rev']]
        out += [{'because': 'input-unreleased', 'key': r['key'], 'pinned': r['rev'], 'released': sorted(s.released.get(r['key'], ())),
                 'from': self._can_hand_in(r['key'], self._above(oid))} for r in o['reads']
                if r.get('released') and s.arts.get(r['key'], 0) >= r['rev'] and not any(x >= r['rev'] for x in s.released.get(r['key'], ()))]
        out += [{'because': 'scope', 'order': x, 'holder': s.leases[x]['holder'], 'expires': s.leases[x]['expires']} for x in sorted(s.leases)
                if x != oid and x not in fam and any(overlap(a, w) for a in s.orders[x]['writes'] for w in o['writes'])]
        for pool, n in sorted(o['needs'].items()):
            held = [x for x in sorted(s.leases) if x != oid and s.orders[x]['needs'].get(pool, 0)]
            used = sum(s.orders[x]['needs'][pool] for x in held)
            if used + n > s.pools.get(pool, 0):
                out.append({'because': 'capacity', 'pool': pool, 'cap': s.pools.get(pool, 0), 'used': used, 'needs': n,
                            'holders': [{'order': x, 'holder': s.leases[x]['holder'], 'units': s.orders[x]['needs'][pool],
                                         'priority': s.orders[x]['priority'], 'expires': s.leases[x]['expires']} for x in held]})
        out += [{'because': 'question', 'ask': a['id'], 'to': a['to'], 'text': a['text']} for a in self._questions(oid)]
        return out or [{'because': 'unclaimed', 'to': o['to']}]

    def do_state_query(self, m, b):
        out = {'source': {'head': self.s.head, 't': self._now, 'stale': False}}
        if 'why' in b:
            must(b['why'] in self.s.orders, 'unknown')
            out['why'] = self.why(b['why'])
        elif 'since' in b:
            since, limit = b['since'], min(b.get('limit', PAGE), PAGE)
            out['log'] = json.loads(json.dumps(self.log[since:since + limit]))            # a copy: the caller must not be able to edit the ledger through a reply
            out['more'], out['next'] = since + limit < len(self.log), out['log'][-1]['seq'] if out['log'] else since
        else:
            out['state'] = self.snapshot()
        return out


def msg(mid, frm, kind, body=None, basis=None, lease=None, ts=None):
    m = {'v': V, 'id': mid, 'from': frm, 'to': 'dispatcher', 'kind': kind, 'body': body or {}}
    if basis is not None:
        m['basis'] = basis
    if lease is not None:
        m['lease'] = {'order': lease['order'], 'token': lease['token']}
    if ts is not None:
        m['ts'] = ts
    return m
