#!/usr/bin/env python3
"""The dispatcher's hands.  A blank cockpit is `git init` plus an empty ledger; a topic is a branch; an order that
is claimed gets a branch of its own; the agent that works on it gets a plain folder with no .git in it; and only this adapter writes
the repository.  It does no work and judges nothing: it builds the folder, starts the agent, offers every file the agent changed to
the dispatcher (artifact.put), commits what the dispatcher took, and merges an order branch when the judge named on the order passes it.

Seats come from the chain of command: a team with teams under it sits in the planner seat (it may only hand in a list of sub-orders,
_dispatch/plan.json; any file it writes is left where it is), everyone else in the worker seat (files only, no orders).

Guards that can be switched off in a test (off=...):
   commit-accepted       commit only what the dispatcher took          merge-after-verdict   merge only after the judge passed it
   planner-no-files      the planner seat hands in no files           pinned-judge          rule with the judge pinned when the topic opened
   judge-needs           take no plan with an order the judge would rule on without a file it reads
   same-reason           sent back twice for the same reason: not started again, back to whoever planned it

Verification: the judge's source is pinned in the repository when the topic opens (refs/judge/<topic>, on no branch,
so no order can write it) and every ruling loads that copy; a worker's folder holds the same source as a self-check it may run before
handing in (_dispatch/verify.py: passing there is not the verdict); every merge says which judge ruled and whether the agent checked
itself; an order that is stuck or failed for good becomes a question to the nearest person up the chain, with the reasons.

What the judge reads: the judge says, in reads(), which other files a ruling on each file reads.  The planner seat
is shown that table, with the orders already under it and the budget it has left; a plan is not taken when an order in it would be
ruled on without one of those files among its released inputs; and an order the judge sends back twice for the same reason is not
started a third time: it and the open orders that wait for it are cancelled in the planner's name, and the planner seat starts again.
"""
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from dispatcher import Dispatcher, msg, covers        # noqa: E402

GUARDS = ('commit-accepted', 'merge-after-verdict', 'planner-no-files', 'pinned-judge', 'judge-needs', 'same-reason')
JUDGE_API = ('judge', 'judged', 'reads')            # what a judge file has to define; a topic does not open without all three
BOX = '_dispatch'               # the channel inside a sandbox: ORDER.json and the self-check in, plan.json out; never collected
NAME = re.compile(r'^[a-z0-9][a-z0-9_-]*(\.[a-z0-9][a-z0-9_-]*)*$')      # an order id becomes a folder and a branch: nothing else gets through
RULES = {'worker': 'You sit in the worker seat and do this one order only. Write files only under the paths listed in order.writes; '
                   'a file written anywhere else is not collected. The pinned inputs (inputs) are already at their paths: read them, '
                   'do not change them. %s/ is the channel: leave it alone. You cannot issue orders. Before handing in, run verify.cmd: '
                   'it checks this folder with the same program the judge uses; if it fails, fix what it says. '
                   'Passing it is not the verdict. When you are done, stop.' % BOX,
         'planner': 'You sit in the planner seat and do none of the work itself. Write the list of sub-orders to %s/plan.json '
                    '(format: roster.plan); any other file you write is not collected. Sub-orders may only go to roster.teams, and the '
                    'judge may only be one of roster.judges; if one order of the list is refused the whole list is refused, and the '
                    'reason is written in history. When the judge rules on an order it reads, besides the files that order handed in, '
                    'the files roster.judge_reads names for them: list those files in that order\'s reads (released: true), and put the '
                    'orders that hand them in earlier in the list. An entry in history whose what is replan means an order below was sent '
                    'back twice by the judge for the same reason and has been cancelled (with the ones waiting for it, see detail): hand in '
                    'a new list that supplies what was missing. roster.children are the sub-orders that already exist: the ones that passed '
                    'need not be issued again, a new id must not repeat one of them, after must not point at a cancelled one; the budgets '
                    'of the new sub-orders together must not exceed roster.budget_left.' % BOX}
PLAN = {'orders': [{'id': '<a unique id>', 'to': '<one of roster.teams>', 'title': '', 'goal': '<the instruction for whoever does it>',
                    'writes': ['<a path prefix inside your own scope>'],
                    'reads': [{'key': '<a file another order hands in>', 'rev': 1, 'released': True}], 'after': ['<an order that must pass first>'], 'budget': 0,
                    'accept': {'judge': '<one of roster.judges>', 'criteria': '<what passing means>'}}]}


VERIFY = r'''#!/usr/bin/env python3
