class Clock:
    def __init__(self, start):
        self.now = start


class Git:
    """Plumbing over a bare repository: nothing is ever checked out."""

    def __init__(self, path):
        self.path = path

    def raw(self, *args, data=None, env=None):
        r = subprocess.run(['git', '--git-dir', self.path] + list(args), input=data, capture_output=True, env=dict(os.environ, **(env or {})))
        if r.returncode:
            raise RuntimeError('git %s: %s' % (' '.join(args[:2]), r.stderr.decode('utf-8', 'replace').strip()[:300]))
        return r.stdout

    def __call__(self, *args, **kw):
        return self.raw(*args, **kw).decode('utf-8').strip()

    @staticmethod
    def who(t):
        return {'GIT_AUTHOR_NAME': 'dispatch-adapter', 'GIT_AUTHOR_EMAIL': 'adapter@dispatch.invalid', 'GIT_AUTHOR_DATE': '@%d +0000' % t,
                'GIT_COMMITTER_NAME': 'dispatch-adapter', 'GIT_COMMITTER_EMAIL': 'adapter@dispatch.invalid', 'GIT_COMMITTER_DATE': '@%d +0000' % t}

    def init(self, t):
        subprocess.run(['git', 'init', '-q', '--bare', '-b', 'main', self.path], check=True, capture_output=True)
        c = self('commit-tree', self('mktree', data=b''), '-m', 'blank cockpit', env=self.who(t))
        self('update-ref', 'refs/heads/main', c)
        return c

    def tip(self, branch):
        return self('rev-parse', '--verify', '-q', 'refs/heads/' + branch)

    def tree(self, rev):
        out = {}
        for row in self.raw('ls-tree', '-r', '-z', rev).split(b'\0'):
            if row:
                meta, path = row.split(b'\t', 1)
                out[path.decode('utf-8')] = meta.split()[2].decode()
        return out

    def blob(self, data):
        return self('hash-object', '-w', '--stdin', data=data)

    def commit(self, parents, files, message, t):
        """The tree of the first parent with `files` ({path: blob}) laid over it."""
        fd, idx = tempfile.mkstemp(prefix='gitws-idx-')
        os.close(fd)
        os.unlink(idx)
        try:
            self('read-tree', parents[0], env={'GIT_INDEX_FILE': idx})
            for p, sha in sorted(files.items()):
                self('update-index', '--add', '--cacheinfo', '100644,%s,%s' % (sha, p), env={'GIT_INDEX_FILE': idx})
            tree = self('write-tree', env={'GIT_INDEX_FILE': idx})
        finally:
            if os.path.exists(idx):
                os.unlink(idx)
        args = ['commit-tree', tree]
        for p in parents:
            args += ['-p', p]
        return self(*(args + ['-m', message]), env=self.who(t))


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def scan(box):
    """({path: bytes} of the regular files of a sandbox outside the channel, [paths that are not plain files])."""
    files, odd = {}, []
    for d, dirs, names in os.walk(box):
        rel = os.path.relpath(d, box)
        if rel == BOX or rel.startswith(BOX + os.sep):
            dirs[:] = []
            continue
        for n in names + [x for x in dirs if os.path.islink(os.path.join(d, x))]:
            full = os.path.join(d, n)
            key = os.path.relpath(full, box).replace(os.sep, '/')
            if os.path.islink(full) or not os.path.isfile(full) or '\n' in key or key.startswith('-') or '.git' in key.split('/'):
                odd.append(key)
            else:
                with open(full, 'rb') as f:
                    files[key] = f.read()
        dirs[:] = [x for x in dirs if not os.path.islink(os.path.join(d, x))]
    return files, sorted(odd)


class Ctx:
    """What a runner may ask of the adapter while it works: only the passing of time."""

    def __init__(self, ad, launch):
        self.ad, self.launch = ad, launch

    def wait(self, secs, alive=True):
        """Time passes.  alive=False: the process stopped answering, so its own lease is not kept alive meanwhile."""
        while secs > 0:
            step = min(60, secs)
            secs -= step
            self.ad.clock.now += step
            self.ad.beat(skip=() if alive else (self.launch['order'],))


class Adapter:
    def __init__(self, root, d, agents, judge_path, clock, judge_id='program:judge', ttl=600, max_launches=3, off=()):
        """agents: {identity: runner(sandbox_path, ctx)}.  judge_path: a Python file with judge(order, files, revs) -> (passed, reason)
        judged(order) -> what it can check, and reads() -> what a ruling on each file reads; it is read once, when the topic opens."""
        assert set(off) <= set(GUARDS), off
        self.root, self.d, self.agents, self.judge_path, self.clock, self._judges, self.told = root, d, agents, judge_path, clock, {}, set()
        self.judge_id, self.ttl, self.max_launches, self.off = judge_id, ttl, max_launches, set(off)
        self.git, self.topic = Git(os.path.join(root, 'repo.git')), None
        self.n, self.refused, self.replies, self.launches = 0, {}, [], []
        self.live, self.count, self.history, self.stuck = {}, {}, {}, set()      # leases kept alive; launches, earlier outcomes, escalations per order
        self.blobs, self.base, self.outs, self.rel, self.merged, self.conflicts = {}, {}, {}, {}, set(), 0
        for sub in ('sandboxes', 'manifests'):
            os.makedirs(os.path.join(root, sub))
        self.git.init(clock.now)

    # ---- the one way anything reaches the dispatcher
    def send(self, frm, kind, body=None, lease=None, basis=False):
        self.n += 1
        m = msg('a%05d' % self.n, frm, kind, body, basis=len(self.d.log) if basis else None, lease=lease)
        r = self.d.submit(m, self.clock.now)
        if not r['ok']:
            self.refused[r['code']] = self.refused.get(r['code'], 0) + 1
        b = body or {}
        self.replies.append({'id': m['id'], 't': self.clock.now, 'from': frm, 'kind': kind, 'about': (lease or {}).get('order') or b.get('order') or b.get('id') or b.get('actor'),
                             'ok': r['ok'], 'code': r.get('code')})
        return r

    def open_topic(self, name):
        with open(self.judge_path, 'rb') as f:               # the judge is pinned here, where no order branch can reach it
            src = f.read()
        ns = {'__name__': 'pinned_judge'}
        exec(compile(src, 'judge.py', 'exec'), ns)
        lacks = [x for x in JUDGE_API if not callable(ns.get(x))]
        if lacks:                                            # a judge that does not say what it reads cannot be planned for
            raise ValueError('the judge has no %s()' % '(), '.join(lacks))
        self.topic, blank = 'topic/' + name, self.git.tip('main')
        self.git('update-ref', 'refs/heads/' + self.topic, blank)
        self.git('update-ref', 'refs/judge/' + name, self.git.commit([blank], {'judge.py': self.git.blob(src)}, 'judge of topic %s' % name, self.clock.now))

    def judge_src(self):
        """(source, fingerprint) of the judge a ruling runs: the copy pinned when the topic opened."""
        if 'pinned-judge' in self.off:                       # guard off: whatever the file on disk says right now
            with open(self.judge_path, 'rb') as f:
                src = f.read()
        else:
            src = self.git.raw('cat-file', 'blob', 'refs/judge/%s:judge.py' % self.topic.split('/', 1)[1])
        return src, self.git('hash-object', '--stdin', data=src)[:12]

    def load_judge(self):
        src, fp = self.judge_src()
        if fp not in self._judges:
            ns = {'__name__': 'pinned_judge'}
            exec(compile(src, 'judge.py', 'exec'), ns)
            self._judges[fp] = ns
        return self._judges[fp], fp

    def escalate(self, frm, oid, blocking, text):
        """A question to the nearest person up the chain (not just whoever is directly above), carrying the last reasons."""
        people = [a for a in self.chain(self.d.snapshot()['org'], frm) if a.startswith('human:')]
        past = '; '.join('launch %d: %s %s' % (h['launch'], h['what'], json.dumps(h['detail'], ensure_ascii=False)[:120]) for h in self.history.get(oid, [])[-3:])
        body = {'order': oid, 'blocking': blocking, 'text': ('%s. Latest: %s' % (text, past or 'nothing recorded'))[:500]}
        if people:
            body['to'] = people[0]
        return self.send(frm, 'ask.raise', body)

    def beat(self, skip=()):
        """Keep the leases of live work alive, then let the dispatcher's clock end whatever is overdue."""
        for oid, le in sorted(self.live.items()):
            if oid not in skip and le['expires'] - self.clock.now < self.ttl / 2:
                r = self.send(le['holder'], 'lease.renew', {'ttl': self.ttl}, lease=le)
                if r['ok']:
                    le['expires'] = r['lease']['expires']
                else:                                        # it ended on the dispatcher's clock: nothing left to keep alive
                    del self.live[oid]
        self.d.tick(self.clock.now)

    # ---- who sits where
    @staticmethod
    def chain(org, a):
        out = []
        while org.get(a) and org[a] not in out:
            a = org[a]
            out.append(a)
        return out

    @staticmethod
    def seat(o, org):
        return 'planner' if any(k.startswith('team:') and up == o['to'] for k, up in org.items()) else 'worker'

    def holder(self, o, org, busy):
        if self.seat(o, org) == 'planner':
            return o['to'] if o['to'] in self.agents and o['to'] not in busy else None
        free = [a for a in sorted(self.agents) if a not in busy and (a == o['to'] or o['to'] in self.chain(org, a))]
        return free[0] if free else None

    # ---- one round: hand in, judge, claim everything that is ready, launch, collect
    def step(self):
        did = False
        self.beat()
        orders = self.d.snapshot()['orders']
        for oid, le in sorted(self.live.items()):           # a planner's order is handed in when everything under it has passed
            kids = [c for c in orders.values() if c['parent'] == oid and c['state'] != 'CANCELLED']      # a cancelled one was replaced, or dropped
            if orders[oid]['state'] == 'LEASED' and kids and all(c['state'] == 'SUCCEEDED' for c in kids) and (oid, le['token']) not in self.base_moved():
                outs = [x for c in sorted(kids, key=lambda c: c['id']) for x in self.outs.get(c['id'], [])]
                if self.send(le['holder'], 'report.submit', {'outputs': outs, 'evidence': 'all %d sub-orders passed' % len(kids)}, lease=le)['ok']:
                    self.outs[oid] = outs
                    del self.live[oid]
                    did = True
        for oid in sorted(orders):
            if self.d.snapshot()['orders'][oid]['state'] == 'JUDGING':
                self.rule(self.d.snapshot()['orders'][oid])
                did = True
        snap = self.d.snapshot()
        org, orders, busy, batch = snap['org'], snap['orders'], set(), []
        for oid in sorted(orders):                           # ended for good without passing: a person hears why
            if orders[oid]['state'] in ('FAILED', 'DEAD') and oid not in self.told:
                last = [x['agent'] for x in self.launches if x['order'] == oid]
                self.escalate(last[-1] if last else orders[oid]['to'], oid, False, 'this order ended without passing (%s)' % orders[oid]['state'])
                self.told.add(oid)
                did = True
        for oid in sorted(orders):
            o = orders[oid]
            if o['state'] != 'PENDING' or oid in self.stuck or not self.ready(o, snap):
                continue
            who = self.holder(o, org, busy)
            if who is None:
                continue
            if self.count.get(oid, 0) >= self.max_launches:      # the seat keeps coming back with nothing: a person has to look
                self.escalate(who, oid, True, 'started %d times without handing in anything that could be taken' % self.count[oid])
                self.stuck.add(oid)
                did = True
                continue
            r = self.send(who, 'claim.request', {'order': oid, 'ttl': self.ttl}, basis=True)
            if r['ok']:
                busy.add(who)
                batch.append(self.prepare(o, dict(r['lease'], holder=who), self.seat(o, org), org))
        for L in batch:                                      # started one after another here; a real run starts them together
            L['t0'] = self.clock.now
            try:
                self.agents[L['agent']](L['box'], Ctx(self, L))
            except Exception as e:                           # a runner that crashes is an agent that handed in nothing more
                L['error'] = repr(e)[:300]
            L['t1'] = self.clock.now
        for L in batch:
            self.collect(L)
            did = True
        return did

    def run(self, max_rounds=40):
        n = 0
        while n < max_rounds and self.step():
            n += 1
        return n

    def base_moved(self):
        """Orders whose own branch holds commits (a planner that was allowed to write): they are handed in by take(), not here."""
        return {k for k, b in self.base.items() if self.git.tip('order/%s/%d' % k) != b}

    def ready(self, o, snap):
        return (all(snap['orders'].get(a, {}).get('state') == 'SUCCEEDED' for a in o['after'])
                and all(any(x >= r['rev'] for x in self.rel.get(r['key'], ())) if r.get('released') else snap['artifacts'].get(r['key'], 0) >= r['rev'] for r in o['reads'])
                and not any(a['state'] == 'OPEN' and a['blocking'] and a['about'] == o['id'] for a in snap['asks'].values()))

    # ---- a claimed order becomes a branch and a folder
    def prepare(self, o, le, seat, org):
        oid, tok = o['id'], le['token']
        self.count[oid] = self.count.get(oid, 0) + 1
        self.live[oid] = le
        base = self.git.tip(self.topic)
        self.base[(oid, tok)] = base
        self.git('update-ref', 'refs/heads/order/%s/%d' % (oid, tok), base)
        given = {p: s for p, s in self.git.tree(base).items() if any(covers(w, p) for w in o['writes'])}
        inputs = []
        for r in o['reads']:
            rev = max(x for x in self.rel[r['key']] if x >= r['rev']) if r.get('released') else r['rev']
            given[r['key']] = self.blobs[(r['key'], rev)]
            inputs.append({'key': r['key'], 'rev': rev})
        box = os.path.join(self.root, 'sandboxes', '%s.%d' % (oid, tok))
        os.makedirs(os.path.join(box, BOX))
        manifest = {}
        for p, s in sorted(given.items()):
            data = self.git.raw('cat-file', 'blob', s)
            os.makedirs(os.path.dirname(os.path.join(box, p)), exist_ok=True)
            with open(os.path.join(box, p), 'wb') as f:
                f.write(data)
            manifest[p] = sha256(data)
        doc = {'v': 'dispatch/1', 'seat': seat, 'you': le['holder'], 'rules': RULES[seat],
               'order': {k: o[k] for k in ('id', 'parent', 'title', 'goal', 'to', 'writes', 'reads', 'after', 'budget', 'accept', 'unverified')},
               'attempt': o['attempt'], 'launch': self.count[oid], 'lease': {'token': tok, 'expires': le['expires']},
               'inputs': inputs, 'history': self.history.get(oid, [])}
        if seat == 'worker':                                 # the judge's own source, to run before handing in
            doc['verify'] = {'cmd': 'python3 %s/verify.py' % BOX, 'note': 'exit code 0 = this self-check passed; every run writes %s/verify.json' % BOX}
            for name, data in (('judge.py', self.judge_src()[0]), ('verify.py', VERIFY.encode('utf-8'))):
                with open(os.path.join(box, BOX, name), 'wb') as f:
                    f.write(data)
        if seat == 'planner':                                # what it needs to cut the work so that the judge can rule on every piece
            kids = sorted((c for c in self.d.snapshot()['orders'].values() if c['parent'] == oid), key=lambda c: c['id'])
            doc['roster'] = {'teams': sorted(k for k, up in org.items() if k.startswith('team:') and up == o['to']), 'judges': [self.judge_id], 'plan': PLAN,
                             'judge_reads': self.load_judge()[0]['reads'](),
                             'children': [{k: c[k] for k in ('id', 'state', 'to', 'writes', 'budget')} for c in kids],
                             'budget_left': o['budget'] - sum(c['budget'] for c in kids if c['state'] != 'CANCELLED')}
        with open(os.path.join(box, BOX, 'ORDER.json'), 'w', encoding='utf-8') as f:
            json.dump(doc, f, ensure_ascii=False, indent=1)
        with open(os.path.join(self.root, 'manifests', '%s.%d.json' % (oid, tok)), 'w', encoding='utf-8') as f:
            json.dump({'order': oid, 'token': tok, 'files': manifest}, f, ensure_ascii=False, indent=1)
        L = {'order': oid, 'token': tok, 'agent': le['holder'], 'seat': seat, 'attempt': o['attempt'], 'launch': self.count[oid], 'box': box,
             'lease': le, 'inputs': inputs, 'manifest': manifest, 'taken': [], 'refused': [], 'outside': [], 'outcome': None}
        self.launches.append(L)
        return L

    def changed(self, L):
        files, odd = scan(L['box'])
        L['odd'] = odd
        return {p: b for p, b in files.items() if L['manifest'].get(p) != sha256(b)}

    def collect(self, L):
        files = self.changed(L)
        if L['seat'] == 'planner' and 'planner-no-files' not in self.off:
            L['outside'] = sorted(files)                     # whatever the planner seat wrote stays in its folder
            return self.plan(L)
        if L['seat'] == 'planner' and os.path.exists(os.path.join(L['box'], BOX, 'plan.json')):
            return self.plan(L)
        self.take(L, files)

    def selfcheck(self, L, files):
        """What the agent's own run of the self-check says about the files it hands in: pass, fail, stale (changed since), none (never ran)."""
        try:
            with open(os.path.join(L['box'], BOX, 'verify.json'), encoding='utf-8') as f:
                v = json.load(f)
            seen = dict(v['files'])
        except (OSError, ValueError, KeyError, TypeError):
            return 'none'
        if any(seen.get(p) != sha256(b) for p, b in files.items()):
            return 'stale'
        return 'pass' if v.get('ok') is True else 'fail'

    def take(self, L, files):
        oid, tok, le, who = L['order'], L['token'], L['lease'], L['agent']
        L['selfcheck'] = self.selfcheck(L, files)
        arts, keep, outs = self.d.snapshot()['artifacts'], {}, []
        for p in sorted(files):
            sha = self.git.blob(files[p])
            r = self.send(who, 'artifact.put', {'key': p, 'expect': arts.get(p, 0), 'note': 'git:' + sha}, lease=le)
            if r['ok']:
                keep[p] = sha
                outs.append({'key': p, 'rev': r['rev']})
                self.blobs[(p, r['rev'])] = sha
                L['taken'].append(p)
            else:
                L['refused'].append({'key': p, 'code': r['code']})
                if r['code'] == 'out-of-scope':
                    L['outside'].append(p)
                if 'commit-accepted' not in self.off:
                    continue
                keep[p] = sha                                # guard off: commit whatever the agent wrote
        if keep:
            ref = 'order/%s/%d' % (oid, tok)
            self.git('update-ref', 'refs/heads/' + ref, self.git.commit([self.git.tip(ref)], keep, 'order %s token %d: %d file(s)' % (oid, tok, len(keep)), self.clock.now))
        if outs:
            r = self.send(who, 'report.submit', {'outputs': outs, 'evidence': '%d file(s)' % len(outs)}, lease=le)
            if r['ok']:
                self.outs[oid] = outs
                self.live.pop(oid, None)
                L['outcome'] = 'submitted'
                if 'merge-after-verdict' in self.off:        # guard off: merge as soon as it is handed in
                    self.merge(oid, tok, r['events'][0])
                return
        self.give_back(L, 'fenced' if any(x['code'] == 'fenced' for x in L['refused']) else 'no-output')

    def give_back(self, L, why, detail=None):
        oid = L['order']
        self.send(L['agent'], 'lease.release', {'reason': why}, lease=L['lease'])
        self.live.pop(oid, None)
        L['outcome'] = why
        self.history.setdefault(oid, []).append({'launch': L['launch'], 'what': why, 'detail': detail or L['refused']})

    def needs(self, b):
        """Files the pinned judge reads when it rules on this order that the order neither writes nor pins as a released input."""
        mod = self.load_judge()[0]
        table, own = mod['reads'](), set(mod['judged'](b))
        have = {r['key'] for r in b.get('reads') or () if r.get('released')}
        return sorted({x for k in own for x in table.get(k, ())} - own - have)

    def plan(self, L):
        oid, le, who = L['order'], L['lease'], L['agent']
        try:
            with open(os.path.join(L['box'], BOX, 'plan.json'), encoding='utf-8') as f:
                items = json.load(f)['orders']
            bodies = [dict(x, parent=oid) for x in items]
        except (OSError, ValueError, KeyError, TypeError):
            bodies = []
        if not bodies:
            return self.give_back(L, 'no-plan')
        trial, bad = Dispatcher(events=self.d.log), []       # rehearse on a copy of the ledger: a plan is taken whole or not at all
        for i, b in enumerate(bodies):
            r = trial.submit(msg('trial-%d' % i, who, 'order.issue', b, lease=le), self.clock.now)
            if not NAME.match(str(b.get('id'))) or len(b['id']) > 64 or b['id'].endswith('.lock'):
                bad.append({'id': b.get('id'), 'code': 'bad-id', 'detail': 'an id is lower-case letters, digits, - and _, in parts joined by ., at most 64 characters'})
            elif not r['ok']:
                bad.append({'id': b.get('id'), 'code': r['code'], 'detail': r.get('detail', '')})
            elif b['accept'].get('judge') != self.judge_id or not self.load_judge()[0]['judged'](b):
                bad.append({'id': b.get('id'), 'code': 'unjudgeable', 'detail': 'the judge can only be %s, and the write scope must hold a file it rules on' % self.judge_id})
            elif 'judge-needs' not in self.off and self.needs(b):
                bad.append({'id': b.get('id'), 'code': 'judge-needs', 'detail': 'to rule on this order the judge reads %s: list it under reads (released: true) and put the order that hands it in earlier in the list' % ', '.join(self.needs(b))})
        if bad:
            L['plan_refused'] = bad
            return self.give_back(L, 'plan-refused', bad)
        for b in bodies:
            self.send(who, 'order.issue', b, lease=le)
        L['issued'], L['outcome'] = [b['id'] for b in bodies], 'planned'

    # ---- the judge named on the order, then the merge
    def rule(self, o):
        oid, tok = o['id'], o['token']
        own = self.git.tip('order/%s/%d' % (oid, tok)) != self.base[(oid, tok)]
        tree = self.git.tree(self.git.tip('order/%s/%d' % (oid, tok)) if own else self.git.tip(self.topic))
        files = {p: self.git.raw('cat-file', 'blob', s) for p, s in tree.items()}
        L = [x for x in self.launches if (x['order'], x['token']) == (oid, tok)][-1]
        revs = {x['key']: x['rev'] for x in L['inputs']} if L['inputs'] else {k: max(v) for k, v in self.rel.items()}
        if own and not L['inputs']:                          # handed in together: what it is based on is what came with it
            revs.update({x['key']: x['rev'] for x in self.outs.get(oid, ())})
        for x in L['inputs']:                                # the pinned revisions, whatever the branch holds at those paths
            files[x['key']] = self.git.raw('cat-file', 'blob', self.blobs[(x['key'], x['rev'])])
        mod, fp = self.load_judge()
        try:
            ok, why = mod['judge'](o, files, revs)
        except Exception as e:                               # a judge that crashes has not passed anything
            ok, why = False, 'the judge program raised: %r' % (e,)
        ok, why = ok is True, str(why)[:300]
        r = self.send(self.judge_id, 'verdict', {'order': oid, 'pass': ok, 'retry': True, 'reason': why}, basis=True)
        if not r['ok']:
            return
        L['verdict'] = {'pass': ok, 'reason': why, 'judge': fp}
        if not ok:
            before = [h['detail'] for h in self.history.get(oid, ()) if h['what'] == 'judge-failed']
            self.history.setdefault(oid, []).append({'launch': L['launch'], 'what': 'judge-failed', 'detail': why})
            if 'same-reason' not in self.off and before and before[-1] == why:
                self.replan(oid, why)
            return
        if own:
            for x in self.outs.get(oid, ()):
                self.rel.setdefault(x['key'], []).append(x['rev'])
            if (oid, tok) not in self.merged:
                self.merge(oid, tok, r['events'][0], fp, L.get('selfcheck', 'none'))
        if o['parent'] is None:
            self.git('update-ref', 'refs/tags/accepted/' + self.topic.split('/', 1)[1], self.git.tip(self.topic))

    def replan(self, oid, why):
        """The judge gave the same reason twice: starting the order again changes nothing, so it goes back to whoever cut the work this way.
        It and the open orders beside it that wait for it are cancelled in the planner's name, the planner's lease is given back, and its
        seat starts again with what happened in its history.  With no planner above it, a person has to look."""
        orders = self.d.snapshot()['orders']
        o = orders[oid]
        if o['state'] != 'PENDING':                          # that ruling ended it for good: step() tells a person
            return
        up = orders.get(o['parent'])
        if up is None or up['state'] not in ('PENDING', 'LEASED'):
            last = [x['agent'] for x in self.launches if x['order'] == oid]
            self.escalate(last[-1] if last else o['to'], oid, True, 'sent back twice for the same reason, and there is no planner above to cut it again')
            self.stuck.add(oid)
            return
        gone, grew = [oid], True
        while grew:                                          # beside it, still open, and waiting for something that is going away
            grew = False
            for c in sorted(orders.values(), key=lambda c: c['id']):
                waits = set(c['after']) & set(gone) or any(covers(w, r['key']) for r in c['reads'] for g in gone for w in orders[g]['writes'])
                if c['parent'] == up['id'] and c['id'] not in gone and c['state'] in ('PENDING', 'LEASED', 'JUDGING') and waits:
                    gone.append(c['id'])
                    grew = True
        said = lambda g: 'same-reason: ' + why if g == oid else 'waits for %s, which was cancelled' % oid       # noqa: E731
        done = [g for g in gone if self.send(orders[g]['issuer'], 'order.cancel', {'order': g, 'reason': said(g)}, basis=True)['ok']]
        for g in done:
            self.live.pop(g, None)
        le = self.live.pop(up['id'], None)
        if le:                                               # the planner seat is free to be claimed again, with a new token
            self.send(le['holder'], 'lease.release', {'reason': 'replan'}, lease=le)
        self.history.setdefault(up['id'], []).append({'launch': self.count.get(up['id'], 0), 'what': 'replan',
                                                      'detail': {'order': oid, 'reason': why, 'cancelled': done}})

    def merge(self, oid, tok, seq, fp=None, checked='none'):
        tip, base, top = self.git.tip('order/%s/%d' % (oid, tok)), self.base[(oid, tok)], self.git.tip(self.topic)
        was, now = self.git.tree(base), self.git.tree(top)
        mine = {p: s for p, s in self.git.tree(tip).items() if was.get(p) != s}
        clash = [p for p in mine if now.get(p) != was.get(p)]
        if clash:                                            # someone else's merge touched the same path since this branch began
            self.conflicts += len(clash)
            return False
        stamp = 'judge: %s\nself-check: %s' % ('%s@%s' % (self.judge_id, fp) if fp else 'none', checked)     # how it was verified; "none" is a value
        c = self.git.commit([top, tip], mine, 'merge order %s token %d seq %d\n\n%s' % (oid, tok, seq, stamp), self.clock.now)
        self.git('update-ref', 'refs/heads/' + self.topic, c, top)
        self.merged.add((oid, tok))
        return True

    def save(self):
        with open(os.path.join(self.root, 'ledger.jsonl'), 'w', encoding='utf-8') as f:
            f.writelines(json.dumps(e, ensure_ascii=False) + '\n' for e in self.d.log)
        with open(os.path.join(self.root, 'replies.jsonl'), 'w', encoding='utf-8') as f:
            f.writelines(json.dumps(r, ensure_ascii=False) + '\n' for r in self.replies)
        keep = ('order', 'token', 'agent', 'seat', 'attempt', 'launch', 't0', 't1', 'taken', 'refused', 'outside', 'odd', 'outcome', 'issued', 'plan_refused', 'selfcheck', 'verdict', 'error')
        with open(os.path.join(self.root, 'launches.jsonl'), 'w', encoding='utf-8') as f:
            f.writelines(json.dumps({k: L[k] for k in keep if k in L}, ensure_ascii=False) + '\n' for L in self.launches)
