"""Read-only history of run ledgers, replayed by the dispatcher and cached by file metadata."""
import json
import os
import re
import time

import cli
import dispatcher
import gitws
import live

RUN = re.compile(r'^[A-Za-z0-9._-]+$')
FAILED = ('FAILED', 'DEAD', 'CANCELLED')


def day(t):
    return time.strftime('%Y-%m-%d', time.localtime(t))


def row_order(e):
    return (e.get('body') or {}).get('id') if e['kind'] == 'order.issued' else e.get('order') or e.get('about')


def empty_day():
    return {'orders': [], 'planned': [], 'stats': dict.fromkeys(('issued', 'succeeded', 'failed', 'launches'), 0)}


def lead_seat(seats):
    """Both saved team formats put the run's lead first; never borrow the live team's seat."""
    seat = seats[0] if seats else {}
    return {key: seat.get(key, '') for key in ('actor', 'name', 'model', 'family')}


class History:
    def __init__(self, root, current, clock):
        self.root, self.current, self.clock = os.path.abspath(root), current, clock
        self.cache = {}
        self.library = None

    def folder(self, run):
        if not isinstance(run, str) or not RUN.fullmatch(run) or run in ('.', '..', 'library'):
            raise FileNotFoundError('invalid run id')
        path = os.path.join(self.root, run)
        if os.path.islink(path) or not os.path.isdir(path) or os.path.dirname(os.path.realpath(path)) != os.path.realpath(self.root):
            raise FileNotFoundError('no such run folder')
        return path

    def read(self, run):
        path = self.folder(run)
        ledger = os.path.join(path, cli.LEDGER)
        if os.path.islink(ledger):
            raise ValueError('ledger must be a regular file')
        st = os.stat(ledger)
        mark = (st.st_size, st.st_mtime_ns, st.st_ino)
        if run not in self.cache or self.cache[run][0] != mark:
            events = cli.read_ledger(path)
            d = dispatcher.Dispatcher(events=events)
            orders = d.snapshot()['orders']
            issued = {e['body']['id']: e for e in events if e['kind'] == 'order.issued'}
            tops = {}
            for oid in orders:
                top, seen = oid, set()
                while orders[top].get('parent'):
                    if top in seen:
                        raise ValueError('cyclic order ancestry')
                    seen.add(top)
                    top = orders[top]['parent']
                tops[oid] = top
            self.cache[run] = (mark, {'orders': orders, 'events': events, 'issued': issued, 'tops': tops})
        return self.cache[run][1]

    def runs(self):
        good, skipped = {}, []
        for name in sorted(os.listdir(self.root)):
            if name == 'library':
                continue
            path = os.path.join(self.root, name)
            if not os.path.isdir(path) and not os.path.islink(path):
                continue
            try:
                good[name] = self.read(name)
            except (OSError, ValueError, KeyError, TypeError, AttributeError, cli.LedgerError) as e:
                skipped.append({'run': name, 'why': '%s: %s' % (type(e).__name__, str(e).replace(self.root + os.sep, ''))})
        return good, skipped

    def board(self, run):
        path = os.path.join(self.folder(run), 'logs', 'team.json')
        try:
            with open(path, encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {}

    def seats(self, run, board):
        path = os.path.join(self.folder(run), 'team.json')
        try:
            with open(path, encoding='utf-8') as f:
                team = json.load(f)
            return [dict(s, name=s.get('name') or s['id'], actor=('team:' if i == 0 else 'agent:') + s['id'],
                         team='team:' + s['id'], family=live.family(s['model']))
                    for i, s in enumerate([team['lead']] + team['seats'])]
        except FileNotFoundError:
            return [dict(s, id=s['actor'].split(':', 1)[-1]) for s in board.get('seats', [])]

    def launches(self, run):
        board = self.board(run)
        if 'launches' in board:
            return board['launches']
        try:
            with open(os.path.join(self.folder(run), 'launches.jsonl'), encoding='utf-8') as f:
                return [json.loads(line) for line in f]
        except FileNotFoundError:
            return []

    def summary(self, plans):
        runs, skipped = self.runs()
        out = {'today': day(self.clock()), 'live_run': self.current, 'runs': [], 'days': {}, 'skipped': skipped}
        for run, r in runs.items():
            events, orders = r['events'], r['orders']
            run_day = day(events[0]['t']) if events else day(os.stat(self.folder(run)).st_mtime)
            out['runs'].append({'run': run, 'live': run == self.current, 'day': run_day})
            try:
                lead = lead_seat(self.seats(run, self.board(run)))
            except (OSError, ValueError, KeyError, TypeError) as e:
                out['skipped'].append({'run': run, 'why': 'team records unreadable: ' + type(e).__name__})
                lead = lead_seat([])
            try:
                launches = self.launches(run)
            except (OSError, ValueError, TypeError) as e:
                out['skipped'].append({'run': run, 'why': 'launch records unreadable: ' + type(e).__name__})
                launches = []
            rejected = {e['order'] for e in events if e['kind'] == 'order.failed' and e.get('retry')}
            for oid, o in orders.items():
                if o.get('parent'):
                    continue
                e = r['issued'][oid]
                target = out['days'].setdefault(day(e['t']), empty_day())
                family = {k for k, top in r['tops'].items() if top == oid}
                attention = any(orders[k]['state'] in FAILED or (k in rejected and orders[k]['state'] != 'SUCCEEDED') for k in family)
                target['orders'].append({'run': run, 'id': oid, 'title': o['title'], 'state': o['state'], 'to': o['to'], 't': e['t'], 'attention': attention, 'lead': dict(lead)})
                stats = target['stats']
                stats['issued'] += 1
                stats['succeeded'] += o['state'] == 'SUCCEEDED'
                stats['failed'] += o['state'] in FAILED
                stats['launches'] += sum(l['order'] in family for l in launches)
        for p in plans.values():
            out['days'].setdefault(p['day'], empty_day())['planned'].append(
                {k: p.get(k) for k in ('id', 'title', 'state', 'run', 'order')})
        return out

    def order(self, run, oid):
        r = self.read(run)
        orders = r['orders']
        if oid not in orders:
            raise FileNotFoundError('unknown order')
        family = {oid}
        while True:
            more = {k for k, o in orders.items() if o.get('parent') in family} - family
            if not more:
                break
            family.update(more)
        def node(k):
            o = orders[k]
            return dict(o, by=r['issued'][k]['by'], judge=o.get('accept', {}).get('judge', ''), day=day(r['issued'][k]['t']),
                        top=r['tops'][k], writes=', '.join(o.get('writes', [])))
        board = self.board(run)
        seats = self.seats(run, board)
        return {'run': run, 'live': run == self.current, 'lead': lead_seat(seats), 'order': node(oid),
                'children': [node(k) for k, o in orders.items() if o.get('parent') == oid],
                'nodes': [node(k) for k in orders if k in family],
                'seats': seats, 'launches': [l for l in self.launches(run) if l['order'] in family],
                'files': self.files(run, family), 'ledger': [e for e in r['events'] if row_order(e) in family],
                'library': self.library.order(run, oid, family) if self.library else
                           {'workflow': None, 'uses': [], 'proposed': [], 'saved': {}}}

    def artifacts(self, run, family=None):
        newest = {}
        for e in self.read(run)['events']:
            if e['kind'] == 'artifact.rev' and (family is None or e.get('order') in family):
                note = e.get('note', '')
                if re.fullmatch(r'git:[0-9a-f]{40,64}', note):
                    newest[e['key']] = (e, note[4:])
        return newest

    def files(self, run, family):
        git = gitws.Git(os.path.join(self.folder(run), 'repo.git'))
        try:
            accepted = git.tree('refs/tags/accepted/' + live.TOPIC)
        except RuntimeError:
            accepted = {}
        return [{'path': key, 'order': e['order'], 'rev': e['rev'], 'size': int(git('cat-file', '-s', sha)),
                 'accepted': accepted.get(key) == sha} for key, (e, sha) in sorted(self.artifacts(run, family).items())]

    def read_file(self, run, path, limit=65536):
        if not path or path.startswith('/') or '\\' in path or any(p in ('', '.', '..') for p in path.split('/')):
            return None
        item = self.artifacts(run).get(path)
        if item is None:
            return None
        e, sha = item
        data = gitws.Git(os.path.join(self.folder(run), 'repo.git')).raw('cat-file', 'blob', sha)
        try:
            text, binary = data[:limit].decode('utf-8'), False
        except UnicodeDecodeError:
            text, binary = '', True
        return {'path': path, 'rev': e['rev'], 'size': len(data), 'text': text, 'binary': binary, 'truncated': len(data) > limit}

    def file_bytes(self, run, path, family):
        """The exact blob represented by a file in this order's GET /order result."""
        item = self.artifacts(run, family).get(path)
        if item is None:
            return None
        return gitws.Git(os.path.join(self.folder(run), 'repo.git')).raw('cat-file', 'blob', item[1])
