"""The judge of orders issued from the cockpit (program:judge-floor).  It holds only the floor a program can hold for
work it knows nothing about: something was handed in where the order said, none of it is empty, and each file reads as
what its name claims (UTF-8 text, JSON that parses, Python that compiles; nothing is ever run).  Whether the work is any
good is NOT looked at: that stays with whoever the order names under `unverified`, or with a person named as the judge.

Like every judge file it is read once, when the topic opens, and it is also what a worker's self-check runs.
To hold more than the floor, write your own file with the same three functions and start the backend with --judge."""
import json

TEXT = ('.md', '.txt', '.json', '.jsonl', '.py', '.csv', '.tsv', '.html', '.js', '.ts', '.tsx', '.css', '.yaml', '.yml', '.toml', '.sh', '.sql')


def covers(scope, key):
    """'a/b/' covers everything under it; 'a/b' covers exactly itself (as dispatcher.covers)."""
    return key == scope or (scope.endswith('/') and key.startswith(scope))


def judged(order):
    """What this judge can rule on for an order: everything the order may write."""
    return list(order.get('writes') or ())


def reads():
    """{file it rules on: [other files it reads to do so]}.  The floor reads nothing else."""
    return {}


def parse(path, text):
    """None, or what is wrong with a file that claims a format."""
    low = path.lower()
    try:
        if low.endswith('.json'):
            json.loads(text)
        elif low.endswith('.jsonl'):
            for n, line in enumerate(text.splitlines(), 1):
                if line.strip():
                    try:
                        json.loads(line)
                    except ValueError:
                        return 'line %d is not JSON' % n
        elif low.endswith('.py'):
            compile(text, path, 'exec')         # parsed only: nothing of it runs
    except SyntaxError as e:
        return 'does not compile as Python (line %s)' % e.lineno
    except ValueError:
        return 'is not JSON that parses'
    except Exception as e:                      # a file made to break the parser has not passed
        return 'could not be read (%s)' % type(e).__name__
    return None


def judge(order, files, revs):
    scopes = judged(order)
    if not scopes:
        return False, 'this order has no write scope, so there is nothing for the judge to look at'
    mine = {p: b for p, b in files.items() if any(covers(w, p) for w in scopes)}
    why = ['nothing was handed in under %s' % w if w.endswith('/') else '%s was not handed in' % w for w in scopes if not any(covers(w, p) for p in mine)]
    for p, b in sorted(mine.items()):
        if not b.strip():
            why.append('%s is empty' % p)
        elif p.lower().endswith(TEXT):
            try:
                bad = parse(p, b.decode('utf-8'))
            except UnicodeDecodeError:
                bad = 'is not UTF-8 text'
            if bad:
                why.append('%s %s' % (p, bad))
    if why:
        return False, '; '.join(why)[:300]
    return True, '%d file(s) are inside the write scope, not empty and readable as what they claim to be; this judge did not look at whether the content is any good' % len(mine)
