"""A durable, shared library. Call from the server lock; flock also serializes separate runs.

One atomic JSON snapshot holds bytes, entries and receipts together, so a review or a
replayed plan cannot leave half a change behind. Ledger-derived records are idempotent.
"""
import base64
import contextlib
import datetime
import fcntl
import hashlib
import json
import os
import re
import tempfile

LIMIT = 65536
KINDS = ('artifact', 'skill', 'workflow', 'lesson')
FINAL = ('SUCCEEDED', 'FAILED', 'DEAD', 'CANCELLED')
REPO = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))


class Error(ValueError):
    def __init__(self, code, detail, status=400):
        super().__init__(detail)
        self.code, self.status = code, status


def outside_repo(root):
    if os.path.commonpath((os.path.realpath(root), REPO)) == REPO:
        raise ValueError('The runs root must be outside the repository; it holds the shared library.')


def encoded(doc):
    # Match the HTTP handler's serialization, including its byte limit.
    return json.dumps(doc, ensure_ascii=False).encode('utf-8')


def iso(t):
    return datetime.datetime.fromtimestamp(t, datetime.timezone.utc).isoformat()


def key(*parts):
    return json.dumps(parts)


def public(entry):
    return {k: v for k, v in entry.items() if not k.startswith('_')}


def preview(data):
    return data[:LIMIT].decode('utf-8', 'replace').encode('utf-8')[:LIMIT].decode('utf-8', 'ignore')


def utf8(value):
    if isinstance(value, str):
        try:
            return value.encode('utf-8')
        except UnicodeEncodeError:
            pass
    return None


class Library:
    def __init__(self, root, clock):
        outside_repo(root)
        self.root, self.clock = os.path.join(root, 'library'), clock
        if os.path.islink(self.root):
            raise ValueError('The library must be a real folder, not a symlink.')
        os.makedirs(self.root, exist_ok=True)
        self.path = os.path.join(self.root, 'index.json')
        self.lock = os.path.join(self.root, 'writer.lock')
        with self.transaction():
            pass

    def read(self):
        try:
            with open(self.path, encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {'v': 'library-store/1', 'entries': [], 'plans': {}, 'next': 1}

    @contextlib.contextmanager
    def transaction(self):
        with open(self.lock, 'a+b') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX)
            doc = self.read()
            before = encoded(doc)
            yield doc
            data = encoded(doc)
            if data == before and os.path.exists(self.path):
                return
            fd, path = tempfile.mkstemp(prefix='.library-', dir=self.root)
            try:
                with os.fdopen(fd, 'wb') as f:
                    f.write(data)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(path, self.path)
                directory = os.open(self.root, os.O_RDONLY)
                try:
                    os.fsync(directory)
                finally:
                    os.close(directory)
            finally:
                if os.path.exists(path):
                    os.unlink(path)

    def add(self, doc, receipt, kind, title, status, by, source, data=b'', at=None, **fields):
        old = next((e for e in doc['entries'] if e['_key'] == receipt), None)
        if old is not None:
            return old
        n = doc['next']
        suffix = '-' + str(n)
        slug = re.sub('[^a-z0-9]+', '-', title.lower()).strip('-') or 'entry'
        stem = (kind + '-' + slug)[:48 - len(suffix)].rstrip('-')
        e = {'id': stem + suffix, 'kind': kind, 'title': title, 'status': status, 'by': by,
             'at': iso(self.clock() if at is None else at), 'source': source, 'tags': [], 'replaces': None,
             'version': 1, 'used': 0, 'summary': ' '.join(preview(data).split())[:200],
             'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data),
             'steps': [], 'metrics': {}, 'uses': [], 'reason': '',
             '_data': base64.b64encode(data).decode('ascii'), '_key': receipt, '_n': n}
        e.update(fields)
        doc['next'] += 1
        doc['entries'].append(e)
        return e

    def listing(self):
        entries = self.read()['entries']
        return {'entries': [public(e) for e in sorted(entries, key=lambda e: (e['at'], e['_n']), reverse=True)],
                'counts': {kind: sum(e['kind'] == kind for e in entries) for kind in KINDS}}

    def item(self, eid):
        entry = next((e for e in self.read()['entries'] if e['id'] == eid), None)
        if entry is None:
            raise Error('unknown-entry', 'No library entry has that id.', 404)
        return dict(public(entry), text=preview(base64.b64decode(entry['_data'])))

    def save(self, body, history, actor):
        run, oid, path = (body.get(k) for k in ('run', 'order', 'path'))
        # Resolve the exact same family and revision as GET /order, never a disk path.
        try:
            if not isinstance(path, str) or not path or path.startswith('/') or '\\' in path or any(
                    p in ('', '.', '..') for p in path.split('/')):
                raise FileNotFoundError()
            detail = history.order(run, oid)
            handed = next((f for f in detail['files'] if f['path'] == path), None)
            if handed is None:
                raise FileNotFoundError()
            data = history.file_bytes(run, path, {n['id'] for n in detail['nodes']})
            if data is None:
                raise FileNotFoundError()
        except (OSError, ValueError, KeyError, TypeError, RuntimeError):
            raise Error('not-a-handed-in-file', 'Choose a file listed for this run and order.') from None
        kind, title, tags = body.get('kind'), body.get('title'), body.get('tags', [])
        if (kind not in ('artifact', 'skill') or utf8(title) is None or not title.strip()
                or len(title) > 200 or not isinstance(tags, list) or any(utf8(t) is None for t in tags)):
            raise Error('bad-entry', 'Use artifact or skill, a title of 1 to 200 characters, and a list of text tags.')
        if kind == 'skill':
            try:
                data.decode('utf-8')
            except UnicodeDecodeError:
                raise Error('bad-entry', 'A skill must be UTF-8 text.') from None
        with self.transaction() as doc:
            entry = self.add(doc, key('save', run, oid, path, kind), kind, title.strip(), 'accepted', actor,
                             {'run': run, 'order': oid, 'path': path}, data, tags=tags)
        return public(entry)

    def review(self, body, actor):
        with self.transaction() as doc:
            entry = next((e for e in doc['entries'] if e['id'] == body.get('id')), None)
            if entry is None or entry['status'] != 'proposed':
                raise Error('not-reviewable', 'Only a proposed entry can be reviewed.')
            decision, reason = body.get('decision'), body.get('reason', '')
            if decision not in ('accept', 'reject') or utf8(reason) is None:
                raise Error('bad-review', 'Use accept or reject and a text reason.')
            if decision == 'reject' and not reason.strip():
                raise Error('reason-needed', 'Rejecting a proposal needs a reason.')
            entry.update(status='accepted' if decision == 'accept' else 'rejected', reason=reason.strip())
            if decision == 'accept':
                old = next((e for e in doc['entries'] if e['id'] == entry['replaces']), None)
                if old is not None:
                    old['status'] = 'superseded'
            else:
                self.add(doc, key('rejected', entry['id']), 'lesson', 'Rejected: ' + entry['title'],
                         'recorded', actor, entry['source'], reason.strip().encode('utf-8'),
                         order=entry['source']['order'], seat=entry['by'], reason=reason.strip())
        return public(entry)

    def _plan(self, doc, run, oid, token, actor, at, plan):
        receipt = key(run, oid, token)
        if receipt in doc['plans']:
            return
        known = {e['id']: e for e in doc['entries']}
        used, unknown = [], []
        values = plan.get('uses', [])
        for eid in values if isinstance(values, list) else []:
            if utf8(eid) is None or eid in used or eid in unknown:
                continue
            if eid in known:
                known[eid]['used'] += 1
                used.append(eid)
            else:
                unknown.append(eid)
        source = {'run': run, 'order': oid, 'path': '_dispatch/plan.json'}
        proposals = plan.get('propose', [])
        for i, p in enumerate(proposals[:3] if isinstance(proposals, list) else []):
            if not isinstance(p, dict) or p.get('kind') != 'skill':
                continue
            title, text, replaces, why = (p.get(k) for k in ('title', 'text', 'replaces', 'why'))
            data = utf8(text)
            if (utf8(title) is None or not title.strip() or len(title) > 200
                    or data is None or not text.strip() or len(data) > 8192
                    or utf8(why) is None or (replaces is not None and
                    (not isinstance(replaces, str) or replaces not in known or known[replaces]['kind'] != 'skill'))):
                continue
            self.add(doc, key('proposal', run, oid, token, i), 'skill', title.strip(), 'proposed', actor, source,
                     data, at=at, replaces=replaces,
                     version=known[replaces]['version'] + 1 if replaces else 1, reason=why)
        doc['plans'][receipt] = {'run': run, 'order': oid, 'uses': used, 'unknown_uses': unknown}

    def record_plan(self, run, launch, plan, at):
        with self.transaction() as doc:
            self._plan(doc, run, launch['order'], launch['token'], launch['agent'], at, plan)

    @staticmethod
    def usage(doc, run, oid):
        receipts = [p for p in doc['plans'].values() if p['run'] == run and p['order'] == oid]
        return {k: list(dict.fromkeys(eid for p in receipts for eid in p[k])) for k in ('uses', 'unknown_uses')}

    def sync(self, history):
        """Backfill old runs and recover after a ledger append but before the library receipt."""
        runs, _ = history.runs()
        with self.transaction() as doc:
            for run, r in runs.items():
                leases = {}
                for event in r['events']:
                    kind, oid = event['kind'], event.get('order')
                    if kind == 'lease.granted':
                        leases[oid] = event
                    if kind == 'order.issued':
                        parent = event['body'].get('parent')
                        lease = leases.get(parent)
                        if lease and key(run, parent, lease['token']) not in doc['plans']:
                            # Only plans proven to have issued sub-orders may affect the library.
                            box = os.path.join(os.path.realpath(history.folder(run)), 'sandboxes', '%s.%d' % (parent, lease['token']))
                            path = os.path.join(box, '_dispatch', 'plan.json')
                            if not re.fullmatch(r'[a-z0-9][a-z0-9_.-]{0,63}', parent):
                                continue
                            if os.path.realpath(path) != os.path.abspath(path):
                                continue
                            try:
                                with open(path, encoding='utf-8') as f:
                                    plan = json.load(f)
                                if isinstance(plan, dict):
                                    self._plan(doc, run, parent, lease['token'], lease['by'], event['t'], plan)
                            except (OSError, ValueError):
                                pass
                    if kind in ('order.failed', 'order.dead'):
                        o = r['orders'][oid]
                        reason = event.get('reason', 'The lease expired too many times.')
                        self.add(doc, key('lesson', run, event['seq']), 'lesson', 'Review: ' + o['title'],
                                 'recorded', event['by'], {'run': run, 'order': oid, 'path': 'ledger.jsonl'},
                                 reason.encode('utf-8'), at=event['t'], order=oid,
                                 seat=leases.get(oid, {}).get('by', o['to']), reason=reason)
                for oid, o in r['orders'].items():
                    if o.get('parent') or o['state'] not in FINAL:
                        continue
                    ended = next(e for e in reversed(r['events']) if e.get('order') == oid and
                                 e['kind'] in ('order.succeeded', 'order.failed', 'order.dead', 'order.cancelled'))
                    family = {k for k, top in r['tops'].items() if top == oid}
                    counts = {k: 0 for k in family}
                    for e in r['events']:
                        if e['kind'] == 'lease.granted' and e['order'] in family:
                            counts[e['order']] += 1
                    steps = [{'order': k, 'seat': child['to'], 'title': child['title'], 'after': child['after'],
                              'reads': child['reads'], 'writes': child['writes']}
                             for k, issued in r['issued'].items() if k in family and k != oid
                             for child in [issued['body']]]
                    metrics = {'state': o['state'], 'launches': sum(counts.values()),
                               'sent_back': sum(max(0, n - 1) for n in counts.values()),
                               'seconds': ended['t'] - r['issued'][oid]['t']}
                    self.add(doc, key('workflow', run, oid), 'workflow', o['title'], 'recorded', 'program:library',
                             {'run': run, 'order': oid, 'path': 'ledger.jsonl'}, at=ended['t'], steps=steps,
                             metrics=metrics, **self.usage(doc, run, oid))

    def context(self):
        entries = self.read()['entries']
        known = {e['id']: e for e in entries}
        def chain(e):
            seen = set()
            while e['replaces'] in known and e['id'] not in seen:
                seen.add(e['id'])
                e = known[e['replaces']]
            return e['id']
        groups = {'skills': [], 'artifacts': [], 'workflows': [], 'lessons': []}
        fields = {'skills': ('id', 'title', 'version'), 'artifacts': ('id', 'title', 'summary', 'source'),
                  'workflows': ('id', 'title', 'steps', 'metrics', 'uses'), 'lessons': ('id', 'order', 'seat', 'reason')}
        roots, chosen = set(), []
        for e in sorted(entries, key=lambda e: (e['at'], e['_n']), reverse=True):
            group = e['kind'] + 's'
            if e['kind'] in ('skill', 'artifact') and e['status'] != 'accepted':
