                'uses': [{k: e[k] for k in ('id', 'kind', 'title')} for eid in uses for e in entries if e['id'] == eid],
                'proposed': [public(e) for e in related if e['status'] == 'proposed'],
                'saved': {e['source']['path']: e['id'] for e in related if e['_key'].startswith('["save",')}}
