"""One run, live: the dispatcher's ledger, the git layer, and one OpenCode process per order.

    you (human:ceo)
      the lead          a planner seat: it writes _dispatch/plan.json and nothing else
        team A            one worker agent
        team B            one worker agent
        ...

Which seat is run with which model is the team file (see team.example.json); nothing here knows a model's name.
Two threads: one answers HTTP, one does the work.  They share one lock, and the lock is let go while an agent's
process runs, so the page is answered meanwhile."""
import json
import os
import re
import shutil
import signal
import threading
import time
import traceback

import cli
import gitws
import opencode_agent as A

HERE = os.path.dirname(os.path.abspath(__file__))
CEO, JUDGE, TOPIC = 'human:ceo', 'program:judge-floor', 'work'
STOPPED = 'the backend was stopped: what this launch produced was not collected'
OWN = (cli.LEDGER, 'replies.jsonl', 'launches.jsonl')       # what the backend itself writes in the run folder while an agent runs
KEEP = ('outcome', 'taken', 'refused', 'outside', 'selfcheck', 'verdict', 'issued', 'plan_refused', 'error', 'held', 'killed')
FAMILIES = (('deepseek', r'deepseek'), ('kimi', r'kimi|moonshot'), ('qwen', r'qwen|dashscope|tongyi'))
ID = re.compile(r'^[a-z0-9][a-z0-9-]{0,30}$')


def say(text):
    print('cockpit: ' + text, flush=True)


def family(model):
    """Which mark the page draws for a model id: deepseek, kimi, qwen, or other."""
    low = str(model).lower()
    return next((name for name, pat in FAMILIES if re.search(pat, low)), 'other')


def atomic(path, text):
    """Whole or not at all, and left alone when it already says this."""
    try:
        with open(path, encoding='utf-8') as f:
            if f.read() == text:
                return
    except (OSError, ValueError):
        pass
    with open(path + '.tmp', 'w', encoding='utf-8') as f:
        f.write(text)
    os.replace(path + '.tmp', path)


def load_team(path):
    """The team file, checked.  {'lead': {id, name, model}, 'seats': [{id, name, model}], 'pass_env': [...], 'permission': {...}}"""
    with open(path, encoding='utf-8') as f:
        doc = json.load(f)
    seats = [doc['lead']] + list(doc['seats'])
    for s in seats:
        if not ID.match(str(s.get('id'))) or not isinstance(s.get('model'), str) or '/' not in s['model']:
            raise ValueError('a seat needs an id (lower-case letters, digits, -) and a model written provider/model: %r' % (s,))
    if len({s['id'] for s in seats}) != len(seats) or len(seats) < 2:
        raise ValueError('a team is a lead and at least one seat, each with its own id')
    names = [n for n in doc.get('pass_env', ()) if isinstance(n, str) and re.match(r'^[A-Z][A-Z0-9_]*$', n)]
    return {'lead': doc['lead'], 'seats': list(doc['seats']), 'pass_env': names, 'permission': dict(doc.get('permission') or {})}


class Through:
    """What the adapter holds as its dispatcher: the HTTP side's writer.  So a row the adapter causes is on disk, and in
    the chain a reader checks, the moment it exists, exactly like one a person sent."""

    def __init__(self, writer, gate):
        self.w, self.gate = writer, gate

    @property
    def log(self):
        return self.w.d.log

    def snapshot(self):
        with self.gate:
            return self.w.d.snapshot()

    def submit(self, m, now):
        with self.gate:
            return self.w.submit(m, now)

    def tick(self, now):
        """The dispatcher's clock: what it ends by itself (a lease whose time is up) is written like any other row."""
        with self.gate:
            w = self.w
            if w._stat() != w.mark:
                raise cli.Moved('%s changed since this writer read it: someone wrote without the lock; nothing was written' % w.path)
            before = len(w.d.log)
            out = w.d.tick(now)
            new = w.d.log[before:]
            if new:
                data = ''.join(json.dumps(e, ensure_ascii=False) + '\n' for e in new).encode('utf-8')
                more = cli.chain(data, w.chain[-1] if w.chain else None)
                fd = os.open(w.path, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
                try:
                    while data:
                        data = data[os.write(fd, data):]
                    os.fsync(fd)
                finally:
                    os.close(fd)
                w.chain = w.chain + more
            w.mark = w._stat()
            return out


class Adapter(gitws.Adapter):
    """The git layer with what a live run needs: a launch the guard held back hands its lease back with nothing looked
    at; once the guard has said no, nothing new is claimed; an order somebody else is to judge waits for them."""
    guard, board, stopping = None, staticmethod(lambda: None), staticmethod(lambda: False)
    library = None

    def library_context(self, launch):
        """Refresh at launch time: an earlier seat in the batch may have changed the library."""
        if self.library is not None:
            path = os.path.join(launch['box'], gitws.BOX, 'LIBRARY.json')
            atomic(path, json.dumps(self.library.context(), ensure_ascii=False))

    def prepare(self, o, le, seat, org):
        launch = super().prepare(o, le, seat, org)
        if self.library is not None:
            path = os.path.join(launch['box'], gitws.BOX, 'ORDER.json')
            with open(path, encoding='utf-8') as f:
                doc = json.load(f)
            if seat == 'planner':
                doc['rules'] += (' Read _dispatch/LIBRARY.json before planning. Reuse what fits. '
                                 'Name the library entry ids you used in plan.json "uses": ["id", ...]. '
                                 'You may propose new or better skills in "propose": '
                                 '[{"kind": "skill", "title": "...", "text": "...", "replaces": null, "why": "..."}]. '
                                 'Use at most 3 proposals, each at most 8 KB of UTF-8 text. '
                                 'Proposals need a person to accept them before any seat follows them.')
            else:
                doc['rules'] += ' Read _dispatch/LIBRARY.json and follow the listed skills that fit this order.'
            atomic(path, json.dumps(doc, ensure_ascii=False, indent=1))
            self.library_context(launch)
        return launch

    def plan(self, launch):
        result = super().plan(launch)
        if self.library is not None and launch.get('outcome') == 'planned':
            with open(os.path.join(launch['box'], gitws.BOX, 'plan.json'), encoding='utf-8') as f:
                plan = json.load(f)
            self.library.record_plan(os.path.basename(self.root), launch, plan, self.clock.now)
        return result

    def save(self):
        """Never the ledger: its writer owns it."""
        keep = ('order', 'token', 'agent', 'seat', 'attempt', 'launch', 't0', 't1') + KEEP
        row = lambda L: json.dumps({k: L[k] for k in keep if k in L}, ensure_ascii=False) + '\n'
        atomic(os.path.join(self.root, 'replies.jsonl'), ''.join(json.dumps(r, ensure_ascii=False) + '\n' for r in self.replies))
        atomic(os.path.join(self.root, 'launches.jsonl'), ''.join(row(L) for L in self.launches if 't1' in L and L.get('outcome') is not None))

    def ready(self, o, snap):
        return not self.guard.halted and super().ready(o, snap)

    def collect(self, L):
        if self.stopping() and not L.get('held'):
            L['held'] = L['error'] = STOPPED
        if L.get('held'):
            self.give_back(L, 'held', {'why': L['held']})
        else:
            super().collect(L)
        self.board()

    def rule(self, o):
        if o['accept']['judge'] != self.judge_id:
            return                              # somebody else's to rule: it waits in JUDGING for their verdict
        super().rule(o)
        self.board()


def unlocked(runner, gate, stopping):
    """The agent's process runs with the lock let go.  step() calls a runner with the lock held exactly once."""
    def run(box, ctx):
        ctx.ad.library_context(ctx.launch)
        gate.release()
        try:
            if stopping():
                ctx.launch['held'] = STOPPED
                return
            runner(box, ctx)
        finally:
            gate.acquire()
    return run


class Live:
    def __init__(self, run, team, server, limit=A.MAX_TOTAL, wall=A.WALL, judge=None, exe=None, every=5, pace=1.0, clock=None):
        """run: a folder that does not exist yet.  server(gate, run, clock) -> the HTTP server (it owns the ledger's writer)."""
        os.makedirs(run)
        self.run, self.team, self.pace, self.limit, self.wall = run, team, pace, limit, wall
        self.clock = clock or time.time
        atomic(os.path.join(run, 'team.json'), json.dumps(team, ensure_ascii=False, indent=1))
        self.gate, self.stop, self.guard = threading.RLock(), threading.Event(), A.Guard(limit)
        self.fatal, self.errors, self.closed, self.ad, self.doc, self.sizes = None, 0, False, None, '{}', {}
        pinned = os.path.join(run, 'judge.py')
        shutil.copyfile(judge or os.path.join(HERE, 'judge_floor.py'), pinned)
        lead, seats = team['lead'], team['seats']
        self.lead = 'team:' + lead['id']
        self.cast = [(self.lead, lead)] + [('agent:' + s['id'], s) for s in seats]
        self.org = [(self.lead, CEO)] + [x for s in seats for x in (('team:' + s['id'], self.lead), ('agent:' + s['id'], 'team:' + s['id']))]
        self.srv = server(self.gate, run, self.now)
        self.srv.live = self
        self.url = 'http://%s:%d' % (cli.BIND, self.srv.server_address[1])
        try:
            env = A.clean_env(team['pass_env'], team['permission'])
            agents = {who: unlocked(A.Runner(s['model'], self.guard, run, exe=exe, env=env, wall=wall, board=self.board, every=every, clock=self.now), self.gate, self.stop.is_set)
                      for who, s in self.cast}
            self.ad = Adapter(run, Through(self.srv.writer, self.gate), agents, pinned, gitws.Clock(self.now()), judge_id=JUDGE, max_launches=A.MAX_PER_ORDER)
            self.ad.guard, self.ad.board, self.ad.stopping = self.guard, self.board, self.stop.is_set
            self.ad.library = getattr(self.srv, 'library', None)
            self.ad.open_topic(TOPIC)
            for actor, boss in self.org:
                r = self.ad.send(CEO, 'org.set', {'actor': actor, 'superior': boss})
                if not r['ok']:
                    raise RuntimeError('org.set %s was refused: %r' % (actor, r))
            self.board()
        except BaseException:
            self.srv.server_close()
            raise
        self.threads = [threading.Thread(target=self.work, name='adapter', daemon=True), threading.Thread(target=self.srv.serve_forever, name='http', daemon=True)]

    def now(self):
        t = int(self.clock()) + self.guard.skew
        return max(t, self.ad.clock.now) if self.ad is not None else t

    # ---- what the page reads besides the ledger
    def files(self):
        """The newest revision of every file a worker handed in: [{path, rev, order, size, accepted}]."""
        ad, newest = self.ad, {}
        for (key, rev), sha in ad.blobs.items():
            if rev >= newest.get(key, (0, None))[0]:
                newest[key] = (rev, sha)
        try:
            ok = ad.git.tree('refs/tags/accepted/' + TOPIC)
        except RuntimeError:                    # nothing has been accepted yet: the tag does not exist
            ok = {}
        out = []
        for key, (rev, sha) in sorted(newest.items()):
            if sha not in self.sizes:
                self.sizes[sha] = int(ad.git('cat-file', '-s', sha))
            by = [L['order'] for L in ad.launches if key in L.get('taken', ())]
            out.append({'path': key, 'rev': rev, 'order': by[-1] if by else None, 'size': self.sizes[sha], 'accepted': ok.get(key) == sha})
        return out

    def read_file(self, path, limit=65536):
        """The text of one handed-in file, by its key (never a path on this machine's disk)."""
        with self.gate:
            revs = [r for (k, r) in self.ad.blobs if k == path]
            if not revs:
                return None
            data = self.ad.git.raw('cat-file', 'blob', self.ad.blobs[(path, max(revs))])
        try:
            text, binary = data[:limit].decode('utf-8'), False
        except UnicodeDecodeError:
            text, binary = '', True
        return {'path': path, 'rev': max(revs), 'size': len(data), 'text': text, 'binary': binary, 'truncated': len(data) > limit}

    def board(self):
        with self.gate:
            ad, g = self.ad, self.guard
            if ad is None:
                return
            ad.save()
            Ls = {(L['order'], L['token'], L['launch']): L for L in ad.launches}
            recs = []
            for r in list(g.records):
                L, rec = Ls.get((r['order'], r['token'], r['launch']), {}), dict(r)
                rec.update({k: L[k] for k in KEEP if k in L})
                mine = [p for p in rec.get('outside_box') or () if p in OWN]
                rec['outside_box'] = [p for p in rec.get('outside_box') or () if p not in mine]
                recs.append(rec)
            seat = lambda who, s, role, up: {'actor': who, 'name': s.get('name') or s['id'], 'model': s['model'], 'family': family(s['model']), 'role': role, 'parent': up}
            doc = {'v': 'cockpit/1', 'run': os.path.basename(self.run), 'backend': self.url, 'state': 'fatal' if self.fatal else 'halted' if g.halted else 'running',
                   'halted': g.halted, 'fatal': self.fatal, 'launched': sum(g.n.values()), 'limit': g.limit, 'per_order': A.MAX_PER_ORDER, 'wall': self.wall,
                   'ceo': CEO, 'judge': JUDGE, 'lead': self.lead, 'topic': TOPIC,
                   'seats': [seat(self.lead, self.team['lead'], 'lead', CEO)] + [dict(seat('agent:' + s['id'], s, 'worker', self.lead), team='team:' + s['id']) for s in self.team['seats']],
                   'launches': recs, 'held': list(g.held), 'files': self.files(), 'updated': self.now()}
            self.doc = json.dumps(doc, ensure_ascii=False)
            os.makedirs(os.path.join(self.run, 'logs'), exist_ok=True)
            atomic(os.path.join(self.run, 'logs', 'team.json'), json.dumps(doc, ensure_ascii=False, indent=1))
            if ad.library is not None:
                ad.library.sync(self.srv.history)

    # ---- the adapter's thread
    def once(self):
        with self.gate:
            self.ad.clock.now = max(self.ad.clock.now, self.now())
            did = self.ad.step()
            self.board()
            return did

    def work(self):
        while not self.stop.is_set():
            try:
                self.once()
                self.errors = 0
            except cli.Moved as e:              # someone else wrote the ledger: nothing more may be written from here
                self.fatal = str(e)
            except Exception:
                self.errors += 1
                say('WARNING a step failed (%d in a row):\n%s' % (self.errors, traceback.format_exc()[-1500:]))
                if self.errors >= 5:
                    self.fatal = 'five steps in a row failed: stopped'
            if self.fatal:
                say('ERROR %s' % self.fatal)
                self.stop.set()
                self.board()
                break
            self.stop.wait(self.pace)

    def start(self):
        for t in self.threads:
            t.start()
        return self

    def close(self, wait=60):
        """Stop: whatever agent is running is ended and what it wrote is not collected."""
        if self.closed:
            return True
        self.closed = True
        self.stop.set()
        for pid in list(A.RUNNING):
            try:
                os.killpg(pid, signal.SIGTERM)  # launch() starts each agent in a process group of its own
            except OSError:
                pass
        self.threads[0].join(wait)
        self.srv.shutdown()
        self.threads[1].join(10)
        alive = self.threads[0].is_alive()
        if alive:
            say('WARNING the working thread did not stop within %d seconds; the ledger may hold a step it had not finished' % wait)
        self.srv.server_close()
        return not alive
