#!/usr/bin/env python3
"""Start one OpenCode process for one order, and read what it printed.

The only agent command this backend ever runs is

    opencode run --format json -m <provider/model> --title <order id> "<PROMPT>"

with the order's sandbox as the working directory.  The agent finds everything it needs in _dispatch/ORDER.json there.

What the process is given:
  * a clean environment: only the variables in KEEP plus the ones the team file lists under `pass_env` (the names of
    your provider keys).  Nothing else of the shell that started the backend reaches the agent;
  * OpenCode's own switches: no auto-update, no session sharing, no reading of another tool's skills folder;
  * a permission config through OPENCODE_CONFIG_CONTENT.  A non-interactive `opencode run` cannot ask a person, so a
    rule that says "ask" ends the run on the spot: every rule here is allow or deny.

Nothing here is tied to a subscription: the only limits are how many processes one backend may start, how many per
order, and a wall clock per process.  What a model costs is whatever OpenCode reports in its step_finish events."""
import json
import os
import signal
import subprocess
import time

MAX_TOTAL, MAX_PER_ORDER, WALL = 12, 2, 600
KEEP = ('PATH', 'HOME', 'LANG', 'LC_ALL', 'LC_CTYPE', 'TERM', 'TMPDIR', 'XDG_CONFIG_HOME', 'XDG_DATA_HOME', 'XDG_CACHE_HOME', 'XDG_STATE_HOME')
SWITCHES = {'OPENCODE_DISABLE_AUTOUPDATE': '1', 'OPENCODE_DISABLE_SHARE': '1', 'OPENCODE_DISABLE_CLAUDE_CODE': '1'}
PERMISSION = {'external_directory': 'deny', 'doom_loop': 'deny'}      # OpenCode's two default "ask" rules; a team file may add more
PROMPT = ('Read _dispatch/ORDER.json in this folder first. Do what its "rules" and "order" say, and nothing else. '
          'Work only inside this folder. Write files with your file-writing tool, not with shell redirection. '
          'If ORDER.json has "verify", run verify.cmd as a command of its own, copied exactly, before you finish. '
          'When the work is done, stop.')
RUNNING = set()                     # process groups of the agents running right now: what a stop has to end
REFUSED = 'rejected permission'     # what OpenCode's tool error says when a rule answered "ask" and nobody could answer


def binary():
    """The executable to start: $OPENCODE_BIN when set (a test points it at a stand-in), else `opencode` on PATH."""
    return os.environ.get('OPENCODE_BIN') or 'opencode'


def opencode_argv(model, title, exe=None):
    return [exe or binary(), 'run', '--format', 'json', '-m', model, '--title', title, PROMPT]


def clean_env(pass_env=(), permission=None, base=None):
    base = os.environ if base is None else base
    env = {k: base[k] for k in tuple(KEEP) + tuple(pass_env) if k in base}
    env.update(SWITCHES)
    env['OPENCODE_CONFIG_CONTENT'] = json.dumps({'permission': dict(PERMISSION, **(permission or {}))})
    return env


class Guard:
    """Counts launches and decides, before each one, whether it may start.  The first no stops everything after it."""

    def __init__(self, limit=MAX_TOTAL, clock=time.time):
        self.limit, self.clock, self.n = limit, clock, {}
        self.halted, self.checks, self.records, self.held, self.skew = None, [], [], [], 0

    def allow(self, kind):
        now, why, total = self.clock(), self.halted, sum(self.n.values())
        if why is None and total >= self.limit:
            why = 'this backend has already started %d agent process(es) (its limit is %d)' % (total, self.limit)
        self.checks.append({'at': now, 'kind': kind, 'ok': why is None, 'why': why, 'counts': dict(self.n)})
        if why is not None:
            self.halted = why
        return why is None, why


def launch(argv, cwd, out_path, err_path, env=None, wall=WALL, tick=None, every=5):
    """Run it in a process group of its own; kill the group at the wall clock.  {'rc', 'secs', 'killed'}.
    A model that is rate-limited makes `opencode run` hang without printing anything: the wall clock is what ends it."""
    t = time.time()
    with open(out_path, 'wb') as out, open(err_path, 'wb') as err:
        try:
            p = subprocess.Popen(argv, cwd=cwd, env=env, stdin=subprocess.DEVNULL, stdout=out, stderr=err, start_new_session=True)
        except OSError as e:
            return {'rc': None, 'secs': 0.0, 'killed': False, 'error': repr(e)[:200]}
        RUNNING.add(p.pid)
        killed = False
        while True:
            left = wall - (time.time() - t)
            if left <= 0:
                killed = True
                break
            try:
                p.wait(timeout=min(every, left))
                break
            except subprocess.TimeoutExpired:
                if tick:
                    tick()
        for sig in (signal.SIGTERM, signal.SIGKILL):         # also after a clean exit: nothing it started may keep writing
            try:
                os.killpg(p.pid, sig)
            except OSError:
                break
            try:
                p.wait(timeout=10)
            except subprocess.TimeoutExpired:
                continue
            if not killed:
                break
        p.wait()
        RUNNING.discard(p.pid)
    return {'rc': p.returncode, 'secs': round(time.time() - t, 1), 'killed': killed}


def fingerprint(root, skip=()):
    """{path: (size, mtime_ns)} of everything under root outside the folders in skip."""
    skip, out = {os.path.abspath(s) for s in skip}, {}
    for d, dirs, names in os.walk(root):
        dirs[:] = [x for x in dirs if os.path.abspath(os.path.join(d, x)) not in skip]
        for n in names:
            p = os.path.join(d, n)
            try:
                st = os.lstat(p)
            except OSError:
                continue
            out[os.path.relpath(p, root)] = (st.st_size, st.st_mtime_ns)
    return out


def jsonl(path):
    try:
        with open(path, encoding='utf-8', errors='replace') as f:
            for line in f:
                try:
                    e = json.loads(line)
                except ValueError:
                    continue
                if isinstance(e, dict):
                    yield e
    except OSError:
        return


def read_opencode(stem):
    """What one `opencode run --format json` printed, added up.  The event shapes are the ones observed on opencode 1.x
    ({type, part: {...}}); a field that is missing counts as nothing, and the raw log stays next to this."""
    out = {'events': 0, 'steps': 0, 'tools': {}, 'tool_errors': 0, 'refused': 0, 'errors': [], 'cost': 0.0,
           'tokens': {'input': 0, 'output': 0, 'reasoning': 0, 'cache_read': 0, 'cache_write': 0}, 'text': ''}
    for e in jsonl(stem + '.out'):
        out['events'] += 1
        t, p = e.get('type'), e.get('part') if isinstance(e.get('part'), dict) else {}
        if t == 'step_finish':
            out['steps'] += 1
            out['cost'] += p.get('cost') or 0
            tk = p.get('tokens') if isinstance(p.get('tokens'), dict) else {}
            for k in ('input', 'output', 'reasoning'):
                out['tokens'][k] += tk.get(k) or 0
            cache = tk.get('cache') if isinstance(tk.get('cache'), dict) else {}
            out['tokens']['cache_read'] += cache.get('read') or 0
            out['tokens']['cache_write'] += cache.get('write') or 0
        elif t == 'tool_use':
            name = str(p.get('tool'))
            out['tools'][name] = out['tools'].get(name, 0) + 1
            st = p.get('state') if isinstance(p.get('state'), dict) else {}
            if st.get('status') == 'error':
                out['tool_errors'] += 1
                if REFUSED in str(st.get('error', '')):
                    out['refused'] += 1
        elif t == 'text':
            out['text'] = str(p.get('text') or '')[-400:]
        elif t == 'error':
            out['errors'].append(json.dumps(e.get('error', e), ensure_ascii=False)[:300])
    return out


class Runner:
    """runner(sandbox, ctx) for one seat.  `model` is what the seat's -m says; `exe` and `env` come from the team file."""

    def __init__(self, model, guard, root, exe=None, env=None, wall=WALL, board=None, every=5, clock=None):
        self.model, self.guard, self.root, self.exe, self.env = model, guard, root, exe, env
        self.wall, self.board, self.every = wall, board or (lambda: None), every
        self.clock = clock or (lambda: int(time.time()) + self.guard.skew)

    def sync(self, ctx):
        """The ledger's clock follows the wall clock (plus whatever a killed launch was made to wait)."""
        d = self.clock() - ctx.ad.clock.now
        if d > 0:
            ctx.wait(d)
        self.board()

    def __call__(self, box, ctx):
        L, g = ctx.launch, self.guard
        self.sync(ctx)
        ok, why = g.allow(self.model)
        if not ok:
            L['held'] = why
            g.held.append({'order': L['order'], 'kind': self.model, 'why': why, 'at': self.clock()})
            self.board()
            return
        g.n[self.model] = g.n.get(self.model, 0) + 1
        n, logs = sum(g.n.values()), os.path.join(self.root, 'logs')
        os.makedirs(logs, exist_ok=True)
        stem = os.path.join(logs, '%02d-%s' % (n, L['order']))
        argv = opencode_argv(self.model, '%s#%d' % (L['order'], L['launch']), self.exe)
        rec = {'n': n, 'model': self.model, 'order': L['order'], 'token': L['token'], 'seat': L['seat'], 'agent': L['agent'], 'launch': L['launch'],
               'started': self.clock(), 'state': 'running', 'log': os.path.basename(stem), 'argv': ['<prompt>' if a == PROMPT else a for a in argv]}
        g.records.append(rec)
        self.board()
        before = fingerprint(self.root, (box, logs))
        r = launch(argv, box, stem + '.out', stem + '.err', env=self.env, wall=self.wall, tick=lambda: self.sync(ctx), every=self.every)
        after = fingerprint(self.root, (box, logs))
        self.sync(ctx)
        rec.update(r, state='killed' if r['killed'] else 'ended', seen=read_opencode(stem),
                   outside_box=sorted(p for p in set(before) | set(after) if before.get(p) != after.get(p)))
        if r['killed']:                                      # its lease is not renewed any more and runs out; the fence then refuses what it left
            L['killed'] = True
            ctx.wait(ctx.ad.ttl + 1, alive=False)
            g.skew += ctx.ad.ttl + 1
        self.board()
