"""Human-triggered plans, kept outside the dispatcher ledger. Call while holding the server lock."""
import datetime
import json
import os
import re
import uuid

import history
import live

CRITERIA = 'Files are handed in under the write scope, are not empty and read as what they claim to be.'


def envelope(fields, oid, lead, message_id):
    """The same order.issue envelope used by the day form, sent through the ledger writer."""
    return {'v': 'dispatch/1', 'id': message_id, 'from': live.CEO, 'to': 'dispatcher', 'kind': 'order.issue',
            'body': {'id': oid, 'title': fields['title'], 'goal': fields['goal'], 'to': lead,
                     'writes': [fields['writes'] or oid + '/'], 'budget': fields['budget'],
                     'accept': {'judge': live.JUDGE, 'criteria': CRITERIA}}}


class Plans:
    def __init__(self, root, clock):
        self.path, self.clock = os.path.join(root, 'planned.jsonl'), clock

    def read(self):
        plans = {}
        try:
            with open(self.path, encoding='utf-8') as f:
                for line in f:
                    e = json.loads(line)
                    if e['kind'] == 'planned.added':
                        plans[e['id']] = dict(e, state='waiting', run=None, order=None)
                    elif e['kind'] == 'planned.cancelled':
                        plans[e['id']]['state'] = 'cancelled'
                    elif e['kind'] == 'planned.issued':
                        plans[e['id']].update(state='issued', run=e['run'], order=e['order'])
                    else:
                        raise ValueError('unknown planned event')
        except FileNotFoundError:
            pass
        today = history.day(self.clock())
        for p in plans.values():
            if p['state'] == 'waiting' and p['day'] <= today:
                p['state'] = 'due'
        return plans

    def append(self, kind, **fields):
        data = (json.dumps(dict(fields, kind=kind, t=self.clock()), ensure_ascii=False) + '\n').encode('utf-8')
        fd = os.open(self.path, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
        try:
            while data:
                data = data[os.write(fd, data):]
            os.fsync(fd)
        finally:
            os.close(fd)

    def add(self, fields):
        day = fields.get('day')
        if not isinstance(day, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', day):
            raise ValueError('day must be a real date written YYYY-MM-DD')
        datetime.date.fromisoformat(day)
        if day <= history.day(self.clock()):
            raise ValueError('plan a later day; issue today directly from its day page')
        values = {}
        for key, limit in (('title', 80), ('goal', 4000), ('writes', 120)):
            value = fields.get(key, '' if key == 'writes' else None)
            if not isinstance(value, str) or len(value) > limit or (key != 'writes' and not value.strip()):
                raise ValueError(key + ' must be text within its limit and title and goal cannot be empty')
            values[key] = value.strip()
        budget = fields.get('budget', 6)
        if type(budget) is not int or not 1 <= budget <= 99:
            raise ValueError('budget must be an integer from 1 to 99')
        scope = values['writes']
        if scope and (scope.startswith('/') or '\\' in scope or any(p in ('.', '..', '') for p in scope.rstrip('/').split('/'))):
            raise ValueError('writes must be a relative file key or folder scope')
        pid = 'plan-' + uuid.uuid4().hex
        self.append('planned.added', id=pid, day=day, budget=budget, **values)
        return {'id': pid, 'state': 'waiting'}

    def act(self, action, pid, server):
        p = self.read().get(pid)
        if p is None:
            return 404, {'cli': 'not-found'}
        if p['state'] == 'issued':
            return 409, {'cli': 'already-issued', 'run': p['run'], 'order': p['order']}
        if p['state'] == 'cancelled':
            return 409, {'cli': 'cancelled'}
        if action == 'issue' and p['state'] == 'waiting':
            return 409, {'cli': 'not-due'}
        # Repair a crash between the durable order row and planned.issued, even across a restart.
        runs, _ = server.history.runs()
        for run, r in runs.items():
            if any(e['kind'] == 'order.issued' and e['cause'] == pid for e in r['events']):
                self.append('planned.issued', id=pid, run=run, order=pid)
                return 409, {'cli': 'already-issued', 'run': run, 'order': pid}
        if action == 'cancel':
            self.append('planned.cancelled', id=pid)
            return 200, {'id': pid, 'state': 'cancelled'}
        result = server.writer.submit(envelope(p, pid, server.live.lead, pid), server.clock())
        if not result.get('ok'):
            return 409, result
        run = server.history.current
        self.append('planned.issued', id=pid, run=run, order=pid)
        return 200, {'id': pid, 'state': 'issued', 'run': run, 'order': pid}
