 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "dispatch/1/event",
 "title": "One line of the ledger. Only the dispatcher writes these; the state of everything is what you get by reading them in order",
 "type": "object",
 "required": [
  "seq",
  "t",
  "kind",
  "cause",
  "n",
  "by"
 ],
 "properties": {
  "seq": {
   "type": "integer",
   "minimum": 1
  },
  "t": {
   "type": "number",
   "description": "the dispatcher's clock"
  },
  "kind": {
   "enum": [
    "org.set",
    "pool.set",
    "order.issued",
    "order.amended",
    "order.cancelled",
    "lease.granted",
    "lease.renewed",
    "lease.released",
    "lease.expired",
    "order.dead",
    "artifact.rev",
    "notice.input-moved",
    "report.progress",
    "report.submitted",
    "order.succeeded",
    "order.failed",
    "ask.raised",
    "ask.answered"
   ]
  },
  "cause": {
   "type": "string",
   "description": "the envelope id that caused it, or clock:<seq> when time alone did"
  },
  "n": {
   "type": "integer",
   "minimum": 0
  },
  "by": {
   "type": "string"
  },
  "h": {
   "type": "string",
   "description": "content hash of the envelope, on its first event"
  }
 },
 "allOf": [
  {
   "if": {
    "properties": {
     "kind": {
      "const": "org.set"
     }
    }
   },
   "then": {
    "required": [
     "actor",
     "superior"
    ],
    "properties": {
     "actor": {
      "type": "string",
      "minLength": 1
     },
     "superior": {
      "type": [
       "string",
       "null"
      ]
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "pool.set"
     }
    }
   },
   "then": {
    "required": [
     "pool",
     "cap"
    ],
    "properties": {
     "pool": {
      "type": "string",
      "minLength": 1
     },
     "cap": {
      "type": "integer",
      "minimum": 0
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.issued"
     }
    }
   },
   "then": {
    "required": [
     "body"
    ],
    "properties": {
     "body": {
      "type": "object",
      "properties": {
       "id": {
        "type": "string",
        "minLength": 1
       },
       "parent": {
        "type": [
         "string",
         "null"
        ]
       },
       "goal": {
        "type": "string"
       },
       "to": {
        "type": "string",
        "pattern": "^(team|agent):.+"
       },
       "writes": {
        "type": "array",
        "items": {
         "type": "string",
         "minLength": 1
        }
       },
       "reads": {
        "type": "array",
        "items": {
         "type": "object",
         "required": [
          "key",
          "rev"
         ],
         "additionalProperties": false,
         "properties": {
          "key": {
           "type": "string",
           "minLength": 1
          },
          "rev": {
           "type": "integer",
           "minimum": 1
          },
          "released": {
           "type": "boolean"
          }
         }
        }
       },
       "after": {
        "type": "array",
        "items": {
         "type": "string",
         "minLength": 1
        }
       },
       "needs": {
        "type": "object",
        "additionalProperties": {
         "type": "integer",
         "minimum": 0
        }
       },
       "budget": {
        "type": "number",
        "minimum": 0
       },
       "priority": {
        "type": "integer"
       },
       "due": {
        "type": [
         "string",
         "null"
        ]
       },
       "accept": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
         "judge": {
          "type": "string",
          "pattern": "^(human|team|agent|program):.+"
         },
         "criteria": {
          "type": "string",
          "minLength": 1
         }
        }
       },
       "unverified": {
        "type": "array",
        "items": {
         "type": "object",
         "additionalProperties": false,
         "properties": {
          "what": {
           "type": "string",
           "minLength": 1
          },
          "owner": {
           "type": "string",
           "pattern": "^(human|team|agent|program):.+"
          }
         }
        }
       },
       "title": {
        "type": "string"
       },
       "skills": {
        "type": "array",
        "items": {
         "type": "string",
         "minLength": 1
        },
        "description": "the skills this order should be done with, by name or path; carried to the holder as written, never checked or acted on by the dispatcher"
       },
       "knowledge": {
        "type": "array",
        "items": {
         "type": "string",
         "minLength": 1
        },
        "description": "what to read before starting, by name or path; carried to the holder as written, never checked or acted on by the dispatcher"
       }
      },
      "additionalProperties": false,
      "required": [
       "accept",
       "after",
       "budget",
       "due",
       "goal",
       "id",
       "needs",
       "parent",
       "priority",
       "reads",
       "title",
       "to",
       "unverified",
       "writes"
      ],
      "description": "the order as issued, every field filled in but the optional skills and knowledge (there only when the order gave them); the types are those of order.json"
     },
     "under": {
      "type": "object",
      "required": [
       "order",
       "token"
      ],
      "additionalProperties": false,
      "properties": {
       "order": {
        "type": "string",
        "minLength": 1
       },
       "token": {
        "type": "integer",
        "minimum": 1
       }
      },
      "description": "on a sub-order: the lease on its parent it was issued under"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.amended"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "patch",
     "basis"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "basis": {
      "type": "integer",
      "minimum": 0
     },
     "patch": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
       "priority": {
        "type": "integer"
       },
       "due": {
        "type": [
         "string",
         "null"
        ]
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.cancelled"
     }
    }
   },
   "then": {
    "required": [
     "order"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "basis": {
      "type": "integer",
      "minimum": 0
     },
     "reason": {
      "type": "string"
     },
     "cascade": {
      "type": "boolean"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "lease.granted"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "token",
     "expires",
     "basis"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     },
     "expires": {
      "type": "number"
     },
     "basis": {
      "type": "integer",
      "minimum": 0
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "lease.renewed"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "token",
     "expires"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     },
     "expires": {
      "type": "number"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "lease.released"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "token"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     },
     "reason": {
      "type": "string"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "lease.expired"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "token"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.dead"
     }
    }
   },
   "then": {
    "required": [
     "order"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "artifact.rev"
     }
    }
   },
   "then": {
    "required": [
     "key",
     "seen",
     "rev",
     "order",
     "token"
    ],
    "properties": {
     "key": {
      "type": "string",
      "minLength": 1
     },
     "seen": {
      "type": "integer",
      "minimum": 0
     },
     "rev": {
      "type": "integer",
      "minimum": 1
     },
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     },
     "note": {
      "type": "string"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "notice.input-moved"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "key",
     "pinned",
     "rev",
     "to"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "key": {
      "type": "string",
      "minLength": 1
     },
     "pinned": {
      "type": "integer",
      "minimum": 1
     },
     "rev": {
      "type": "integer",
      "minimum": 1
     },
     "to": {
      "type": "string",
      "minLength": 1
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "report.progress"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "token"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     },
     "note": {
      "type": "string"
     },
     "pct": {
      "type": [
       "number",
       "null"
      ]
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "report.submitted"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "token",
     "outputs"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "token": {
      "type": "integer",
      "minimum": 1
     },
     "evidence": {
      "type": "string"
     },
     "outputs": {
      "type": "array",
      "items": {
       "type": "object",
       "required": [
        "key",
        "rev"
       ],
       "additionalProperties": false,
       "properties": {
        "key": {
         "type": "string",
         "minLength": 1
        },
        "rev": {
         "type": "integer",
         "minimum": 1
        }
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.succeeded"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "basis"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "basis": {
      "type": "integer",
      "minimum": 0
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.failed"
     }
    }
   },
   "then": {
    "required": [
     "order",
     "retry",
     "basis"
    ],
    "properties": {
     "order": {
      "type": "string",
      "minLength": 1
     },
     "retry": {
      "type": "boolean"
     },
     "basis": {
      "type": "integer",
      "minimum": 0
     },
     "reason": {
      "type": "string"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "ask.raised"
     }
    }
   },
   "then": {
    "required": [
     "ask",
     "to",
     "text"
    ],
    "properties": {
     "ask": {
      "type": "string",
      "minLength": 1
     },
     "to": {
      "type": "string",
      "minLength": 1
     },
     "text": {
      "type": "string"
     },
     "about": {
      "type": [
       "string",
       "null"
      ]
     },
     "blocking": {
      "type": "boolean"
     },
     "proposal": {
      "type": "object",
      "description": "the order a proposal asks for, as it was sent"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "ask.answered"
     }
    }
   },
   "then": {
    "required": [
     "ask",
     "answer"
    ],
    "properties": {
     "ask": {
      "type": "string",
      "minLength": 1
     },
     "answer": {
      "type": "string"
     }
    }
   }
  }
 ]
}
OC_EOF_15
cat > 'cockpit/schema/message.json' <<'OC_EOF_16'
{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "dispatch/1/message",
 "title": "Everything anyone asks of the dispatcher: a click, a typed prompt and an agent action all look like this",
 "type": "object",
 "required": [
  "v",
  "id",
  "from",
  "to",
  "kind",
  "body"
 ],
 "additionalProperties": false,
 "properties": {
  "v": {
   "const": "dispatch/1"
  },
  "id": {
   "type": "string",
   "pattern": "^(?!clock:).+",
   "description": "chosen by the sender; sending the same id again changes nothing"
  },
  "ts": {
   "type": "string",
   "description": "the sender's clock; for reading only, never used to decide anything"
  },
  "from": {
   "type": "string",
   "pattern": "^(human|team|agent|program):.+"
  },
  "to": {
   "const": "dispatcher"
  },
  "kind": {
   "enum": [
    "org.set",
    "pool.set",
    "order.issue",
    "order.amend",
    "order.cancel",
    "order.propose",
    "claim.request",
    "lease.renew",
    "lease.release",
    "artifact.put",
    "report.progress",
    "report.submit",
    "verdict",
    "ask.raise",
    "ask.answer",
    "state.query"
   ]
  },
  "basis": {
   "type": "integer",
   "minimum": 0,
   "description": "the last ledger number the sender had seen when it decided"
  },
  "lease": {
   "type": "object",
   "required": [
    "order",
    "token"
   ],
   "additionalProperties": false,
   "properties": {
    "order": {
     "type": "string",
     "minLength": 1
    },
    "token": {
     "type": "integer",
     "minimum": 1
    }
   }
  },
  "body": {
   "type": "object"
  }
 },
 "allOf": [
  {
   "if": {
    "properties": {
     "kind": {
      "const": "org.set"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "actor"
      ],
      "properties": {
       "actor": {
        "type": "string",
        "pattern": "^(human|team|agent|program):.+"
       },
       "superior": {
        "type": [
         "string",
         "null"
        ]
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "pool.set"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "pool",
       "cap"
      ],
      "properties": {
       "pool": {
        "type": "string",
        "minLength": 1
       },
       "cap": {
        "type": "integer",
        "minimum": 0
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.issue"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "$ref": "order.json"
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.amend"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "order",
       "patch"
      ],
      "properties": {
       "order": {
        "type": "string",
        "minLength": 1
       },
       "patch": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
         "priority": {
          "type": "integer"
         },
         "due": {
          "type": [
           "string",
           "null"
          ]
         }
        }
       }
      }
     }
    },
    "required": [
     "basis"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.cancel"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "order"
      ],
      "properties": {
       "order": {
        "type": "string",
        "minLength": 1
       },
       "reason": {
        "type": "string"
       }
      }
     }
    },
    "required": [
     "basis"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "order.propose"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "order"
      ],
      "properties": {
       "order": {
        "type": "object"
       },
       "text": {
        "type": "string"
       },
       "to_superior": {
        "type": "string",
        "pattern": "^(human|team|agent|program):.+"
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "claim.request"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "order"
      ],
      "properties": {
       "order": {
        "type": "string",
        "minLength": 1
       },
       "ttl": {
        "type": "integer",
        "minimum": 1
       }
      }
     }
    },
    "required": [
     "basis"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "lease.renew"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
       "ttl": {
        "type": "integer",
        "minimum": 1
       }
      }
     }
    },
    "required": [
     "lease"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "lease.release"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
       "reason": {
        "type": "string"
       }
      }
     }
    },
    "required": [
     "lease"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "artifact.put"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "key",
       "expect"
      ],
      "properties": {
       "key": {
        "type": "string",
        "minLength": 1
       },
       "expect": {
        "type": "integer",
        "minimum": 0
       },
       "note": {
        "type": "string"
       }
      }
     }
    },
    "required": [
     "lease"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "report.progress"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
       "note": {
        "type": "string"
       },
       "pct": {
        "type": [
         "number",
         "null"
        ]
       }
      }
     }
    },
    "required": [
     "lease"
    ]
   }
  },
  {
   "if": {
    "properties": {
     "kind": {
      "const": "report.submit"
     }
    }
   },
   "then": {
    "properties": {
     "body": {
      "type": "object",
      "additionalProperties": false,
