#!/usr/bin/env python3
"""The part of JSON Schema these four files use, in the standard library (no jsonschema module on this machine).
   python3 -I schema/validate.py message|reply|event|order file.jsonl      exit 0 all lines fit, 1 some do not, 2 could not read"""
import json, os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
TYPES = {'object': dict, 'array': list, 'string': str, 'boolean': bool, 'null': type(None)}
KNOWN = {'$schema', '$id', '$ref', 'title', 'description', 'type', 'const', 'enum', 'required', 'properties', 'additionalProperties', 'items', 'pattern', 'minimum', 'minLength', 'allOf', 'if', 'then'}
_cache = {}


def load(name):
    if name not in _cache:
        with open(os.path.join(HERE, name if name.endswith('.json') else name + '.json'), encoding='utf-8') as f:
            _cache[name] = json.load(f)
    return _cache[name]


def is_type(v, t):
    if t == 'integer':
        return isinstance(v, int) and not isinstance(v, bool)
    if t == 'number':
        return isinstance(v, (int, float)) and not isinstance(v, bool)
    return isinstance(v, TYPES[t])


def errors(v, s, at='$'):
    unknown = set(s) - KNOWN
    if unknown:
        raise ValueError('schema keyword not supported here: %s' % sorted(unknown))
    out = []
    if '$ref' in s:
        out += errors(v, load(s['$ref']), at)
    if 'type' in s and not any(is_type(v, t) for t in ([s['type']] if isinstance(s['type'], str) else s['type'])):
        return out + ['%s: expected %s' % (at, s['type'])]
    if 'const' in s and v != s['const']:
        out.append('%s: must be %r' % (at, s['const']))
    if 'enum' in s and v not in s['enum']:
        out.append('%s: %r is not one of the allowed values' % (at, v))
    if isinstance(v, str):
        if len(v) < s.get('minLength', 0):
            out.append('%s: too short' % at)
        if 'pattern' in s and not re.search(s['pattern'], v):
            out.append('%s: does not match %s' % (at, s['pattern']))
    if is_type(v, 'number') and 'minimum' in s and v < s['minimum']:
        out.append('%s: below %s' % (at, s['minimum']))
    if isinstance(v, dict):
        out += ['%s: missing %s' % (at, k) for k in s.get('required', []) if k not in v]
        props, more = s.get('properties', {}), s.get('additionalProperties', True)
        for k, x in v.items():
            if k in props:
                out += errors(x, props[k], '%s.%s' % (at, k))
            elif more is False:
                out.append('%s: unexpected %s' % (at, k))
            elif isinstance(more, dict):
                out += errors(x, more, '%s.%s' % (at, k))
    if isinstance(v, list) and 'items' in s:
        for i, x in enumerate(v):
            out += errors(x, s['items'], '%s[%d]' % (at, i))
    for sub in s.get('allOf', []):
        out += errors(v, sub, at)
    if 'if' in s and not errors(v, s['if'], at):
        out += errors(v, s.get('then', {}), at)
    return out


def main(argv):
    if len(argv) != 2:
        print(__doc__)
        return 2
    try:
        schema = load(argv[0])
        with open(argv[1], encoding='utf-8') as f:
            rows = [json.loads(line) for line in f if line.strip()]
    except (OSError, ValueError) as e:
        print('validate: %s' % e, file=sys.stderr)
        return 2
    bad = 0
    for i, row in enumerate(rows, 1):
        errs = errors(row, schema)
        bad += bool(errs)
        for e in errs[:3]:
            print('line %d %s' % (i, e))
    print('%d lines, %d do not fit' % (len(rows), bad))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
