cat > 'cockpit/serve.py' <<'OC_EOF_20'
#!/usr/bin/env python3
"""The cockpit: one process that keeps the ledger, starts the OpenCode agents and serves the page.

    python3 cockpit/serve.py RUNS [--team team.json] [--port 8800] [--max-launches 12] [--wall 600] [--judge FILE]

then open http://127.0.0.1:8800/ and issue an order.  Every start makes a new folder under RUNS (ledger, git
repository, sandboxes, logs); Ctrl-C stops it, and an agent that is still running then is ended without being collected.

It listens on 127.0.0.1 only.  What it answers:

    GET  /            the page (web/)
    GET  /state       the ledger, folded (see cli.py)
    GET  /team        seats and their models, every launch, the files handed in
    GET  /file?path=  the text of one handed-in file
    POST /message     one envelope for the dispatcher (the page sends order.issue)"""
import argparse
import json
import os
import signal
import sys
import time
import uuid
from urllib.parse import parse_qs, urlsplit

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import cli                          # noqa: E402
import live as L                    # noqa: E402
import opencode_agent as A          # noqa: E402
import history as H                # noqa: E402
import planning as P               # noqa: E402
import library as B                # noqa: E402

WEB = os.path.join(os.path.dirname(HERE), 'web')
PAGE = {'index.html': 'text/html', 'app.css': 'text/css', 'app.js': 'text/javascript', 'icons.js': 'text/javascript'}


class Handler(cli.Handler):
    server_version = 'opencode-cockpit/1'

    def _message_allowed(self, message):
        if not isinstance(message, dict) or message.get('kind') != 'order.issue':
            return True
        live = self.server.live
        if live is None:
            self._send(503, {'cli': 'starting'})
            return False
        body = message.get('body')
        if not isinstance(body, dict) or body.get('to') != live.lead:
            self._send(400, {'cli': 'not-through-lead',
                             'detail': 'Every order must go to the lead (%s), who dispatches the sub-orders.' % live.lead})
            return False
        return True

    def _raw(self, code, data, kind):
        self.send_response(code)
        self.send_header('Content-Type', kind + '; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        u = urlsplit(self.path)
        name = 'index.html' if u.path == '/' else u.path[5:] if u.path.startswith('/web/') else None
        if name is None and u.path not in ('/team', '/file', '/history', '/order', '/library', '/library/item',
                                           '/library/context', '/library/efficiency'):
            return cli.Handler.do_GET(self)             # /state, or not found
        if not self._gate():
            return
        if name is not None:
            if name not in PAGE:                        # only the files named above: a request never picks a path on disk
                return self._send(404, {'cli': 'not-found'})
            try:
                with open(os.path.join(WEB, name), 'rb') as f:
                    return self._raw(200, f.read(), PAGE[name])
            except OSError:
                return self._send(404, {'cli': 'not-found'})
        live = self.server.live
        if live is None:
            return self._send(503, {'cli': 'starting'})
        if u.path == '/team':
            return self._raw(200, live.doc.encode('utf-8'), 'application/json')
        q = parse_qs(u.query, keep_blank_values=True)
        try:
            if u.path.startswith('/library') or u.path == '/order':
                self.server.library.sync(self.server.history)
            if u.path == '/library':
                return self._send(200, self.server.library.listing())
            if u.path == '/library/item':
                return self._send(200, self.server.library.item((q.get('id') or [''])[0]))
            if u.path == '/library/context':
                return self._send(200, self.server.library.context())
            if u.path == '/library/efficiency':
                return self._send(200, self.server.library.efficiency())
            if u.path == '/history':
                return self._send(200, self.server.history.summary(self.server.plans.read()))
            run = (q.get('run') or [self.server.history.current])[0]
            if u.path == '/order':
                return self._send(200, self.server.history.order(run, (q.get('id') or [''])[0]))
            path = (q.get('path') or [''])[0]
            got = self.server.history.read_file(run, path)
        except B.Error as e:
            return self._send(e.status, {'cli': e.code, 'detail': str(e)})
        except FileNotFoundError:
            return self._send(404, {'cli': 'not-found'})
        except (OSError, ValueError, KeyError, TypeError, RuntimeError, cli.LedgerError):
            return self._send(500, {'cli': 'unreadable-history', 'detail': 'The stored run or plans cannot be read.'})
        if got is None:
            return self._send(404, {'cli': 'not-found', 'detail': 'no file with that key was handed in'})
        self._send(200, got)

    def do_POST(self):
        path = urlsplit(self.path).path
        if path not in ('/plan', '/plan/issue', '/plan/cancel', '/library/save', '/library/review'):
            return cli.Handler.do_POST(self)
        if not self._gate():
            return
        n = self.headers.get('Content-Length')
        if n is None or not n.isdigit():
            return self._send(411, {'cli': 'length-required', 'detail': 'Send a Content-Length.'})
        if int(n) > cli.MAX_BODY:
            self.close_connection = True
            return self._send(413, {'cli': 'too-large', 'detail': 'The request body exceeds the size limit.'})
        try:
            body = json.loads(self.rfile.read(int(n)).decode('utf-8'))
            if not isinstance(body, dict):
                raise ValueError('send a JSON object')
        except ValueError:
            return self._send(400, {'cli': 'bad-json' if path.startswith('/library/') else 'bad-plan', 'detail': 'send a JSON object'})
        if path.startswith('/library/'):
            try:
                entry = (self.server.library.save(body, self.server.history, L.CEO) if path.endswith('/save')
                         else self.server.library.review(body, L.CEO))
                return self._send(200, {'entry': entry})
            except B.Error as e:
                return self._send(e.status, {'cli': e.code, 'detail': str(e)})
            except (OSError, ValueError, KeyError, TypeError, RuntimeError):
                return self._send(500, {'cli': 'library-storage', 'detail': 'The library could not be read or saved.'})
        if path == '/plan':
            try:
                return self._send(200, self.server.plans.add(body))
            except ValueError as e:
                return self._send(400, {'cli': 'bad-plan', 'detail': str(e)})
            except OSError:
                return self._send(500, {'cli': 'plan-storage', 'detail': 'The plan could not be saved.'})
        if not isinstance(body.get('id'), str):
            return self._send(400, {'cli': 'bad-plan', 'detail': 'id must be text'})
        try:
            code, result = self.server.plans.act(path.rsplit('/', 1)[1], body['id'], self.server)
            return self._send(code, result)
        except cli.Moved:
            return self._send(409, {'cli': 'moved'})
        except (OSError, ValueError, KeyError, TypeError):
            return self._send(500, {'cli': 'plan-storage', 'detail': 'Check history before trying this action again.'})


class Server(cli.Server):
    """The HTTP side takes the lock for every request, so it never reads the ledger in the middle of a step."""
    live = None

    def __init__(self, gate, run, port, clock, quiet=True):
        self.gate = gate
        cli.Server.__init__(self, run, port, (), clock=clock, quiet=quiet)
        self.RequestHandlerClass = Handler
        port = self.server_address[1]
        self.origins = {'http://%s:%d' % (cli.BIND, port), 'http://localhost:%d' % port}    # the page it serves, and nobody else

    def finish_request(self, request, client_address):
        with self.gate:
            cli.Server.finish_request(self, request, client_address)


def start(runs, team, port=0, limit=A.MAX_TOTAL, wall=A.WALL, judge=None, exe=None, quiet=True, offset=0, **kw):
    """A started cockpit on a new run folder under `runs`."""
    B.outside_repo(runs)
    os.makedirs(runs, exist_ok=True)
    clock = lambda: time.time() + offset
    run = os.path.join(runs, time.strftime('%Y%m%d-%H%M%S', time.localtime(clock())) + '-' + uuid.uuid4().hex[:8])
    def server(gate, run, clock):
        srv = Server(gate, run, port, clock, quiet)
        srv.history = H.History(runs, os.path.basename(run), clock)
        srv.plans = P.Plans(runs, clock)
        try:
            srv.library = B.Library(runs, clock)
            srv.history.library = srv.library
            srv.library.sync(srv.history)
        except BaseException:
            srv.server_close()
            raise
        return srv
    return L.Live(run, team, server, limit=limit, wall=wall, judge=judge, exe=exe, clock=clock, **kw).start()


def main(argv=None):
    a = argparse.ArgumentParser(prog='serve.py', description=__doc__.split('\n')[0])
    a.add_argument('runs', help='a folder for run folders; every start makes a new one inside it')
    a.add_argument('--team', default=os.path.join(os.path.dirname(HERE), 'team.example.json'), help='which seat runs which model (default: team.example.json)')
    a.add_argument('--port', type=int, default=8800)
    a.add_argument('--max-launches', type=int, default=A.MAX_TOTAL, help='how many agent processes this start may run in all (default %d)' % A.MAX_TOTAL)
    a.add_argument('--wall', type=int, default=A.WALL, help='seconds before one agent process is ended (default %d)' % A.WALL)
    a.add_argument('--judge', help='a judge file to use instead of the floor judge (cockpit/judge_floor.py)')
    a.add_argument('--opencode', help='the opencode executable (default: $OPENCODE_BIN, else `opencode` on PATH)')
    a.add_argument('--verbose', action='store_true', help='print every HTTP request')
    a.add_argument('--clock-offset', type=int, default=0, metavar='SECONDS', help='shift the local calendar and ledger clock for rehearsals (default 0)')
    o = a.parse_args(argv)
    try:
        team = L.load_team(o.team)
    except (OSError, ValueError, KeyError, TypeError) as e:
        L.say('ERROR the team file %s cannot be used: %s' % (o.team, e))
        return 2
    try:
        live = start(os.path.abspath(o.runs), team, o.port, o.max_launches, o.wall, o.judge, o.opencode, quiet=not o.verbose, offset=o.clock_offset)
    except (OSError, ValueError) as e:
        L.say('ERROR could not start: %s' % e)
        return 2
    L.say('run folder  %s' % live.run)
    for s in json.loads(live.doc)['seats']:
        L.say('seat        %-22s %s' % (s['actor'], s['model']))
    L.say('limits      %d launch(es) in all, %d per order, %d s each' % (o.max_launches, A.MAX_PER_ORDER, o.wall))
    L.say('open        %s/      (Ctrl-C stops)' % live.url)
    signal.signal(signal.SIGTERM, lambda *_: live.stop.set())
    try:
        while not live.stop.is_set():
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    L.say('stopping')
    return 0 if live.close() and not live.fatal else 1


if __name__ == '__main__':
    sys.exit(main())
