cat > 'tests/fake_bin/opencode' <<'OC_EOF_26'
#!/usr/bin/env python3
"""A stand-in for the `opencode` executable, for tests and rehearsals: no model is called and nothing costs anything.

It accepts exactly the command line the cockpit builds (run --format json -m provider/model --title T PROMPT), reads
_dispatch/ORDER.json in its working directory like a real agent would, and prints events shaped like OpenCode's:
  * in the planner seat it writes a plan of two sub-orders (the second reads what the first hands in);
  * in a worker seat it writes one file under the order's write scope and runs the self-check the order names.
FAKE_OPENCODE_SLEEP (seconds) makes it slow, so that a page has time to show it running.
FAKE_OPENCODE_LIBRARY is an optional JSON object with uses and/or propose fields to
copy into the planner's plan. Set uses to "context" to name all ids in LIBRARY.json.
Include the variable in the team's pass_env. Unset, behavior is unchanged, even
with an empty library. Workers ignore the switch; no model or network is used."""
import json
import os
import subprocess
import sys
import time


def say(kind, **part):
    print(json.dumps({'type': kind, 'sessionID': 'ses_standin', 'part': part}), flush=True)


def main(argv):
    if len(argv) != 8 or argv[:4] != ['run', '--format', 'json', '-m'] or '/' not in argv[4] or argv[5] != '--title':
        say('error', error={'name': 'UsageError', 'message': 'expected: run --format json -m provider/model --title T PROMPT'})
        return 1
    model = argv[4]
    sys.stderr.write('env: %s\n' % ' '.join(sorted(os.environ)))
    with open(os.path.join('_dispatch', 'ORDER.json'), encoding='utf-8') as f:
        doc = json.load(f)
    o, tools = doc['order'], 1
    top = o['writes'][0]
    say('step_start')
    say('tool_use', tool='read', state={'status': 'completed', 'input': {'filePath': '_dispatch/ORDER.json'}})
    if doc['seat'] == 'planner':
        teams, judge = doc['roster']['teams'], doc['roster']['judges'][0]
        pick = lambda word, i: next((t for t in teams if word in t), teams[i])
        kid = lambda name, to, **kw: dict({'id': '%s.%s' % (o['id'], name), 'to': to, 'title': '%s: %s' % (name.capitalize(), o['title'] or o['id']),
                                            'goal': 'Stand-in sub-order (%s) of: %s' % (name, o['goal']), 'writes': ['%s%s/' % (top, name)], 'reads': [], 'after': [],
                                            'budget': 1, 'accept': {'judge': judge, 'criteria': 'a readable file is handed in'}}, **kw)
        plan = {'orders': [kid('draft', pick('writ', 0)),
                           kid('review', pick('review', -1), reads=[{'key': top + 'draft/notes.md', 'rev': 1, 'released': True}], after=[o['id'] + '.draft'])]}
        extra = json.loads(os.environ.get('FAKE_OPENCODE_LIBRARY') or '{}')
        for field in ('uses', 'propose'):
            if field in extra:
                plan[field] = extra[field]
        if plan.get('uses') == 'context':
            with open(os.path.join('_dispatch', 'LIBRARY.json'), encoding='utf-8') as f:
                context = json.load(f)
            plan['uses'] = [e['id'] for group in ('skills', 'artifacts', 'workflows', 'lessons') for e in context[group]]
        with open(os.path.join('_dispatch', 'plan.json'), 'w', encoding='utf-8') as f:
            json.dump(plan, f, indent=1)
        say('tool_use', tool='write', state={'status': 'completed', 'input': {'filePath': '_dispatch/plan.json'}})
        tools += 1
    else:
        os.makedirs(top, exist_ok=True)
        if o['reads']:
            with open(o['reads'][0]['key'], encoding='utf-8') as f:
                src = f.read()
            name, text = 'review.md', '# Review\n\nRead %d characters of %s. Written by a stand-in program (%s), not by a model.\n' % (len(src), o['reads'][0]['key'], model)
        else:
            name, text = 'notes.md', '# Notes\n\nOrder: %s\n\nWritten by a stand-in program (%s), not by a model.\n' % (o['goal'], model)
        with open(os.path.join(top, name), 'w', encoding='utf-8') as f:
            f.write(text)
        say('tool_use', tool='write', state={'status': 'completed', 'input': {'filePath': top + name}})
        tools += 1
        if doc.get('verify'):
            r = subprocess.run(doc['verify']['cmd'].split(), stdin=subprocess.DEVNULL, capture_output=True)
            say('tool_use', tool='bash', state={'status': 'completed' if r.returncode == 0 else 'error', 'input': {'command': doc['verify']['cmd']}})
            tools += 1
    time.sleep(float(os.environ.get('FAKE_OPENCODE_SLEEP') or 0))
    say('text', text='Done (stand-in, seat %s).' % doc['seat'])
    say('step_finish', reason='stop', cost=0, tokens={'input': 0, 'output': 0, 'reasoning': 0, 'cache': {'read': 0, 'write': 0}})
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
