cat > 'tests/sim.py' <<'OC_EOF_28'
#!/usr/bin/env python3
"""Stress the dispatcher with teams that behave like real ones: they act on views that have gone stale, the network
delivers some messages twice, some agents freeze and wake up after their lease is gone, and a few overstep
(claim work that is not theirs, write outside their scope, judge themselves, skip the judge).
The log of each run goes to the independent referee (check.py).  Three questions, all answered by counting:
  guarded   every guard on            -> the referee must find nothing
  naive     every guard off           -> how many conflicts the same behaviour causes with "look, then act"
  mutants   one guard off at a time   -> the referee must notice each missing guard
   python3 -I sim.py [--seeds 12] [--steps 700] [--json out/sim.json]"""
import collections, json, os, random, sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from dispatcher import Dispatcher, GUARDS, msg  # noqa: E402
import check  # noqa: E402

EXPECT = {'dedupe': 'I5', 'one-lease': 'I2', 'fence': 'I3', 'in-scope': 'I4', 'scope': 'I4', 'basis': 'I6', 'expect': 'I6', 'capacity': 'I7',
          'authority': 'I8', 'subset': 'I8', 'members': 'I8', 'deps': 'I9', 'notice': 'I9', 'judge': 'I10'}
SCOPES = ['chip/', 'chip/rtl/', 'chip/pd/', 'chip/pd/floorplan', 'pkg/', 'pkg/substrate/', 'rack/', 'rack/power/']
FILES = ['spec', 'a', 'b']


def run(seed, guards=GUARDS, steps=700, teams=4, workers=3, orders=14):
    rng, d, clock, n = random.Random(seed), Dispatcher(guards), [0], [0]
    stats, again = collections.Counter(), []
    team_ids = ['team:t%d' % i for i in range(teams)]
    doers = team_ids + ['agent:t%d/w%d' % (i, j) for i in range(teams) for j in range(workers)]
    judges = ['program:j0', 'program:j1']
    mind = {a: {'view': None, 'head': 0, 'lease': None, 'revs': {}, 'wrote': {}, 'asleep': 0, 'kids': 0} for a in doers + judges + ['human:ceo']}

    def send(frm, kind, body=None, basis=None, lease=None):
        n[0] += 1
        m = msg('m%d' % n[0], frm, kind, body, basis, lease)
        if rng.random() < 0.12:
            again.append(m)
        return deliver(m)

    def deliver(m):
        r = d.submit(m, clock[0])
        if m['kind'] != 'state.query':
            stats['sent'] += 1
            stats['ack' if r['ok'] else 'nack:' + r['code']] += 1
            stats['dup'] += bool(r.get('dup'))
        return r

    def look(a):
        r = deliver(msg('q', a, 'state.query'))
        mind[a]['view'], mind[a]['head'] = r['state'], r['source']['head']

    def team_of(a):
        return a if a.startswith('team:') else 'team:' + a.split(':')[1].split('/')[0]

    send('human:ceo', 'pool.set', {'pool': 'lic', 'cap': 2})
    send('human:ceo', 'pool.set', {'pool': 'compute', 'cap': 6})
    for t in team_ids:
        send('human:ceo', 'org.set', {'actor': t, 'superior': 'human:ceo'})
    for a in doers[teams:]:
        send('human:ceo', 'org.set', {'actor': a, 'superior': team_of(a)})
    issued = []

    def new_order(frm, parent=None, lease=None):
        oid = 'o%d' % (len(issued) + 1) if parent is None else '%s.%d' % (parent['id'], mind[frm]['kids'] + 1)
        scope = rng.choice(SCOPES) if parent is None else parent['writes'][0]
        b = {'id': oid, 'to': rng.choice(team_ids), 'title': oid, 'writes': [scope], 'budget': 100, 'needs': {'compute': rng.randint(1, 3)},
             'accept': {'judge': rng.choice(judges), 'criteria': 'the check program passes'}}
        if rng.random() < 0.5:
            b['needs']['lic'] = 1
        if parent is None:
            if issued and rng.random() < 0.3:
                b['after'] = [rng.choice(issued)]
            if rng.random() < 0.4:
                b['reads'] = [{'key': rng.choice([s for s in SCOPES if s.endswith('/') and s != scope]) + 'spec', 'rev': 1}]
                if rng.random() < 0.35:
                    b['reads'][0]['released'] = True          # not just written: handed in by an order that succeeded
        else:
            mind[frm]['kids'] += 1
            b.update(parent=parent['id'], budget=30, to=rng.choice([frm] + [a for a in doers if team_of(a) == frm and a != frm]))
            b['writes'] = [scope + 'part%d/' % mind[frm]['kids']] if scope.endswith('/') else [scope]
            if rng.random() < 0.1:
                b['writes'] = [rng.choice(SCOPES)]            # outside the parent
            if rng.random() < 0.1:
                b['budget'] = 90                              # more than the parent has left
            if rng.random() < 0.06:
                b['to'] = rng.choice(team_ids)                # sideways
        if rng.random() < 0.07:
            del b['accept']                                   # nobody to judge it
        if rng.random() < 0.05:
            b['unverified'] = [{'what': 'field reliability'}]  # cannot be checked, and nobody owns it
        r = send(frm, 'order.issue', b, lease=lease)
        if r['ok'] and parent is None:
            issued.append(oid)

    def work(a):
        me = mind[a]
        le = me['lease']
        o = (me['view'] or {'orders': {}})['orders'].get(le['order'])
        roll, scope = rng.random(), le['writes'][0]
        if a.startswith('team:') and o is not None and rng.random() < 0.25:      # a lead splits the order among its people
            r = {'ok': True}
            new_order(a, parent=dict(o, id=le['order']), lease=le)
        elif roll < 0.45:
            key = scope + (rng.choice(FILES) if me['wrote'] else 'spec') if scope.endswith('/') else scope
            if rng.random() < 0.06:
                key = rng.choice(SCOPES) + 'a'                # outside its own order
            seen = me['revs'].get(key, (me['view'] or {'artifacts': {}})['artifacts'].get(key, 0))
            if seen and rng.random() < 0.08:
                seen -= 1                                     # a second process of the same holder, working from an old copy
            r = send(a, 'artifact.put', {'key': key, 'expect': seen}, lease=le)
            if r['ok']:
                me['revs'][key] = me['wrote'][key] = r.get('rev', seen + 1)
            elif r['code'] == 'stale':
                me['revs'].pop(key, None)
                look(a)
        elif roll < 0.55:
            r = send(a, 'report.progress', {'note': 'working', 'pct': rng.randint(1, 99)}, lease=le)
        elif roll < 0.65:
            r = send(a, 'lease.renew', {'ttl': rng.randint(60, 120)}, lease=le)
        elif roll < 0.95:
            r = send(a, 'report.submit', {'outputs': [{'key': k, 'rev': v} for k, v in sorted(me['wrote'].items())], 'evidence': 'log'}, lease=le)
            if r['ok']:
                me['lease'], me['wrote'], me['done'] = None, {}, le['order']
        else:
            r = send(a, 'lease.release', {'reason': 'giving it back'}, lease=le)
            if r['ok']:
                me['lease'] = None
        if not r['ok'] and r['code'] == 'fenced':
            me['lease'], me['wrote'] = None, {}               # it finds out the lease is gone

    def seek(a):
        me = mind[a]
        if me['view'] is None or rng.random() < 0.5:
            look(a)
        os_ = me['view']['orders']
        arts = me['view']['artifacts']
        ready = lambda o: all(os_.get(x, {}).get('state') == 'SUCCEEDED' for x in o['after']) and all(arts.get(r['key'], 0) >= r['rev'] for r in o['reads'])
        mine = [k for k, o in os_.items() if o['state'] == 'PENDING' and ready(o) and (o['to'] == a or (o['to'] == team_of(a) and rng.random() < 0.25))]
        other = [k for k, o in os_.items() if o['state'] in ('PENDING', 'LEASED')]
        pick = mine if rng.random() < 0.85 else other
        if rng.random() < 0.04 and os_:
            send(a, 'order.cancel', {'order': rng.choice(sorted(os_))}, basis=me['head'])      # not its order to cancel
        if rng.random() < 0.04 and me.get('done'):
            send(a, 'verdict', {'order': me['done'], 'pass': True}, basis=me['head'])           # judging itself
        if rng.random() < 0.03:
            send(a, 'order.issue', {'id': 'x%d' % n[0], 'to': team_of(a), 'writes': ['rack/'], 'accept': {'judge': 'program:j0', 'criteria': 'c'}})
        if rng.random() < 0.05:
            q = {'text': 'which option?', 'blocking': rng.random() < 0.4}
            if q['blocking'] and os_:
                q['order'] = rng.choice(sorted(os_))          # holds that order until answered; often not its order to hold
            send(a, 'ask.raise', q)
        if pick:
            oid = rng.choice(sorted(pick))
            r = send(a, 'claim.request', {'order': oid, 'ttl': rng.randint(60, 120)}, basis=me['head'])
            if r['ok'] and not r.get('dup'):
                me['lease'] = dict(r['lease'], writes=os_[oid]['writes'])

    for step in range(steps):
        clock[0] += rng.random() < 0.5
        if again and rng.random() < 0.3:
            deliver(again.pop(rng.randrange(len(again))))
        a = rng.choice(doers + judges + ['human:ceo', 'human:ceo'])
        me = mind[a]
        if a == 'human:ceo':
            if len(issued) < orders and rng.random() < 0.6:
                new_order(a)
            elif rng.random() < 0.3:
                if rng.random() < 0.5 or me['view'] is None:
                    look(a)
                live = [k for k, o in me['view']['orders'].items() if o['state'] in ('PENDING', 'LEASED')]
                if live and rng.random() < 0.7:
                    send(a, 'order.amend', {'order': rng.choice(sorted(live)), 'patch': {'priority': rng.randint(0, 9)}}, basis=me['head'])
                if live and rng.random() < 0.12:                 # the person calls one off, cascade and all, from the screen they have
                    send(a, 'order.cancel', {'order': rng.choice(sorted(live)), 'reason': 'changed my mind'}, basis=me['head'])
                for k in sorted(me['view']['asks'])[:1]:
                    send(a, 'ask.answer', {'ask': k, 'answer': 'go with the first'}, basis=me['head'])
            elif rng.random() < 0.05:                            # the person resizes a pool, sometimes below what is in use
                pool = rng.choice(['lic', 'compute'])
                send(a, 'pool.set', {'pool': pool, 'cap': rng.randint(1, 3) if pool == 'lic' else rng.randint(3, 8)})
            elif rng.random() < 0.03:                            # or moves someone, sometimes a judge onto the team it judges
                send(a, 'org.set', {'actor': rng.choice(judges + doers[teams:]), 'superior': rng.choice(team_ids)})
        elif a in judges:
            if rng.random() < 0.6 or me['view'] is None:
                look(a)
            for k, o in sorted(me['view']['orders'].items()):
                if o['state'] == 'JUDGING' and (o.get('accept') or {}).get('judge') == a:
                    roll = rng.random()
                    send(a, 'verdict', {'order': k, 'pass': roll < 0.75, 'retry': roll < 0.95}, basis=me['head'])
        elif me['asleep'] > clock[0]:
            continue
        elif rng.random() < 0.02:
            me['asleep'] = clock[0] + rng.randint(150, 400)    # frozen: wakes up believing it still holds the lease
        elif me['lease']:
            work(a)
        else:
            seek(a)
    bad = check.check(d.log)
    states = collections.Counter(o['state'] for o in d.s.orders.values())
    waiting = collections.Counter(d.why(k)[0]['because'] for k, o in d.s.orders.items() if o['state'] == 'PENDING')
    return {'seed': seed, 'events': len(d.log), 'stats': dict(stats), 'broken': {i: len(v) for i, v in bad.items()}, 'first': {i: v[0] for i, v in bad.items() if v},
            'orders': dict(states), 'waiting': dict(waiting)}, d


def total(rows, key):
    out = collections.Counter()
    for r in rows:
        out.update(r[key])
    return dict(out)


def main(argv):
    opt = {'--seeds': '12', '--steps': '700', '--json': None}
    while argv:
        if argv[0] not in opt or len(argv) < 2:
            print(__doc__)
            return 2
        opt[argv[0]], argv = argv[1], argv[2:]
    seeds, steps = range(1, int(opt['--seeds']) + 1), int(opt['--steps'])
    guarded = [run(s, GUARDS, steps)[0] for s in seeds]
    naive = [run(s, (), steps)[0] for s in seeds]
    mutants = {}
    for g in GUARDS:
        rows = [run(s, [x for x in GUARDS if x != g], steps)[0] for s in seeds]
        want = EXPECT[g]
        mutants[g] = {'expect': want, 'seedsCaught': sum(1 for r in rows if r['broken'][want]), 'seeds': len(rows), 'broken': total(rows, 'broken'),
                      'internal': sum(r['stats'].get('nack:internal', 0) for r in rows),
                      'first': next((r['first'][want] for r in rows if want in r['first']), None)}
    out = {'seeds': len(seeds), 'steps': steps, 'guarded': {'broken': total(guarded, 'broken'), 'stats': total(guarded, 'stats'), 'orders': total(guarded, 'orders'), 'waiting': total(guarded, 'waiting'), 'events': sum(r['events'] for r in guarded)},
           'naive': {'broken': total(naive, 'broken'), 'stats': total(naive, 'stats'), 'orders': total(naive, 'orders'), 'events': sum(r['events'] for r in naive),
                     'first': {i: next((r['first'][i] for r in naive if i in r['first']), None) for i in check.IDS}},
           'mutants': mutants}
    # a refusal the dispatcher could not explain (it caught its own crash and rolled back) is a bug wherever it shows up
    out['internal'] = sum(r['stats'].get('nack:internal', 0) for r in guarded + naive) + sum(m.pop('internal') for m in mutants.values())
    print('%d seeds x %d steps' % (len(seeds), steps))
    print('     ' + ' '.join('%5s' % i for i in check.IDS))
    for name in ('guarded', 'naive'):
        print('%-8s' % name + ' '.join('%5d' % out[name]['broken'][i] for i in check.IDS))
    print('guarded: sent %d, acked %d, repeats absorbed %d; refused: %s' % (out['guarded']['stats']['sent'], out['guarded']['stats']['ack'], out['guarded']['stats'].get('dup', 0),
          ', '.join('%s %d' % (k[5:], v) for k, v in sorted(out['guarded']['stats'].items()) if k.startswith('nack:'))))
    print('orders at the end  guarded %s | naive %s' % (out['guarded']['orders'], out['naive']['orders']))
    print('guarded, still waiting at the end because: %s' % out['guarded']['waiting'])
    for g, m in mutants.items():
        print('without %-10s -> %-3s broken in %2d/%d seeds %s' % (g, m['expect'], m['seedsCaught'], m['seeds'], '' if m['seedsCaught'] else '   <-- NOT NOTICED'))
    if opt['--json']:
        os.makedirs(os.path.dirname(os.path.abspath(opt['--json'])), exist_ok=True)
        with open(opt['--json'], 'w', encoding='utf-8') as f:
            json.dump(out, f, ensure_ascii=False, indent=1)
    print('crashes caught and rolled back, all runs: %d' % out['internal'])
    clean = not any(out['guarded']['broken'].values()) and not out['internal']
    return 0 if clean and all(m['seedsCaught'] for m in mutants.values()) else 1


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
