#!/usr/bin/env python3
"""Calendar endpoints and stand-in runs without sockets, a browser, or a model."""
import concurrent.futures
import datetime
import io
import json
import os
import shutil
import sys
import tempfile
import time
import unittest
from email.message import Message
from unittest import mock
from urllib.parse import quote

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))
sys.path.insert(0, HERE)                                   # test_cockpit, also when the script folder is not on the path (python -I)

import cli
import history
import live
import planning
import serve
from test_cockpit import TEAM, FAKE


class MemoryServer(serve.Server):
    """Use the production handlers and writer; no listening socket or HTTP thread."""
    def __init__(self, gate, run, port, clock, quiet=True):
        self.gate, self.run, self.clock, self.quiet = gate, run, clock, quiet
        self.server_address = ('127.0.0.1', port)
        self.origins = {'http://127.0.0.1:%d' % port}
        self.writer = cli.Writer(run, {'mode': 'test'})

    def server_close(self):
        self.writer.close()


def request(instance, method, path, body=None, origin=None):
    handler = serve.Handler.__new__(serve.Handler)
    handler.server, handler.path = instance.srv, path
    handler.request_version, handler.command, handler.requestline = 'HTTP/1.1', method, method + ' ' + path + ' HTTP/1.1'
    handler.headers = Message()
    raw = json.dumps(body).encode() if body is not None else b''
    handler.headers['Content-Length'] = str(len(raw))
    handler.headers['Host'] = '127.0.0.1:0'
    if origin:
        handler.headers['Origin'] = origin
    handler.rfile, handler.wfile = io.BytesIO(raw), io.BytesIO()
    with instance.gate:
        getattr(handler, 'do_' + method)()
    head, data = handler.wfile.getvalue().split(b'\r\n\r\n', 1)
    return int(head.split()[1]), json.loads(data)


class Calendar(unittest.TestCase):
    def setUp(self):
        # Runs include a shared library, which must never live in the source repository.
        self.tmp = tempfile.mkdtemp(prefix='calendar-')
        self.instances = []
        self.addCleanup(self.cleanup)
        self.patch_server = mock.patch.object(serve, 'Server', MemoryServer)
        self.patch_start = mock.patch.object(live.Live, 'start', lambda instance: instance)
        self.patch_server.start()
        self.patch_start.start()
        self.addCleanup(self.patch_server.stop)
        self.addCleanup(self.patch_start.stop)

    def cleanup(self):
        for instance in self.instances:
            instance.srv.server_close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def start(self, date, team=TEAM):
        for previous in self.instances:
            previous.srv.server_close()
        stamp = time.mktime(time.strptime(date + ' 12:00:00', '%Y-%m-%d %H:%M:%S'))
        instance = serve.start(self.tmp, team, exe=FAKE, offset=stamp - time.time(), every=0.1, pace=0.01)
        self.instances.append(instance)
        return instance

    def get(self, instance, path):
        code, result = request(instance, 'GET', path)
        self.assertEqual(code, 200, result)
        return result

    def plan(self, instance, date='2030-04-12', **kw):
        fields = dict(title='A planned note', goal='Write and review a note.', writes='', budget=6, day=date)
        fields.update(kw)
        return request(instance, 'POST', '/plan', fields)

    def issue(self, instance, oid):
        fields = dict(title='Try ' + oid, goal='Write and review a note.', writes='', budget=6)
        code, result = request(instance, 'POST', '/message', planning.envelope(fields, oid, instance.lead, 'ui-' + oid))
        self.assertEqual((code, result.get('ok')), (200, True), result)

    def complete(self, instance, oid):
        for _ in range(20):
            instance.once()
            if instance.ad.d.snapshot()['orders'][oid]['state'] == 'SUCCEEDED':
                return
        self.fail('stand-in order did not succeed')

    def test_message_orders_must_go_through_the_running_lead(self):
        team = json.loads(json.dumps(TEAM))
        team['lead']['id'] = 'planner'
        instance = self.start('2030-04-10', team)
        envelope = planning.envelope(dict(title='A note', goal='Write a note.', writes='', budget=6),
                                     'through-lead', instance.lead, 'ui-through-lead')
        ledger_path = os.path.join(instance.run, cli.LEDGER)
        with open(ledger_path, 'rb') as f:
            original = f.read()
        with mock.patch.object(instance.srv.writer, 'submit', wraps=instance.srv.writer.submit) as submit:
            for actor in ('agent:writer', 'team:writer', 'team:lead', '', None):
                with self.subTest(actor=actor):
                    envelope['body']['to'] = actor
                    code, result = request(instance, 'POST', '/message', envelope)
                    self.assertEqual((code, result['cli']), (400, 'not-through-lead'))
                    self.assertIn(instance.lead, result['detail'])
                    submit.assert_not_called()
                    with open(ledger_path, 'rb') as f:
                        self.assertEqual(f.read(), original)
            envelope['body']['to'] = instance.lead
            code, result = request(instance, 'POST', '/message', envelope)
            self.assertEqual((code, result['ok']), (200, True))
            submit.assert_called_once()
        self.complete(instance, 'through-lead')
        issued = [e for e in instance.ad.d.log if e['kind'] == 'order.issued']
        self.assertEqual([(e['by'], e['body']['to']) for e in issued],
                         [(live.CEO, instance.lead), (instance.lead, 'team:writer'), (instance.lead, 'team:reviewer')])

    def test_rejected_message_does_not_tick_an_expired_lease(self):
        instance = self.start('2030-04-10')
        self.issue(instance, 'held')
        code, claim = request(instance, 'POST', '/message', {'v': 'dispatch/1', 'id': 'claim-held', 'from': instance.lead,
                             'to': 'dispatcher', 'kind': 'claim.request', 'basis': instance.srv.writer.d.s.head,
                             'body': {'order': 'held', 'ttl': 1}})
        self.assertEqual((code, claim['ok']), (200, True))
        with open(os.path.join(instance.run, cli.LEDGER), 'rb') as f:
            original = f.read()
        envelope = planning.envelope(dict(title='A note', goal='Write a note.', writes='', budget=6),
                                     'bypass', 'agent:writer', 'ui-bypass')
        with mock.patch.object(instance.srv, 'clock', return_value=instance.now() + 10):
            code, result = request(instance, 'POST', '/message', envelope)
        self.assertEqual((code, result['cli']), (400, 'not-through-lead'))
        with open(os.path.join(instance.run, cli.LEDGER), 'rb') as f:
            self.assertEqual(f.read(), original)
        self.assertEqual(instance.ad.d.snapshot()['orders']['held']['state'], 'LEASED')

