    def test_validation_waiting_restart_due_exactly_once_and_cancel(self):
        first = self.start('2030-04-10')
        for date in ('2030-04-09', '2030-04-10', '2030-02-30', '2030-4-12', '', None):
            code, result = self.plan(first, date)
