        code, p = self.plan(first)
        self.assertEqual((code, p['state']), (200, 'waiting'))
        self.assertEqual(request(first, 'POST', '/plan/issue', {'id': p['id']}), (409, {'cli': 'not-due'}))
        for _ in range(3):
