        self.assertEqual(doc['days']['2030-04-13']['stats']['issued'], 1)

    def test_local_calendar_date(self):
        if not hasattr(time, 'tzset'):
            self.skipTest('tzset is unavailable')
        previous = os.environ.get('TZ')
        try:
            os.environ['TZ'] = 'EST5'
            time.tzset()
            stamp = datetime.datetime(2030, 4, 11, 2, tzinfo=datetime.timezone.utc).timestamp()
            self.assertEqual(history.day(stamp), '2030-04-10')
