#!/usr/bin/env python3
"""The cockpit end to end, with a stand-in for the opencode executable (tests/fake_bin/opencode): no model, no cost."""
import json
import os
import shutil
import subprocess
import sys
import tempfile
import time
import unittest
import urllib.error
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))

import gitws                        # noqa: E402
import live as L                    # noqa: E402
import opencode_agent as A          # noqa: E402
import serve                        # noqa: E402

FAKE = os.path.join(HERE, 'fake_bin', 'opencode')
MODELS = ['deepseek/deepseek-chat', 'moonshotai/kimi-k2', 'alibaba/qwen3-coder-plus']
TEAM = {'lead': {'id': 'lead', 'name': 'Lead', 'model': MODELS[0]},
        'seats': [{'id': 'writer', 'name': 'Writer', 'model': MODELS[1]}, {'id': 'reviewer', 'name': 'Reviewer', 'model': MODELS[2]}],
        'pass_env': ['FAKE_OPENCODE_SLEEP'], 'permission': {}}


def until(test, secs=30.0, every=0.05):
    end = time.time() + secs
    while time.time() < end:
        if test():
            return True
        time.sleep(every)
    return bool(test())


class Base(unittest.TestCase):
    def setUp(self):
        self.tmp, self.lives, self.n = tempfile.mkdtemp(prefix='cockpit-'), [], 0
        self.addCleanup(self.stop)

    def stop(self):
        for l in self.lives:
            l.close(20)
        shutil.rmtree(self.tmp, ignore_errors=True)

    def live(self, **kw):
        kw = dict(dict(exe=FAKE, every=0.1, pace=0.05, wall=30), **kw)
        l = serve.start(os.path.join(self.tmp, 'runs%d' % len(self.lives)), TEAM, **kw)
        self.lives.append(l)
        return l

    def get(self, l, path, origin=None):
        rq = urllib.request.Request(l.url + path, headers={'Origin': origin} if origin else {})
        try:
            with urllib.request.urlopen(rq, timeout=30) as r:
                return r.status, r.headers.get('Content-Type'), r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers.get('Content-Type'), e.read()

    def post(self, l, body, origin=None):
        self.n += 1
        m = gitws.msg('h%05d' % self.n, L.CEO, 'order.issue', body)
        rq = urllib.request.Request(l.url + '/message', data=json.dumps(m).encode('utf-8'), headers={'Content-Type': 'application/json', 'Origin': origin or l.url})
        try:
            with urllib.request.urlopen(rq, timeout=30) as r:
                return r.status, json.load(r)
        except urllib.error.HTTPError as e:
            return e.code, json.load(e)

    def issue(self, l, oid='t1', budget=6):
        code, r = self.post(l, {'id': oid, 'title': 'Try ' + oid, 'goal': 'Write a short note, then review it.', 'to': l.lead, 'writes': [oid + '/'], 'budget': budget,
                                'accept': {'judge': L.JUDGE, 'criteria': 'files are handed in'}})
        self.assertEqual((code, r.get('ok')), (200, True), r)

    def states(self, l):
        with l.gate:
            return {k: o['state'] for k, o in l.ad.d.snapshot()['orders'].items()}

    def tagged(self, l):
        git = lambda *a: subprocess.run(['git', '--git-dir', os.path.join(l.run, 'repo.git')] + list(a), capture_output=True).stdout.decode()
        tags = git('for-each-ref', '--format=%(refname)', 'refs/tags/accepted').split()
        return {n: git('show', '%s:%s' % (t, n)) for t in tags for n in git('ls-tree', '-r', '--name-only', t).splitlines()}


class EndToEnd(Base):
    def test_one_order_is_cut_by_the_lead_and_done_by_two_other_models(self):
        l = self.live()
        self.issue(l)
        self.assertTrue(until(lambda: self.states(l) == {'t1': 'SUCCEEDED', 't1.draft': 'SUCCEEDED', 't1.review': 'SUCCEEDED'}), self.states(l))
        with l.gate:
            rows, recs = list(l.ad.d.log), [dict(r) for r in l.guard.records]
        self.assertEqual([(r['by'], r['body']['id'], r['body']['to']) for r in rows if r['kind'] == 'order.issued'],
                         [(L.CEO, 't1', 'team:lead'), ('team:lead', 't1.draft', 'team:writer'), ('team:lead', 't1.review', 'team:reviewer')])
        self.assertEqual([(r['agent'], r['seat'], r['order'], r['model']) for r in recs],
                         [('team:lead', 'planner', 't1', MODELS[0]), ('agent:writer', 'worker', 't1.draft', MODELS[1]), ('agent:reviewer', 'worker', 't1.review', MODELS[2])])
        for r, model in zip(recs, MODELS):               # the only command ever started: opencode run --format json ... -m <the seat's model>
            self.assertEqual((os.path.basename(r['argv'][0]), r['argv'][1:6], r['argv'][6], r['argv'][-1]), ('opencode', ['run', '--format', 'json', '-m', model], '--title', '<prompt>'))
            self.assertEqual((r['state'], r['rc'], r['outside_box']), ('ended', 0, [f for f in r['outside_box'] if f in L.OWN]))
        self.assertEqual([(r['by'], r['order']) for r in rows if r['kind'] == 'order.succeeded'], [(L.JUDGE, 't1.draft'), (L.JUDGE, 't1.review'), (L.JUDGE, 't1')])
        files = self.tagged(l)
