        self.assertEqual((doc['state'], doc['launched'], doc['limit']), ('running', 3, A.MAX_TOTAL))
        self.assertEqual([(f['path'], f['order'], f['accepted']) for f in doc['files']], [('t1/draft/notes.md', 't1.draft', True), ('t1/review/review.md', 't1.review', True)])
        self.assertEqual([(x['outcome'], x['seen']['steps'] >= 1) for x in doc['launches']], [('planned', True), ('submitted', True), ('submitted', True)])
        code, _, raw = self.get(l, '/file?path=t1/review/review.md')
        self.assertEqual((code, json.loads(raw)['text'].splitlines()[0]), (200, '# Review'))

    def test_an_agent_gets_a_clean_environment(self):
        os.environ['COCKPIT_TEST_SECRET'] = 'x'
        self.addCleanup(os.environ.pop, 'COCKPIT_TEST_SECRET')
        l = self.live()
        self.issue(l)
        self.assertTrue(until(lambda: self.states(l).get('t1') == 'SUCCEEDED'), self.states(l))
        with open(os.path.join(l.run, 'logs', '01-t1.err'), encoding='utf-8') as f:
            names = f.read().split()
        self.assertIn('OPENCODE_CONFIG_CONTENT', names)
        self.assertIn('OPENCODE_DISABLE_AUTOUPDATE', names)
        self.assertNotIn('COCKPIT_TEST_SECRET', names)

    def test_the_launch_limit_holds_and_nothing_more_is_started(self):
        l = self.live(limit=1)
        self.issue(l)
        self.assertTrue(until(lambda: l.guard.halted is not None), self.states(l))
        time.sleep(0.5)
        self.assertEqual(sum(l.guard.n.values()), 1)
        doc = json.loads(self.get(l, '/team')[2])
        self.assertEqual((doc['state'], doc['launched'], len(doc['held']) >= 1), ('halted', 1, True))
        self.assertNotIn('SUCCEEDED', (self.states(l)['t1.draft'], self.states(l)['t1']))

    def test_a_process_past_the_wall_clock_is_ended_and_what_it_left_is_not_taken(self):
        os.environ['FAKE_OPENCODE_SLEEP'] = '30'
        self.addCleanup(os.environ.pop, 'FAKE_OPENCODE_SLEEP')
        l = self.live(wall=1, limit=1)
        self.issue(l)
        self.assertTrue(until(lambda: [r['state'] for r in l.guard.records] == ['killed'], 30), [dict(r) for r in l.guard.records])
        self.assertTrue(until(lambda: self.states(l) != {} and 't1.draft' not in self.states(l), 5))
        self.assertEqual(self.tagged(l), {})


class Door(Base):
