#!/usr/bin/env python3
"""Each guard from both sides, on small hand-written situations:
   - the overstep is refused with the right reason and the legal twin goes through (referee finds nothing);
   - with that one guard taken away the overstep goes through and the referee names the right invariant.
Plus the rules that are not guards (expiry, cascade, immutability, replay), tampered logs for the referee,
and one test for each behaviour the independent review (review/REVIEW.md) found wrong or unstated.
   python3 -I test_dispatch.py"""
import copy, json, os, sys, threading, time, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
CORE = os.path.join(os.path.dirname(HERE), 'cockpit')
sys.path.insert(0, HERE)
sys.path.insert(0, CORE)
import check  # noqa: E402
from dispatcher import Dispatcher, GUARDS, MAX_ATTEMPTS, PAGE, msg  # noqa: E402

J = {'judge': 'program:drc', 'criteria': 'zero violations'}


class World:
    def __init__(self, guards=GUARDS):
        self.d, self.t, self.n = Dispatcher(guards), 0, 0
        self('human:ceo', 'pool.set', {'pool': 'lic', 'cap': 1})
        for a, up in (('team:ic', 'human:ceo'), ('team:pkg', 'human:ceo'), ('agent:ic/a', 'team:ic'), ('agent:ic/b', 'team:ic'), ('agent:pkg/a', 'team:pkg')):
            self('human:ceo', 'org.set', {'actor': a, 'superior': up})

    def __call__(self, frm, kind, body=None, basis=None, lease=None, mid=None, dt=1):
        self.t, self.n = self.t + dt, self.n + 1
        return self.d.submit(msg(mid or 'm%d' % self.n, frm, kind, body, basis, lease), self.t)

    def order(self, oid, to='team:ic', by='human:ceo', lease=None, **kw):
        return self(by, 'order.issue', dict({'id': oid, 'to': to, 'writes': ['chip/'], 'budget': 100, 'accept': J}, **kw), lease=lease)

    def claim(self, who, oid, ttl=1000):
        return self(who, 'claim.request', {'order': oid, 'ttl': ttl}, basis=self.d.s.head)

    def finish(self, who, oid, lease):
        self(who, 'report.submit', {}, lease=lease)
        return self('program:drc', 'verdict', {'order': oid, 'pass': True}, basis=self.d.s.head)


# name -> (invariant, steps).  steps(w) returns (reply to the overstep, reply to the legal twin).
def one_lease(w):
    w.order('o1')
    le = w.claim('agent:ic/a', 'o1')['lease']
    bad = w.claim('agent:ic/b', 'o1')
    w('agent:ic/a', 'lease.release', {}, lease=le)
    return bad, w.claim('agent:ic/b', 'o1')


def fence(w):
    w.order('o1')
    le = w.claim('agent:ic/a', 'o1', ttl=5)['lease']
    good = w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le, dt=4)      # one tick before the lease ends
    bad = w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 1}, lease=le, dt=1)       # the tick it ends
    return bad, good


def in_scope(w):
    w.order('o1')
    le = w.claim('agent:ic/a', 'o1')['lease']
    return w('agent:ic/a', 'artifact.put', {'key': 'pkg/x', 'expect': 0}, lease=le), w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le)


def scope(w):
    w.order('o1')
    w.order('o2', to='team:pkg', writes=['chip/pd/'])
    w.order('o3', to='team:pkg', writes=['pkg/'])
    w.claim('agent:ic/a', 'o1')
    return w.claim('agent:pkg/a', 'o2'), w.claim('agent:pkg/a', 'o3')


def basis(w):
    w.order('o1')
    seen = w.d.s.head
    w('human:ceo', 'order.amend', {'order': 'o1', 'patch': {'priority': 5}}, basis=seen)
    return w('agent:ic/a', 'claim.request', {'order': 'o1'}, basis=seen), w('agent:ic/a', 'claim.request', {'order': 'o1'}, basis=seen + 1)


def basis_sub_order(w):                                    # DP03, second pass: a new sub-order is a change to the order it is under
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    seen = w.d.s.head
    w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10)
    amend = lambda b: w('human:ceo', 'order.amend', {'order': 'o1', 'patch': {'priority': 5}}, basis=b)
    return amend(seen), amend(w.d.s.head)


def basis_sub_order_ended(w):                              # ... and so is a sub-order ending: an ended one is no longer among the open ones a cancel looks at
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10)
    seen = w.d.s.head
    w.finish('agent:ic/a', 'o1.1', w.claim('agent:ic/a', 'o1.1')['lease'])
    cancel = lambda b: w('human:ceo', 'order.cancel', {'order': 'o1'}, basis=b)
    return cancel(seen), cancel(w.d.s.head)


def expect(w):
    w.order('o1')
    le = w.claim('agent:ic/a', 'o1')['lease']
    good = w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le)
    return w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le), good


def capacity(w):
    w.order('o1', needs={'lic': 1})
    w.order('o2', to='team:pkg', writes=['pkg/'], needs={'lic': 1})
    le = w.claim('agent:ic/a', 'o1')['lease']
    bad = w.claim('agent:pkg/a', 'o2')
    w('agent:ic/a', 'lease.release', {}, lease=le)
    return bad, w.claim('agent:pkg/a', 'o2')


def authority(w):
    w.order('o1')
    bad = w('agent:pkg/a', 'order.cancel', {'order': 'o1'}, basis=w.d.s.head)
    return bad, w('human:ceo', 'order.cancel', {'order': 'o1'}, basis=w.d.s.head)


def authority_top(w):
    return w.order('o9', by='agent:ic/a'), w.order('o1')


def authority_sideways(w):
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    return (w.order('o1.1', to='team:pkg', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10),
            w.order('o1.2', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10))


def subset_scope(w):
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    return (w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['pkg/'], budget=10),
            w.order('o1.2', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/rtl/'], budget=10))


def subset_budget(w):
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    good = w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=100)   # exactly the parent's budget
    return w.order('o1.2', to='agent:ic/b', by='team:ic', lease=le, parent='o1', writes=['chip/b/'], budget=1), good


def members(w):
    w.order('o1')
    return w.claim('agent:pkg/a', 'o1'), w.claim('agent:ic/a', 'o1')


def deps_after(w):
    w.order('o1')
    w.order('o2', to='team:pkg', writes=['pkg/'], after=['o1'])
    bad = w.claim('agent:pkg/a', 'o2')
    w.finish('agent:ic/a', 'o1', w.claim('agent:ic/a', 'o1')['lease'])
    return bad, w.claim('agent:pkg/a', 'o2')


def deps_pin(w):
    w.order('o1')
    w.order('o2', to='team:pkg', writes=['pkg/'], reads=[{'key': 'chip/die-size', 'rev': 1}])
    bad = w.claim('agent:pkg/a', 'o2')
    w('agent:ic/a', 'artifact.put', {'key': 'chip/die-size', 'expect': 0}, lease=w.claim('agent:ic/a', 'o1')['lease'])
    return bad, w.claim('agent:pkg/a', 'o2')


def judge_missing(w):
    return w.order('o9', accept={}), w.order('o1')


def judge_is_doer(w):
    return w.order('o9', accept={'judge': 'agent:ic/a', 'criteria': 'looks fine'}), w.order('o1', accept={'judge': 'team:pkg', 'criteria': 'fits the substrate'})


def judge_unowned(w):
    return w.order('o9', unverified=[{'what': 'ten-year field reliability'}]), w.order('o1', unverified=[{'what': 'ten-year field reliability', 'owner': 'human:ceo'}])


def judge_self(w):
    w.order('o1')
    w('agent:ic/a', 'report.submit', {}, lease=w.claim('agent:ic/a', 'o1')['lease'])
    return w('agent:ic/a', 'verdict', {'order': 'o1', 'pass': True}, basis=w.d.s.head), w('program:drc', 'verdict', {'order': 'o1', 'pass': True}, basis=w.d.s.head)


# ---- found by the independent review (review/REVIEW.md); the comment on each names the finding
def capacity_shrink(w):                                   # CK01: a pool in use cannot be cut below what is leased out
    w.order('o1', needs={'lic': 1})
    w.claim('agent:ic/a', 'o1')
    return w('human:ceo', 'pool.set', {'pool': 'lic', 'cap': 0}), w('human:ceo', 'pool.set', {'pool': 'lic', 'cap': 2})


def capacity_hold(w):                                     # CK02: a holder cannot hand down an order that needs what it holds itself
    w.order('o1', needs={'lic': 1})
    le = w.claim('team:ic', 'o1')['lease']
    return (w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10, needs={'lic': 1}),
            w.order('o1.2', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/b/'], budget=10))


def authority_outsider(w):                                # DP02: being a person is not enough; the person has to be above the addressee
    return w.order('o9', by='human:guest'), w.order('o1')


def authority_question(w):                                # SC05: only someone connected to an order can hold it with a question
    w.order('o1')
    return (w('agent:pkg/a', 'ask.raise', {'text': 'stop this', 'order': 'o1', 'blocking': True}),
            w('agent:ic/a', 'ask.raise', {'text': 'which node?', 'order': 'o1', 'blocking': True}))


def judge_joins(w):                                       # DP01: the judge of an open order cannot be moved onto the team it judges
    w.order('o1', accept={'judge': 'agent:pkg/a', 'criteria': 'fits the substrate'})
    return (w('human:ceo', 'org.set', {'actor': 'agent:pkg/a', 'superior': 'team:ic'}),
            w('human:ceo', 'org.set', {'actor': 'agent:pkg/a', 'superior': 'team:pkg'}))


def deps_unknown(w):                                      # CK02: an order cannot come after one that does not exist
    return w.order('o9', after=['nope']), w.order('o1')


def deps_cycle(w):                                        # CK02: a sub-order cannot wait for the order it is part of
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    return (w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10, after=['o1']),
            w.order('o1.2', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/b/'], budget=10))


def deps_released(w):                                     # DP05: "released" input = handed in by an order that passed, not merely written
    w.order('o1')
    w.order('o2', to='team:pkg', writes=['pkg/'], reads=[{'key': 'chip/x', 'rev': 1, 'released': True}])
    le = w.claim('agent:ic/a', 'o1')['lease']
    w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le)
    bad = w.claim('agent:pkg/a', 'o2')
    w('agent:ic/a', 'report.submit', {'outputs': [{'key': 'chip/x', 'rev': 1}]}, lease=le)
    w('program:drc', 'verdict', {'order': 'o1', 'pass': True}, basis=w.d.s.head)
    return bad, w.claim('agent:pkg/a', 'o2')


def deps_handed_in_above(w):                              # R303: what only the orders above can hand in is never handed in while this one is open
    w.order('o1')
    le = w.claim('team:ic', 'o1')['lease']
    kw = dict(to='agent:ic/b', by='team:ic', lease=le, parent='o1', writes=['chip/b/'], budget=10, reads=[{'key': 'chip/if', 'rev': 1, 'released': True}])
    bad = w.order('o1.2', **kw)
    w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/if'], budget=10)      # the interface is a stage of its own, issued first
    return bad, w.order('o1.2' if not bad['ok'] else 'o1.3', **kw)


def deps_question(w):                                     # SC05: an open blocking question keeps the order from being taken
    w.order('o1')
    w('agent:ic/a', 'ask.raise', {'text': 'which node?', 'order': 'o1', 'blocking': True}, mid='q1')
    bad = w.claim('agent:ic/b', 'o1')
    w('human:ceo', 'ask.answer', {'ask': 'q1', 'answer': 'N3'}, basis=w.d.s.head)
    return bad, w.claim('agent:ic/b', 'o1')


CASES = {'one-lease': ('I2', 'held', one_lease), 'fence': ('I3', 'fenced', fence), 'in-scope': ('I4', 'out-of-scope', in_scope), 'scope': ('I4', 'scope-overlap', scope),
         'basis': ('I6', 'stale', basis), 'basis/sub-order': ('I6', 'stale', basis_sub_order), 'basis/sub-order-ended': ('I6', 'stale', basis_sub_order_ended),
         'expect': ('I6', 'stale', expect), 'capacity': ('I7', 'over-capacity', capacity),
         'authority': ('I8', 'no-authority', authority), 'authority/top': ('I8', 'no-authority', authority_top), 'authority/sideways': ('I8', 'no-authority', authority_sideways),
         'subset': ('I8', 'not-subset', subset_scope), 'subset/budget': ('I8', 'not-subset', subset_budget), 'members': ('I8', 'not-addressee', members),
         'deps': ('I9', 'not-ready', deps_after), 'deps/pin': ('I9', 'not-ready', deps_pin),
         'judge': ('I10', 'no-judge', judge_missing), 'judge/doer': ('I10', 'no-judge', judge_is_doer), 'judge/unowned': ('I10', 'no-judge', judge_unowned), 'judge/self': ('I10', 'not-judge', judge_self),
         'capacity/shrink': ('I7', 'over-capacity', capacity_shrink), 'capacity/hold': ('I7', 'hold-and-wait', capacity_hold),
         'authority/outsider': ('I8', 'no-authority', authority_outsider), 'authority/question': ('I8', 'no-authority', authority_question),
         'judge/joins': ('I10', 'no-judge', judge_joins), 'deps/unknown': ('I9', 'unknown', deps_unknown), 'deps/cycle': ('I9', 'dependency-cycle', deps_cycle),
         'deps/released': ('I9', 'not-ready', deps_released), 'deps/question': ('I9', 'not-ready', deps_question),
         'deps/handed-in-above': ('I9', 'dependency-cycle', deps_handed_in_above)}


def broken(d):
    return sorted(i for i, v in check.check(d.log).items() if v)


class Guards(unittest.TestCase):
    def test_every_guard_has_a_case(self):
        self.assertEqual(sorted({k.split('/')[0] for k in CASES} | {'dedupe', 'notice'}), sorted(GUARDS))

    def test_overstep_refused_and_legal_twin_accepted(self):
        for name, (inv, code, steps) in CASES.items():
            w = World()
            bad, good = steps(w)
            self.assertEqual((bad['ok'], bad.get('code')), (False, code), name)
            self.assertTrue(good['ok'], (name, good))
            self.assertEqual(broken(w.d), [], name)

    def test_without_the_guard_the_referee_names_the_invariant(self):
        for name, (inv, code, steps) in CASES.items():
            w = World([g for g in GUARDS if g != name.split('/')[0]])
            bad, good = steps(w)
            self.assertTrue(bad['ok'], (name, bad))
            self.assertIn(inv, broken(w.d), name)

    def test_a_repeat_takes_effect_once(self):
        for guards, want in ((GUARDS, []), ([g for g in GUARDS if g != 'dedupe'], ['I5'])):
            w = World(guards)
            w.order('o1')
            le = w.claim('agent:ic/a', 'o1')['lease']
            first = w('agent:ic/a', 'report.progress', {'note': 'half way'}, lease=le, mid='p1')
            n = len(w.d.log)
            again = w('agent:ic/a', 'report.progress', {'note': 'half way'}, lease=le, mid='p1')
            self.assertEqual(broken(w.d), want)
            if not want:
                self.assertEqual((again.get('dup'), again['events'], len(w.d.log)), (True, first['events'], n))
                self.assertEqual(w('agent:ic/a', 'report.progress', {'note': 'something else'}, lease=le, mid='p1').get('code'), 'id-reuse')

    def test_when_a_pinned_input_moves_the_issuer_is_told(self):
        for guards, want in ((GUARDS, []), ([g for g in GUARDS if g != 'notice'], ['I9'])):
            w = World(guards)
            w.order('o1')
            w.order('o2', to='team:pkg', writes=['pkg/'], reads=[{'key': 'chip/die-size', 'rev': 1}])
            le = w.claim('agent:ic/a', 'o1')['lease']
            w('agent:ic/a', 'artifact.put', {'key': 'chip/die-size', 'expect': 0}, lease=le)
            self.assertEqual([e for e in w.d.log if e['kind'] == 'notice.input-moved'], [])            # revision 1 is what was pinned
            w('agent:ic/a', 'artifact.put', {'key': 'chip/die-size', 'expect': 1}, lease=le)
            told = [(e['order'], e['to'], e['pinned'], e['rev']) for e in w.d.log if e['kind'] == 'notice.input-moved']
            self.assertEqual(told, [] if want else [('o2', 'human:ceo', 1, 2)])
            self.assertEqual(broken(w.d), want)


class Rules(unittest.TestCase):
    def test_a_lease_ends_on_the_dispatcher_clock_and_too_many_ends_is_a_dead_letter(self):
        w = World()
        w.order('o1')
        for attempt in range(1, MAX_ATTEMPTS + 1):
            self.assertEqual(w.d.s.orders['o1']['attempt'], attempt)
            le = w.claim('agent:ic/a', 'o1', ttl=5)['lease']
            self.assertEqual(le['token'], attempt)
            w('agent:ic/b', 'state.query', dt=5)
        self.assertEqual(w.d.s.orders['o1']['state'], 'DEAD')
        self.assertEqual(w.claim('agent:ic/a', 'o1').get('code'), 'closed')
        self.assertEqual(broken(w.d), [])

    def test_the_goal_of_an_order_never_changes(self):
        w = World()
        w.order('o1')
        self.assertEqual(w('human:ceo', 'order.amend', {'order': 'o1', 'patch': {'goal': 'something else'}}, basis=w.d.s.head).get('code'), 'immutable')

    def test_cancel_takes_the_sub_orders_and_the_leases_with_it(self):
        w = World()
        w.order('o1')
        top = w.claim('team:ic', 'o1')['lease']
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=top, parent='o1', writes=['chip/rtl/'], budget=10)
        low = w.claim('agent:ic/a', 'o1.1')['lease']
        self.assertEqual(w('team:ic', 'artifact.put', {'key': 'chip/rtl/x', 'expect': 0}, lease=top).get('code'), 'out-of-scope')   # handed down
        self.assertEqual(w('team:ic', 'report.submit', {}, lease=top).get('code'), 'children-open')
        self.assertTrue(w('human:ceo', 'order.cancel', {'order': 'o1', 'reason': 'replanned'}, basis=w.d.s.head)['ok'])
        self.assertEqual([w.d.s.orders[x]['state'] for x in ('o1', 'o1.1')], ['CANCELLED', 'CANCELLED'])
        self.assertEqual(w('agent:ic/a', 'artifact.put', {'key': 'chip/rtl/x', 'expect': 0}, lease=low).get('code'), 'fenced')
        self.assertEqual(broken(w.d), [])

    def test_a_sideways_request_goes_up_as_a_question(self):
        w = World()
        r = w('team:pkg', 'order.propose', {'text': 'need the die size frozen', 'order': {'id': 'o7', 'to': 'team:ic'}})
        ask = w.d.s.asks[msg('m%d' % w.n, '', '')['id']]
        self.assertEqual((r['ok'], ask['to'], ask['state']), (True, 'human:ceo', 'OPEN'))
        self.assertEqual(w('team:ic', 'ask.answer', {'ask': ask['id'], 'answer': 'no'}, basis=w.d.s.head).get('code'), 'no-authority')
        self.assertTrue(w('human:ceo', 'ask.answer', {'ask': ask['id'], 'answer': 'approved'}, basis=w.d.s.head)['ok'])
        self.assertNotIn('o7', w.d.s.orders)                                                         # approving is not issuing

    def test_state_is_the_fold_of_the_log(self):
        import sim
        r, d = sim.run(3, GUARDS, 400)
        self.assertEqual(vars(Dispatcher(events=copy.deepcopy(d.log)).s), vars(d.s))
        self.assertEqual(r['broken'], {i: 0 for i in check.IDS})

    def test_why_an_order_has_not_started(self):
        w = World()
        w.order('o1', needs={'lic': 1})
        w.order('o2', to='team:pkg', writes=['chip/pd/'], after=['o1'], reads=[{'key': 'chip/die-size', 'rev': 1}], needs={'lic': 1})
        self.assertEqual(w.d.why('o1'), [{'because': 'unclaimed', 'to': 'team:ic'}])          # never empty: free to take, and by whom
        w.claim('agent:ic/a', 'o1')
        why = w('agent:pkg/a', 'state.query', {'why': 'o2'})['why']
        self.assertEqual([x['because'] for x in why], ['after', 'input', 'scope', 'capacity'])
        self.assertEqual((why[2]['holder'], why[3]['pool'], why[3]['used'], why[3]['cap']), ('agent:ic/a', 'lic', 1, 1))
        self.assertEqual(w('agent:pkg/a', 'state.query', {'why': 'nope'}).get('code'), 'unknown')
        since = w('agent:pkg/a', 'state.query', {'since': w.d.s.head - 1})
        self.assertEqual(([e['kind'] for e in since['log']], since['source']['stale']), (['lease.granted'], False))

    def test_a_failed_verdict_sends_it_back_and_the_next_holder_gets_a_higher_token(self):
        w = World()
        w.order('o1')
        w('agent:ic/a', 'report.submit', {}, lease=w.claim('agent:ic/a', 'o1')['lease'])
        w('program:drc', 'verdict', {'order': 'o1', 'pass': False, 'retry': True, 'reason': '3 violations'}, basis=w.d.s.head)
        self.assertEqual((w.d.s.orders['o1']['state'], w.d.s.orders['o1']['attempt'], w.claim('agent:ic/b', 'o1')['lease']['token']), ('PENDING', 2, 2))


def dead_middle():
    """root (team:ic) -> mid (agent:ic/a) -> leaf (agent:ic/a/x, long lease); mid's lease then runs out MAX_ATTEMPTS times."""
    w = World()
    w('human:ceo', 'org.set', {'actor': 'agent:ic/a/x', 'superior': 'agent:ic/a'})
    w.order('root')
    top = w.claim('team:ic', 'root', ttl=3000)['lease']
    w.order('mid', to='agent:ic/a', by='team:ic', lease=top, parent='root', writes=['chip/a/'], budget=50)
    low = None
    for attempt in range(MAX_ATTEMPTS):
        le = w.claim('agent:ic/a', 'mid', ttl=5)['lease']
        if low is None:
            w.order('leaf', to='agent:ic/a/x', by='agent:ic/a', lease=le, parent='mid', writes=['chip/a/x/'], budget=10)
            low = w.claim('agent:ic/a/x', 'leaf', ttl=3000)['lease']
        w('human:ceo', 'state.query', dt=5)
    return w, top, low


class _NoLock:
    def __enter__(self):
        return self

    def __exit__(self, *a):
        return False


class Review(unittest.TestCase):
    """One test per behaviour the independent review found wrong or unstated (finding id in each name)."""

    def test_dp04_a_dead_order_takes_everything_under_it(self):
        w, top, low = dead_middle()
        self.assertEqual([w.d.s.orders[x]['state'] for x in ('root', 'mid', 'leaf')], ['LEASED', 'DEAD', 'CANCELLED'])
        self.assertNotIn('leaf', w.d.s.leases)
        dead = next(e for e in w.d.log if e['kind'] == 'order.dead')
        swept = [e for e in w.d.log if e['kind'] == 'order.cancelled' and e.get('cascade')]
        self.assertEqual([(e['order'], e['cause']) for e in swept], [('leaf', dead['cause'])])
        self.assertEqual(w('agent:ic/a/x', 'artifact.put', {'key': 'chip/a/x/f', 'expect': 0}, lease=low).get('code'), 'fenced')
        self.assertTrue(w('team:ic', 'artifact.put', {'key': 'chip/a/x/f', 'expect': 0}, lease=top)['ok'])      # one writer left, not two
        self.assertEqual(broken(w.d), [])

    def test_dp06_two_callers_at_once_get_one_lease(self):
        for lock, want in ((None, [False, True]), (_NoLock(), [True, True])):       # second arm: without the lock this test does fail
            w = World()
            w.order('o1')
            if lock:
                w.d._lock = lock
            emit, head, out = w.d._emit, w.d.s.head, []

            def slow(kind, **payload):
                if kind == 'lease.granted':
                    time.sleep(0.05)                                                 # every check has passed; the other caller gets its turn before the grant is written
                emit(kind, **payload)
            w.d._emit = slow
            ts = [threading.Thread(target=lambda a=a: out.append(w.d.submit(msg('c-' + a, a, 'claim.request', {'order': 'o1', 'ttl': 100}, basis=head), 10)))
                  for a in ('agent:ic/a', 'agent:ic/b')]
            for t in ts:
                t.start()
            for t in ts:
                t.join(10)
            self.assertEqual(sorted(r['ok'] for r in out), want)
            self.assertEqual([i for i in broken(w.d) if i == 'I2'] if lock else broken(w.d), ['I2'] if lock else [])   # unlocked: two grants in the log, and the referee says so
            self.assertEqual(sorted(r.get('code', '') for r in out), ['', ''] if lock else ['', 'held'])

    def test_sc02_a_malformed_request_is_refused_at_the_door(self):
        w = World()
        w.order('o1')
        le = w.claim('agent:ic/a', 'o1')['lease']
        n = len(w.d.log)
        good = msg('x1', 'agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le)
        for name, change in (('wrong addressee', lambda m: m.update(to='team:pkg')), ('extra field', lambda m: m.update(force=True)), ('no body', lambda m: m.pop('body')),
                             ('no id', lambda m: m.pop('id')), ('lease without a token', lambda m: m['lease'].pop('token')), ('expect as text', lambda m: m['body'].update(expect='0'))):
            m = copy.deepcopy(good)
            change(m)
            self.assertEqual(w.d.submit(m, w.t).get('code'), 'bad-shape', name)
        self.assertEqual(w.d.submit(['not', 'an', 'object'], w.t).get('code'), 'bad-shape')
        self.assertEqual(w('agent:ic/a', 'state.query', {'limit': []}).get('code'), 'bad-shape')
        self.assertEqual(w.order('o2', to='team:pkg', writes=['pkg/'], reads=[{'key': 'chip/x', 'rev': '1'}]).get('code'), 'bad-shape')
        self.assertEqual(w.order('o3', to='team:pkg', writes=['pkg/'], needs={'lic': -1}).get('code'), 'bad-shape')           # SC01
        self.assertEqual((len(w.d.log), broken(w.d)), (n, []))

    def test_sc02_a_crash_half_way_leaves_nothing_behind(self):
        w = World()
        w.order('o1')
        le = w.claim('agent:ic/a', 'o1')['lease']
        n, real = len(w.d.log), w.d.do_report_progress

        def boom(m, b):
            real(m, b)                                                               # the event is written, then the handler dies
            raise RuntimeError('boom')
        w.d.do_report_progress = boom
        r = w('agent:ic/a', 'report.progress', {'note': 'half way', 'pct': 50}, lease=le, mid='p1')
        self.assertEqual((r['ok'], r['code'], len(w.d.log)), (False, 'internal', n))
        self.assertEqual(vars(Dispatcher(events=copy.deepcopy(w.d.log)).s), vars(w.d.s))
        del w.d.do_report_progress
        again = w('agent:ic/a', 'report.progress', {'note': 'half way', 'pct': 50}, lease=le, mid='p1')     # same id: judged afresh, not replayed
        self.assertEqual((again['ok'], again.get('dup'), len(w.d.log)), (True, None, n + 1))
        self.assertEqual((w.d.snapshot()['orders']['o1']['pct'], w.d.snapshot()['orders']['o1']['note']), (50, 'half way'))

    def test_sc03_a_repeat_gets_the_first_answer_back(self):
        w = World()
        w.order('o1', needs={'lic': 1})
        w.order('o2', to='team:pkg', writes=['pkg/'], needs={'lic': 1})
        c1 = msg('c1', 'agent:ic/a', 'claim.request', {'order': 'o1', 'ttl': 500}, basis=w.d.s.head)
        first, n = w.d.submit(copy.deepcopy(c1), w.t + 1), len(w.d.log)
        again = w.d.submit(copy.deepcopy(c1), w.t + 2)                              # the first reply was lost; the same message comes again
        self.assertEqual((first['ok'], again.get('dup'), again['lease'], len(w.d.log)), (True, True, first['lease'], n))
        w.t += 2
        put = w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=first['lease'], mid='p1')
        self.assertEqual((put['rev'], w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=first['lease'], mid='p1').get('rev')), (1, 1))
        m = msg('c2', 'agent:pkg/a', 'claim.request', {'order': 'o2', 'ttl': 100}, basis=w.d.s.head)
        self.assertEqual(w.d.submit(copy.deepcopy(m), w.t).get('code'), 'over-capacity')
        w('agent:ic/a', 'lease.release', {}, lease=first['lease'])
        later = w.d.submit(copy.deepcopy(m), w.t + 1)                                # a refusal is not remembered: the same id is judged again
        self.assertEqual((later['ok'], later.get('dup'), later['lease']['order']), (True, None, 'o2'))
        self.assertEqual(broken(w.d), [])

    def test_sc04_a_read_says_when_there_is_more_and_why_is_never_empty(self):
        w = World()
        w.order('o1')
        le = w.claim('agent:ic/a', 'o1', ttl=3000)['lease']
        for i in range(2 * PAGE + 7):
            w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': i}, lease=le)
        d, got, at, pages, now = w.d, [], 0, 0, w.t
        while True:
            r = d.submit(msg('page-%d' % pages, 'human:ceo', 'state.query', {'since': at}), now)
            got, pages = got + r['log'], pages + 1
            if not r['more']:
                break
            self.assertEqual((len(r['log']), r['next']), (PAGE, at + PAGE))             # a full page says so; it used to stop here without a word
            at = r['next']
        self.assertEqual(([e['seq'] for e in got], pages), (list(range(1, len(d.log) + 1)), -(-len(d.log) // PAGE)))
        w = World()
        w.order('o1')
        w.order('o2', to='team:pkg', writes=['pkg/'])
        w.claim('agent:ic/a', 'o1')
        w('human:ceo', 'order.cancel', {'order': 'o2'}, basis=w.d.s.head)
        held, gone = (w('agent:pkg/a', 'state.query', {'why': x})['why'] for x in ('o1', 'o2'))
        self.assertEqual((held[0]['because'], held[0]['state'], held[0]['holder'], 'token' in held[0]), ('state', 'LEASED', 'agent:ic/a', False))
        self.assertEqual(gone, [{'because': 'state', 'state': 'CANCELLED'}])

    def test_dp03_a_cancel_must_have_seen_the_latest_work(self):
        acts = {'a new revision': lambda w, le: w('team:ic', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le),
                'a progress report': lambda w, le: w('team:ic', 'report.progress', {'note': 'placed', 'pct': 40}, lease=le),
                'a new sub-order': lambda w, le: w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10),
                'a renewal': lambda w, le: w('team:ic', 'lease.renew', {'ttl': 500}, lease=le)}
        for name, act in acts.items():
            w = World()
            w.order('o1')
            le = w.claim('team:ic', 'o1')['lease']
            seen = w.d.s.head
            self.assertTrue(act(w, le)['ok'], name)
            old = w('human:ceo', 'order.cancel', {'order': 'o1'}, basis=seen)
            if name == 'a renewal':                                                      # a heartbeat: nothing the canceller needs to have seen
                self.assertTrue(old['ok'], name)
            else:
                self.assertEqual((old.get('code'), w('human:ceo', 'order.cancel', {'order': 'o1'}, basis=w.d.s.head)['ok']), ('stale', True), name)
            self.assertEqual(broken(w.d), [], name)

    def test_dp03_work_inside_a_sub_order_is_not_a_change_to_the_order_above(self):       # the other side of the line: only issuing and ending go up
        w = World()
        w.order('o1')
        le = w.claim('team:ic', 'o1')['lease']
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=10)
        seen = w.d.s.head
        sub = w.claim('agent:ic/a', 'o1.1')['lease']
        self.assertTrue(w('agent:ic/a', 'report.progress', {'note': 'placed', 'pct': 40}, lease=sub)['ok'])
        self.assertTrue(w('human:ceo', 'order.amend', {'order': 'o1', 'patch': {'priority': 5}}, basis=seen)['ok'])      # o1 itself is as it was
        self.assertEqual(w('human:ceo', 'order.cancel', {'order': 'o1'}, basis=seen).get('code'), 'stale')              # a cancel takes o1.1 too, and that moved
        self.assertEqual(broken(w.d), [])

    def test_dp07_a_refused_request_writes_nothing_of_its_own(self):
        w = World()
        w.order('o1')
        le = w.claim('agent:ic/a', 'o1', ttl=5)['lease']
        n = len(w.d.log)
        r = w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le, dt=10, mid='late')
        self.assertEqual((r['code'], [(e['kind'], e['cause'].split(':')[0]) for e in w.d.log[n:]]), ('fenced', [('lease.expired', 'clock')]))   # the clock's event stays; it is not the request's
        self.assertNotIn('late', w.d.s.seen)
        self.assertEqual(broken(w.d), [])

    def test_ck02_an_order_cannot_wait_for_one_that_already_ended(self):
        w = World()
        w.order('o1')
        w('human:ceo', 'order.cancel', {'order': 'o1'}, basis=w.d.s.head)
        self.assertEqual(w.order('o2', to='team:pkg', writes=['pkg/'], after=['o1']).get('code'), 'closed')
        self.assertEqual(w('human:ceo', 'org.set', {'actor': 'team:ic', 'superior': 'agent:ic/a'}).get('code'), 'bad-shape')    # reporting lines cannot loop

    def test_ck04_who_holds_a_shared_pool_is_there_to_read(self):
        w = World()
        w.order('o1', needs={'lic': 1}, priority=1)
        w.order('o2', to='team:pkg', writes=['pkg/'], needs={'lic': 1}, priority=9)
        le = w.claim('agent:ic/a', 'o1', ttl=10)['lease']
        for _ in range(5):                                                               # nothing stops a holder renewing for ever: a stated gap, not a rule
            self.assertTrue(w('agent:ic/a', 'lease.renew', {'ttl': 10}, lease=le, dt=5)['ok'])
        self.assertEqual(w.claim('agent:pkg/a', 'o2').get('code'), 'over-capacity')
        cap = w.d.why('o2')[0]
        self.assertEqual((cap['because'], [(h['order'], h['holder'], h['priority'], h['units']) for h in cap['holders']]), ('capacity', [('o1', 'agent:ic/a', 1, 1)]))

    def test_what_a_read_hands_back_is_a_copy(self):                                     # found while re-running the review: the rows were the ledger's own
        w = World()
        w.order('o1')
        le = w.claim('agent:ic/a', 'o1')['lease']
        first = json.dumps(w.d.log, sort_keys=True)
        for body in ({'since': 0}, {}, {'why': 'o1'}):
            r = w('agent:ic/a', 'state.query', body)
            for part in ('log', 'state', 'why', 'source'):
                for x in ([r[part]] if isinstance(r.get(part), dict) else r.get(part) or []):
                    for k in list(x):
                        x[k] = 'changed by the caller'
        le['token'] = 99
        self.assertEqual(json.dumps(w.d.log, sort_keys=True), first)
        self.assertEqual(w.d.s.leases['o1']['token'], 1)
        self.assertEqual(broken(w.d), [])
        self.assertEqual(Dispatcher(events=w.d.log).snapshot(), w.d.snapshot())


class Referee(unittest.TestCase):
    def log(self):
        w = World()
        w.order('o1')
        w.finish('agent:ic/a', 'o1', w.claim('agent:ic/a', 'o1')['lease'])
        self.assertEqual(broken(w.d), [])
        return copy.deepcopy(w.d.log)

    def test_does_not_borrow_the_dispatcher(self):
        with open(os.path.join(CORE, 'check.py'), encoding='utf-8') as f:
            src = f.read()
        self.assertNotIn('import dispatcher', src)
        self.assertNotIn('from dispatcher', src)

    def test_a_gap_or_a_clock_going_back_is_seen(self):
        log = self.log()
        self.assertIn('I1', [i for i, v in check.check(log[:3] + log[4:]).items() if v])
        log = self.log()
        log[-1]['t'] = 0
        self.assertIn('I1', [i for i, v in check.check(log).items() if v])

    def test_a_forged_success_is_seen(self):
        log = self.log()
        log[-1]['by'] = 'agent:ic/a'
        self.assertIn('I10', [i for i, v in check.check(log).items() if v])
        log = [e for e in self.log() if e['kind'] != 'report.submitted']
        for i, e in enumerate(log):
            e['seq'] = i + 1
        self.assertIn('I10', [i for i, v in check.check(log).items() if v])

    def busy(self):
        """A longer honest log: two orders, a question asked and answered, a pinned input that moves, one success."""
        w = World()
        w.order('o1')
        w.order('o2', to='team:pkg', writes=['pkg/'], reads=[{'key': 'chip/x', 'rev': 1}], needs={'lic': 1})
        le = w.claim('agent:ic/a', 'o1')['lease']
        w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 0}, lease=le)
        w('agent:ic/a', 'ask.raise', {'text': 'which node?', 'order': 'o1', 'blocking': False}, mid='q1')
        w('human:ceo', 'ask.answer', {'ask': 'q1', 'answer': 'N3'}, basis=w.d.s.head)
        w.claim('agent:pkg/a', 'o2')
        w('agent:ic/a', 'artifact.put', {'key': 'chip/x', 'expect': 1}, lease=le)
        w.finish('agent:ic/a', 'o1', le)
        self.assertEqual(broken(w.d), [])
        self.assertLessEqual({'ask.answered', 'notice.input-moved', 'order.succeeded'}, {e['kind'] for e in w.d.log})
        return copy.deepcopy(w.d.log)

    def named(self, log):
        return [i for i, v in check.check(log).items() if v]

    def test_what_an_event_says_about_itself_is_not_taken_on_trust(self):                # CK03: all four used to come back clean
        log = self.busy()
        log.append({'seq': len(log) + 1, 't': log[-1]['t'], 'kind': 'order.cancelled', 'cause': 'forged', 'n': 0, 'by': 'human:ceo', 'order': 'o2', 'cascade': True})
        self.assertEqual(self.named(log), ['I8'])                                        # "cascade" with nothing above it ending
        log = self.busy()
        next(e for e in log if e['kind'] == 'notice.input-moved')['to'] = 'agent:pkg/a'
        self.assertEqual(self.named(log), ['I9'])                                        # the notice went to someone who is not the issuer
        log = self.busy()
        next(e for e in log if e['kind'] == 'ask.answered')['by'] = 'agent:pkg/a'
        self.assertEqual(self.named(log), ['I8'])                                        # answered by someone it was not put to
        log = self.busy()
        log.append({'seq': len(log) + 1, 't': log[-1]['t'], 'kind': 'lease.granted', 'cause': 'forged', 'n': 0, 'by': 'agent:ic/b', 'order': 'o1', 'token': 2,
                    'expires': log[-1]['t'] + 50, 'basis': len(log)})
        self.assertEqual(self.named(log), ['I10'])                                       # leased again after it had passed

    def test_a_negative_need_is_seen(self):                                              # SC01
        log = self.busy()
        next(e for e in log if e['kind'] == 'order.issued' and e['body']['id'] == 'o2')['body']['needs']['lic'] = -1
        self.assertEqual(self.named(log), ['I7'])

    def test_an_order_left_open_under_a_dead_one_is_seen(self):                          # DP04
        log = [e for e in copy.deepcopy(dead_middle()[0].d.log) if not (e['kind'] == 'order.cancelled' and e.get('cascade'))]
        for i, e in enumerate(log):
            e['seq'] = i + 1
        self.assertEqual(self.named(log), ['I8'])


def both_run_out(other=None):
    """a-root (team:ic) runs out of attempts in the same clock step in which the lease on z-child, under it, also runs out.
    other: one more order, not under a-root, whose lease runs out in that same step."""
    w = World()
    w.order('a-root')
    if other:
        w.order(other, to='team:pkg', writes=['pkg/'])
    for _ in range(MAX_ATTEMPTS - 1):
        w.claim('team:ic', 'a-root', ttl=2)
        w('human:ceo', 'state.query', dt=2)
    top = w.claim('team:ic', 'a-root', ttl=4)['lease']                              # runs out at t0 + 4
    w.order('z-child', to='agent:ic/a', by='team:ic', lease=top, parent='a-root', writes=['chip/c/'], budget=10)
    w.claim('agent:ic/a', 'z-child', ttl=2)                                          # t0 + 2, runs out at t0 + 4
    if other:
        w.claim('agent:pkg/a', other, ttl=1)                                         # t0 + 3, runs out at t0 + 4
    mark = len(w.d.log)
    w('human:ceo', 'state.query', dt=1 if other else 2)                              # t0 + 4
    return w, w.d.log[mark:]


class Recheck(unittest.TestCase):
    """One test for each thing the second independent review (review3/REVIEW.md) found that was then changed."""

    def named(self, log):
        return [i for i, v in check.check(log).items() if v]

    def unchanged(self, w, first):
        self.assertEqual(json.dumps([w.d.log, w.d.snapshot()], sort_keys=True), first)
        self.assertEqual(broken(w.d), [])
        self.assertEqual(Dispatcher(events=w.d.log).snapshot(), w.d.snapshot())

    def test_r301_what_goes_out_is_a_copy_all_the_way_down(self):                       # the first fix copied the rows, not what is inside them
        w = World()
        w.order('o1', needs={'lic': 1})
        w.claim('agent:ic/a', 'o1')
        first = json.dumps([w.d.log, w.d.snapshot()], sort_keys=True)
        for got in (w('human:ceo', 'state.query')['state'], w.d.snapshot()):
            got['orders']['o1']['needs']['lic'] = 2
            got['orders']['o1']['writes'].append('elsewhere/')
            got['orders']['o1']['accept']['judge'] = 'agent:ic/a'
            got['leases']['o1']['token'] = 99
            got['pools']['lic']['cap'] = 9
            self.unchanged(w, first)
        self.assertEqual(w.d.s.orders['o1']['needs'], {'lic': 1})

    def test_r301_what_comes_in_is_copied_before_it_is_kept(self):                       # the sender goes on changing its own message
        w = World()
        m = msg('own', 'human:ceo', 'order.issue', {'id': 'o1', 'to': 'team:ic', 'writes': ['chip/'], 'budget': 100, 'accept': dict(J)})
        w.t += 1
        self.assertTrue(w.d.submit(m, w.t)['ok'])
        le = w.claim('agent:ic/a', 'o1')['lease']
        first = json.dumps([w.d.log, w.d.snapshot()], sort_keys=True)
        m['body']['writes'].append('elsewhere/')
        m['body']['accept']['judge'] = 'agent:ic/a'
        self.unchanged(w, first)
        self.assertEqual(w('agent:ic/a', 'artifact.put', {'key': 'elsewhere/x', 'expect': 0}, lease=le).get('code'), 'out-of-scope')
        self.assertEqual(next(e for e in w.d.log if e['kind'] == 'order.issued')['body']['writes'], ['chip/'])

    def test_r301_a_repeat_answer_is_a_copy_too(self):
        w = World()
        w.order('o1')
        c = msg('c1', 'agent:ic/a', 'claim.request', {'order': 'o1', 'ttl': 500}, basis=w.d.s.head)
        first = w.d.submit(copy.deepcopy(c), w.t + 1)
        kept = copy.deepcopy(first)
        first['events'].append(998)
        first['lease']['token'] = 98
        again = w.d.submit(copy.deepcopy(c), w.t + 2)
        self.assertEqual((again.get('dup'), again['events'], again['lease']), (True, kept['events'], kept['lease']))
        again['events'].append(999)
        again['lease']['token'] = 99
        third = w.d.submit(copy.deepcopy(c), w.t + 3)
        self.assertEqual((third.get('dup'), third['events'], third['lease']), (True, kept['events'], kept['lease']))
        self.assertEqual(broken(w.d), [])

    def test_r301_a_ledger_handed_in_is_copied(self):                                   # replay: whoever handed the events in may go on changing theirs
        w = World()
        w.order('o1', needs={'lic': 1})
        w.claim('agent:ic/a', 'o1')
        events = copy.deepcopy(w.d.log)
        d = Dispatcher(events=events)
        issued = next(e for e in events if e['kind'] == 'order.issued')
        issued['body']['writes'].append('elsewhere/')
        issued['body']['needs']['lic'] = 5
        events[0]['kind'] = 'changed by the caller'
        self.assertEqual(json.dumps(d.log, sort_keys=True), json.dumps(w.d.log, sort_keys=True))
        self.assertEqual(d.snapshot(), w.d.snapshot())

    def test_r310_leases_that_run_out_in_one_clock_step_are_not_judged_one_by_one(self):
        w, tail = both_run_out()
        self.assertEqual([e['kind'] for e in tail], ['lease.expired', 'order.dead', 'order.cancelled'])
        self.assertEqual((len({e['cause'] for e in tail}), tail[-1]['order'], tail[-1].get('cascade'), w.d.s.leases), (1, 'z-child', True, {}))
        self.assertEqual(broken(w.d), [])
        for name in ('zz-other', 'a-first'):                                             # sorted after and before the one that dies
            w, tail = both_run_out(name)
            self.assertEqual(sorted(e['kind'] for e in tail), ['lease.expired', 'lease.expired', 'order.cancelled', 'order.dead'])
            self.assertEqual((len({e['cause'] for e in tail}), w.d.s.leases), (1, {}))
            self.assertEqual(broken(w.d), [])

    def test_r310_a_ledger_that_stops_half_way_through_the_clock_step_is_seen(self):
        w, tail = both_run_out()
        log = copy.deepcopy(w.d.log)
        self.assertIn('I3', self.named(log[:-2]))                                        # a-root's lease ended, z-child's is past its time and still live
        self.assertIn('I3', self.named(log[:-1]))
        self.assertEqual(self.named(log[:-3]), [])                                       # stopping before the clock step is an honest ledger: nothing was due yet
        w, tail = both_run_out('zz-other')
        self.assertEqual(self.named(copy.deepcopy(w.d.log)[:-1]), ['I3'])                # everything under a-root is settled; the other lease is not

    def live_lease(self):
        w = World()
        w.order('o1')
        w.order('o2', to='team:pkg', writes=['pkg/'])
        le = w.claim('agent:ic/a', 'o1', ttl=5)['lease']
        self.assertEqual(broken(w.d), [])
        return copy.deepcopy(w.d.log), w.t + 5

    def forged(self, log, t, kind, **more):
        log.append(dict({'seq': len(log) + 1, 't': t, 'kind': kind, 'cause': more.pop('cause', 'forged'), 'n': more.pop('n', 0), 'by': more.pop('by', 'human:ceo')}, **more))
        return log

    def test_r310_outside_the_clock_step_a_lease_past_its_time_is_still_seen(self):
        log, end = self.live_lease()
        self.assertEqual(self.named(self.forged(log, end - 1, 'org.set', actor='agent:x', superior='human:ceo')), [])
        log, end = self.live_lease()
        self.assertEqual(self.named(self.forged(log, end, 'org.set', actor='agent:x', superior='human:ceo')), ['I3'])
        self.forged(log, end + 1, 'org.set', cause='forged again', actor='agent:y', superior='human:ceo')
        self.assertEqual(len(check.check(log)['I3']), 1)                                 # said once for one lease, not at every event after
        log, end = self.live_lease()
        self.forged(log, end, 'org.set', actor='agent:x', superior='human:ceo')          # a request acts while the lease is past its time ...
        self.forged(log, end, 'lease.expired', n=1, by='dispatcher', order='o1', token=1)   # ... and ends it itself before it is over
        self.assertIn('I3', self.named(log))

    def test_r310_calling_a_cancel_a_cascade_does_not_hide_a_lease_past_its_time(self):
        log, end = self.live_lease()
        self.forged(log, end, 'order.cancelled', order='o2', cascade=True)               # "cascade" with nothing above it ending
        self.assertEqual(self.named(log), ['I3', 'I8'])                                  # ... seen when the ledger stops there
        self.forged(log, end + 1, 'lease.expired', cause='clock:%d' % (len(log) + 1), by='dispatcher', order='o1', token=1)
        self.assertEqual(self.named(log), ['I3', 'I8'])                                  # ... and when the next request then ends the lease properly
        log, end = self.live_lease()
        self.forged(log, end, 'order.cancelled', order='o2')                             # an ordinary cancel is a request like any other: no excuse
        self.forged(log, end, 'lease.expired', n=1, by='dispatcher', order='o1', token=1)
        self.assertIn('I3', self.named(log))
        log, end = self.live_lease()
        self.forged(log, end, 'order.dead', order='o2')
        self.forged(log, end + 1, 'lease.expired', cause='clock:%d' % (len(log) + 1), by='dispatcher', order='o1', token=1)
        self.assertIn('I3', self.named(log))


    # R303: a sub-order that needs something handed in.  name -> (refused, steps); steps(w) returns the reply to issuing the reader.
    def reader(self, w, le, oid='o1.9', parent='o1', by='team:ic', to='agent:ic/b', writes=('chip/b/',), **read):
        return w.order(oid, to=to, by=by, lease=le, parent=parent, writes=list(writes), budget=10, reads=[dict({'key': 'chip/if', 'rev': 1, 'released': True}, **read)])

    def hand_in_first(self, w, oid='o0'):                                                 # an earlier order writes chip/if and passes: revision 1 is handed in
        w.order(oid)
        le = w.claim('agent:ic/a', oid)['lease']
        w('agent:ic/a', 'artifact.put', {'key': 'chip/if', 'expect': 0}, lease=le)
        w('agent:ic/a', 'report.submit', {'outputs': [{'key': 'chip/if', 'rev': 1}]}, lease=le)
        self.assertTrue(w('program:drc', 'verdict', {'order': oid, 'pass': True}, basis=w.d.s.head)['ok'])

    def top(self, w):
        w.order('o1')
        return w.claim('team:ic', 'o1')['lease']

    def nobody(self, w):
        return self.reader(w, self.top(w))

    def producer_cancelled(self, w):
        le = self.top(w)
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/if'], budget=10)
        self.assertTrue(w('team:ic', 'order.cancel', {'order': 'o1.1'}, basis=w.d.s.head)['ok'])
        return self.reader(w, le)

    def producer_waits_for_the_order_above(self, w):
        w.order('o1')
        self.assertTrue(w.order('ox', to='team:pkg', writes=['chip/if'], after=['o1'])['ok'])
        return self.reader(w, w.claim('team:ic', 'o1')['lease'])

    def two_levels_up(self, w):                                                           # chip/if is the top order's to write, not the parent's
        le = self.top(w)
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/a/'], budget=50)
        return self.reader(w, w.claim('agent:ic/a', 'o1.1')['lease'], oid='o1.1.1', parent='o1.1', by='agent:ic/a', to='agent:ic/a', writes=['chip/a/x/'])

    def handed_in_too_old(self, w):
        self.hand_in_first(w)
        return self.reader(w, self.top(w), rev=2)

    def producer_first(self, w):
        le = self.top(w)
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=le, parent='o1', writes=['chip/if'], budget=10)
        return self.reader(w, le)

    def producer_outside(self, w):
        w.order('o1')
        self.assertTrue(w.order('ox', to='team:pkg', writes=['chip/if'])['ok'])
        return self.reader(w, w.claim('team:ic', 'o1')['lease'])

    def not_theirs_to_write(self, w):                                                     # whoever hands pkg/x in is in somebody else's tree
        return self.reader(w, self.top(w), key='pkg/x')

    def already_handed_in(self, w):
        self.hand_in_first(w)
        return self.reader(w, self.top(w))

    def only_pinned(self, w):                                                             # the revision has to exist; nobody has to hand it in
        return self.reader(w, self.top(w), released=False)

    HANDED_IN = (('nobody', True), ('producer_cancelled', True), ('producer_waits_for_the_order_above', True), ('two_levels_up', True), ('handed_in_too_old', True),
                 ('producer_first', False), ('producer_outside', False), ('not_theirs_to_write', False), ('already_handed_in', False), ('only_pinned', False))

    def test_r303_an_input_only_the_orders_above_can_hand_in(self):
        for name, refused in self.HANDED_IN:
            w = World()
            r = getattr(self, name)(w)
            self.assertEqual((r['ok'], r.get('code')), (False, 'dependency-cycle') if refused else (True, None), name)
            self.assertEqual(broken(w.d), [], name)
            w = World([g for g in GUARDS if g != 'deps'])                                 # the referee says the same from the ledger alone
            self.assertTrue(getattr(self, name)(w)['ok'], name)
            self.assertEqual(broken(w.d), ['I9'] if refused else [], name)

    def test_r303_issued_in_that_order_the_whole_tree_finishes(self):
        w = World()
        top = self.top(w)
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=top, parent='o1', writes=['chip/if'], budget=10)
        self.assertTrue(self.reader(w, top)['ok'])
        le = w.claim('agent:ic/a', 'o1.1')['lease']
        w('agent:ic/a', 'artifact.put', {'key': 'chip/if', 'expect': 0}, lease=le)
        self.assertEqual(w.claim('agent:ic/b', 'o1.9').get('code'), 'not-ready')
        why = [x for x in w('human:ceo', 'state.query', {'why': 'o1.9'})['why'] if x['because'] == 'input-unreleased']
        self.assertEqual([(x['key'], x['released'], x['from']) for x in why], [('chip/if', [], ['o1.1'])])     # who it is waiting for
        w('agent:ic/a', 'report.submit', {'outputs': [{'key': 'chip/if', 'rev': 1}]}, lease=le)
        self.assertTrue(w('program:drc', 'verdict', {'order': 'o1.1', 'pass': True}, basis=w.d.s.head)['ok'])
        self.assertTrue(w.finish('agent:ic/b', 'o1.9', w.claim('agent:ic/b', 'o1.9')['lease'])['ok'])
        self.assertTrue(w.finish('team:ic', 'o1', top)['ok'])
        self.assertEqual(({o['state'] for o in w.d.s.orders.values()}, broken(w.d)), ({'SUCCEEDED'}, []))

    def test_r303_limit_it_is_only_looked_at_when_the_order_is_issued(self):
        w = World()
        top = self.top(w)
        w.order('o1.1', to='agent:ic/a', by='team:ic', lease=top, parent='o1', writes=['chip/if'], budget=10)
        self.reader(w, top)
        le = w.claim('agent:ic/a', 'o1.1')['lease']
        w('agent:ic/a', 'artifact.put', {'key': 'chip/if', 'expect': 0}, lease=le)
        self.assertTrue(w('team:ic', 'order.cancel', {'order': 'o1.1'}, basis=w.d.s.head)['ok'])               # the producer goes ...
        self.assertEqual(w.claim('agent:ic/b', 'o1.9').get('code'), 'not-ready')                               # ... and the reader waits for nobody
        why = [x for x in w('human:ceo', 'state.query', {'why': 'o1.9'})['why'] if x['because'] == 'input-unreleased']
        self.assertEqual([x['from'] for x in why], [[]])                                                       # which is what `why` says
        self.assertEqual(w('team:ic', 'report.submit', {}, lease=top).get('code'), 'children-open')
        self.assertEqual(broken(w.d), [])                                                                      # no rule was broken: it is the planner's to see
        w.order('o1.2', to='agent:ic/a', by='team:ic', lease=top, parent='o1', writes=['chip/if'], budget=10)  # the way out: a new producer (or cancel the reader)
        le = w.claim('agent:ic/a', 'o1.2')['lease']
        w('agent:ic/a', 'artifact.put', {'key': 'chip/if', 'expect': 1}, lease=le)
        w('agent:ic/a', 'report.submit', {'outputs': [{'key': 'chip/if', 'rev': 2}]}, lease=le)
        self.assertTrue(w('program:drc', 'verdict', {'order': 'o1.2', 'pass': True}, basis=w.d.s.head)['ok'])
        self.assertTrue(w.finish('agent:ic/b', 'o1.9', w.claim('agent:ic/b', 'o1.9')['lease'])['ok'])
        self.assertTrue(w.finish('team:ic', 'o1', top)['ok'])
        self.assertEqual(broken(w.d), [])


if __name__ == '__main__':
    unittest.main()
