#!/usr/bin/env python3
"""Library contracts with real handlers, ledgers, git blobs and the stand-in; no sockets or models."""
import collections
import concurrent.futures
import datetime
import hashlib
import json
import os
import shutil
import sys
import tempfile
import unittest
from unittest import mock

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))
sys.path.insert(0, HERE)

import cli
import library
import live
import opencode_agent
import planning
import serve
from test_calendar import MemoryServer, request
from test_cockpit import TEAM, FAKE


def read_json(path):
    with open(path, encoding='utf-8') as f:
        return json.load(f)


def bytes_in(folder):
    out = {}
    for root, _, names in os.walk(folder):
        for name in names:
            with open(os.path.join(root, name), 'rb') as f:
                out[os.path.relpath(os.path.join(root, name), folder)] = f.read()
    return out


class Library(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix='library-test-')
        self.instances, self.serial = [], 0
        self.addCleanup(self.cleanup)
        for patch in (mock.patch.object(serve, 'Server', MemoryServer),
                      mock.patch.object(live.Live, 'start', lambda instance: instance)):
            patch.start()
            self.addCleanup(patch.stop)

    def cleanup(self):
        for instance in self.instances:
            instance.srv.server_close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def start(self, extra=None, **kw):
        for previous in self.instances:
            previous.srv.server_close()
        team = json.loads(json.dumps(TEAM))
        team['pass_env'].append('FAKE_OPENCODE_LIBRARY')
        with mock.patch.dict(os.environ, {'FAKE_OPENCODE_LIBRARY': json.dumps(extra or {})}):
            instance = serve.start(self.tmp, team, exe=FAKE, every=0.1, pace=0.01,
                                   offset=len(self.instances) * 86400, **kw)
        self.instances.append(instance)
        return instance

    def get(self, instance, path):
        code, result = request(instance, 'GET', path)
        self.assertEqual(code, 200, result)
        return result

    def post(self, instance, path, body):
        code, result = request(instance, 'POST', path, body)
        self.assertEqual(code, 200, result)
        return result

    def issue(self, instance, oid, **kw):
        fields = dict(title='Try ' + oid, goal='Write and review a note.', writes='', budget=6)
        fields.update(kw)
        result = self.post(instance, '/message', planning.envelope(fields, oid, instance.lead, 'ui-' + oid))
        self.assertTrue(result['ok'], result)

    def complete(self, instance, oid):
        for _ in range(20):
            instance.once()
            if instance.ad.d.snapshot()['orders'][oid]['state'] == 'SUCCEEDED':
                return
        self.fail('stand-in order did not succeed')

    def save(self, instance, oid, kind='skill', **kw):
        body = dict(run=os.path.basename(instance.run), order=oid, path=oid + '/draft/notes.md',
                    kind=kind, title='Review checklist', tags=['review', 'text'])
        body.update(kw)
        return self.post(instance, '/library/save', body)['entry']

    def message(self, instance, kind, body, actor=None, lease=None):
        self.serial += 1
        doc = dict(v='dispatch/1', id='test-%d' % self.serial, to='dispatcher',
                   kind=kind, body=body, **{'from': actor or live.CEO})
        if lease:
            doc['lease'] = {k: lease[k] for k in ('order', 'token')}
        else:
            doc['basis'] = instance.srv.writer.d.s.head
        result = self.post(instance, '/message', doc)
        self.assertTrue(result['ok'], result)
        return result

    def handed(self, instance, oid, data, path='shared/file.txt'):
        self.issue(instance, oid, writes='shared/')
        lease = self.message(instance, 'claim.request', {'order': oid}, instance.lead)['lease']
        sha = instance.ad.git.blob(data)
        rev = instance.ad.d.snapshot()['artifacts'].get(path, 0)
        self.message(instance, 'artifact.put', {'key': path, 'expect': rev, 'note': 'git:' + sha}, instance.lead, lease)
        self.message(instance, 'report.submit', {'outputs': [{'key': path, 'rev': rev + 1}]}, instance.lead, lease)
        self.message(instance, 'verdict', {'order': oid, 'pass': True}, live.JUDGE)

    def test_empty_context_matches_every_launch_rules_and_excluded_channel(self):
        instance = self.start()
        empty = dict(v='library/1', skills=[], artifacts=[], workflows=[], lessons=[])
        self.assertEqual(self.get(instance, '/library/context'), empty)
        self.assertEqual(self.get(instance, '/library'), {'entries': [], 'counts': dict.fromkeys(library.KINDS, 0)})
        self.assertEqual(self.get(instance, '/library/efficiency'), {'orders': []})
        self.assertEqual(request(instance, 'GET', '/library/item?id=missing')[1]['cli'], 'unknown-entry')
        checked, launch = [], opencode_agent.launch
        def check_launch(argv, box, *args, **kw):
            expected = self.get(instance, '/library/context')
            self.assertEqual(read_json(os.path.join(box, '_dispatch', 'LIBRARY.json')), expected)
            doc = read_json(os.path.join(box, '_dispatch', 'ORDER.json'))
            self.assertIn('LIBRARY.json', doc['rules'])
            if doc['seat'] == 'planner':
                for text in ('before planning', 'Reuse what fits', '"uses"', '"propose"'):
                    self.assertIn(text, doc['rules'])
            else:
                self.assertIn('follow the listed skills that fit', doc['rules'])
            checked.append(doc['seat'])
            return launch(argv, box, *args, **kw)
        self.issue(instance, 'first')
        self.assertEqual(self.get(instance, '/order?id=first')['library'],
                         {'workflow': None, 'uses': [], 'proposed': [], 'saved': {}})
        with mock.patch.object(opencode_agent, 'launch', check_launch):
            self.complete(instance, 'first')
        self.assertEqual(checked, ['planner', 'worker', 'worker'])
        for launch in instance.ad.launches:
            for field in ('taken', 'outside', 'refused'):
                self.assertNotIn('LIBRARY.json', json.dumps(launch[field]))
        self.assertEqual(len(self.get(instance, '/order?id=first')['files']), 2)
        self.assertEqual([e for e in instance.ad.d.log if e['kind'] == 'artifact.rev' and '_dispatch' in e['key']], [])
        self.assertEqual(self.get(instance, '/history')['skipped'], [])
        self.assertNotIn('library', [r['run'] for r in self.get(instance, '/history')['runs']])
        self.assertEqual(request(instance, 'GET', '/order?run=library&id=first')[0], 404)
        for path in ('/library', '/library/context', '/library/efficiency', '/library/item?id=x'):
            self.assertEqual(request(instance, 'GET', path, origin='http://elsewhere.invalid')[0], 403)
        for path in ('/library/save', '/library/review'):
            self.assertEqual(request(instance, 'POST', path, {}, origin='http://elsewhere.invalid')[0], 403)

    def test_saves_validate_ownership_keep_bytes_and_survive_two_restarts(self):
        first = self.start()
        self.issue(first, 'first')
        self.complete(first, 'first')
        run = os.path.basename(first.run)
        body = dict(run=run, order='first.draft', path='first/draft/notes.md', kind='artifact', title='Reference', tags=[])
        before = bytes_in(first.srv.library.root)
        bad = [{'run': 'missing'}, {'run': '..'}, {'run': 'library'}, {'run': []}, {'order': 'missing'}, {'order': []},
               {'path': '../team.json'}, {'path': '/absolute'}, {'path': 'first/../draft/notes.md'},
               {'path': 'first/review/review.md'}, {'path': 'first//draft/notes.md'}, {'path': []},
               {'path': '_dispatch/LIBRARY.json'}, {'path': 'first\\draft\\notes.md'}]
        for change in bad:
            code, result = request(first, 'POST', '/library/save', dict(body, **change))
            self.assertEqual((code, result['cli']), (400, 'not-a-handed-in-file'), change)
            self.assertEqual(bytes_in(first.srv.library.root), before)
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            results = list(pool.map(lambda _: request(first, 'POST', '/library/save', body), range(4)))
        self.assertEqual({code for code, _ in results}, {200})
        self.assertEqual(len({result['entry']['id'] for _, result in results}), 1)
        artifact = results[0][1]['entry']
        skill = self.save(first, 'first')
        again = self.save(first, 'first', title='Ignored duplicate title')
        self.assertEqual(again, skill)
        self.assertNotEqual(artifact['id'], skill['id'])
        data = first.srv.history.file_bytes(run, body['path'], {'first.draft'})
        for entry in (artifact, skill):
            self.assertRegex(entry['id'], r'^[a-z0-9-]{1,48}$')
            self.assertNotIn(run, entry['id'])
            self.assertEqual(entry['sha256'], hashlib.sha256(data).hexdigest())
            self.assertEqual(entry['bytes'], len(data))
            self.assertEqual(entry['summary'], ' '.join(data.decode().split())[:200])
            self.assertEqual(entry['status'], 'accepted')
            self.assertEqual(entry['by'], live.CEO)
            self.assertEqual(entry['version'], 1)
            self.assertEqual(entry['used'], 0)
            datetime.datetime.fromisoformat(entry['at'])
            self.assertEqual(self.get(first, '/library/item?id=' + entry['id'])['text'].encode(), data)
        detail = self.get(first, '/order?id=first')['library']
        self.assertEqual(detail['saved']['first/draft/notes.md'], skill['id'])
        workflow = detail['workflow']
        second = self.start({'uses': 'context'})
        context = self.get(second, '/library/context')
        self.assertEqual([s['id'] for s in context['skills']], [skill['id']])
        self.assertEqual([a['id'] for a in context['artifacts']], [artifact['id']])
        expected = context
        self.issue(second, 'second')
        second.once()
        self.assertEqual(read_json(os.path.join(second.ad.launches[0]['box'], '_dispatch', 'LIBRARY.json')), expected)
        self.complete(second, 'second')
        third = self.start()
        entries = self.get(third, '/library')['entries']
        self.assertEqual(sum(e['id'] == workflow for e in entries), 1)
        self.assertEqual(sum(e['kind'] == 'workflow' for e in entries), 2)
        self.assertEqual(self.get(third, '/library/item?id=' + skill['id'])['used'], 1)
        self.assertEqual(self.get(third, '/library')['counts'], dict(artifact=1, skill=1, workflow=2, lesson=0))
        self.assertEqual([o['order'] for o in self.get(third, '/library/efficiency')['orders']], ['first', 'second'])

    def test_proposals_usage_accept_replace_reject_and_atomic_review(self):
        first = self.start()
        self.issue(first, 'seed')
        self.complete(first, 'seed')
        old = self.save(first, 'seed')
        proposal = lambda title, **kw: dict(kind='skill', title=title, text='Check the inputs before writing.',
                                           replaces=None, why='Avoid repeat launches.', **kw)
        replacement = proposal('Better checklist')
        replacement['replaces'] = old['id']
        second = self.start({'uses': [old['id'], 'missing-reference', old['id']],
                             'propose': [replacement, proposal('Unhelpful'), proposal('Third'), proposal('Fourth')]})
        self.issue(second, 'learn')
        self.complete(second, 'learn')
        detail = self.get(second, '/order?id=learn')['library']
        self.assertEqual(detail['uses'], [{'id': old['id'], 'kind': 'skill', 'title': old['title']}])
        proposed = detail['proposed']
        self.assertEqual(len(proposed), 3)
        self.assertEqual([s['id'] for s in self.get(second, '/library/context')['skills']], [old['id']])
        workflow = self.get(second, '/library/item?id=' + detail['workflow'])
        self.assertEqual(workflow['uses'], [old['id']])
        self.assertEqual(workflow['unknown_uses'], ['missing-reference'])
        self.assertEqual(self.get(second, '/library/item?id=' + old['id'])['used'], 1)
        new, rejected = proposed[:2]
        self.assertEqual((new['by'], new['version'], new['replaces']), (second.lead, 2, old['id']))
        self.assertEqual(new['source'], dict(run=os.path.basename(second.run), order='learn', path='_dispatch/plan.json'))
        before = bytes_in(second.srv.library.root)
        for reason in ('', '  '):
