        self.post(second, '/library/review', dict(id=new['id'], decision='accept', reason='Use it.'))
        self.assertEqual(self.get(second, '/library/item?id=' + old['id'])['status'], 'superseded')
        self.assertEqual([s['id'] for s in self.get(second, '/library/context')['skills']], [new['id']])
        self.post(second, '/library/review', dict(id=rejected['id'], decision='reject', reason='This repeats the existing skill.'))
        lesson = self.get(second, '/library/context')['lessons'][0]
        self.assertEqual((lesson['order'], lesson['seat'], lesson['reason']), ('learn', second.lead, 'This repeats the existing skill.'))
        for eid in (new['id'], rejected['id'], old['id'], 'missing'):
