            self.assertEqual((code, result['cli']), (400, 'not-reviewable'))
        third = self.start()
        self.assertEqual([s['id'] for s in self.get(third, '/library/context')['skills']], [new['id']])
        self.assertEqual(len(self.get(third, '/library/context')['lessons']), 1)
        expected = self.get(third, '/library/context')
        self.issue(third, 'next')
        third.once()
        self.assertEqual(read_json(os.path.join(third.ad.launches[0]['box'], '_dispatch', 'LIBRARY.json')), expected)

    def test_invalid_proposals_and_refused_plans_do_not_change_plan_semantics(self):
        first = self.start({'uses': ['unknown'], 'propose': [
            dict(kind='skill', title='Too large', text='x' * 8193, why='large', replaces=None),
            dict(kind='skill', title='Wrong replacement', text='text', why='missing', replaces='missing'),
            dict(kind='artifact', title='Wrong kind', text='text', why='wrong', replaces=None)]})
        self.issue(first, 'invalid')
        self.complete(first, 'invalid')
        self.assertEqual(self.get(first, '/order?id=invalid')['library']['proposed'], [])
        second = self.start({'uses': ['unknown'], 'propose': [dict(kind='skill', title='Valid', text='Do a check.', why='Try it.')]})
        self.issue(second, 'refused', budget=1)
        second.once()
        self.assertEqual(second.ad.launches[0]['outcome'], 'plan-refused')
