    def test_plan_receipt_recovers_once_and_proposal_limit_counts_utf8_bytes(self):
        first = self.start()
        self.issue(first, 'seed')
        self.complete(first, 'seed')
        seed = self.save(first, 'seed')
        text = chr(233) * 4096  # Exactly 8192 UTF-8 bytes; character counts alone are insufficient.
        second = self.start({'uses': [seed['id']], 'propose': [
            dict(kind='skill', title='At limit', text=text, why='A limit test.'),
            dict(kind='skill', title='Over limit', text=text + 'x', why='Too long.'),
            dict(kind='skill', title='Invalid text', text=chr(0xd800), why='Invalid UTF-8.')]})
        self.issue(second, 'recover')
        with mock.patch.object(second.srv.library, 'record_plan', side_effect=OSError('interrupted receipt')):
            with self.assertRaises(OSError):
                second.once()
        # The git layer already issued the plan. Recovery proves that from ledger rows and the saved plan.
        detail = self.get(second, '/order?id=recover')['library']
        self.assertEqual(len(detail['proposed']), 1)
        proposal = detail['proposed'][0]
        self.assertEqual((proposal['title'], proposal['bytes']), ('At limit', 8192))
        for _ in range(2):
            self.get(second, '/library/context')
        self.assertEqual(self.get(second, '/library/item?id=' + seed['id'])['used'], 1)
        self.complete(second, 'recover')
        third = self.start()
        self.assertEqual(self.get(third, '/library/item?id=' + seed['id'])['used'], 1)
        run = os.path.basename(second.run)
        self.assertEqual([e['id'] for e in self.get(third, '/order?run=' + run + '&id=recover')['library']['proposed']], [proposal['id']])

    def test_bad_save_metadata_and_binary_skills_write_nothing(self):
        instance = self.start()
        self.handed(instance, 'file', b'Plain text')
        body = dict(run=os.path.basename(instance.run), order='file', path='shared/file.txt', kind='skill', title='A skill')
        before = bytes_in(instance.srv.library.root)
        for change in ({'kind': 'workflow'}, {'title': ''}, {'title': 'x' * 201}, {'tags': 'tag'},
                       {'tags': [1]}, {'title': chr(0xd800)}):
