#!/usr/bin/env python3
"""The one-file script writes exactly the files it was built from, only inside its folder, and notices a damaged copy.

Runs real bash into temporary folders; no sockets or models."""
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, 'tools'))
import make_oneshot  # noqa: E402

BASH = shutil.which('bash')
CHECKOUT = bool(shutil.which('git')) and os.path.exists(os.path.join(ROOT, '.git')) and os.path.exists(os.path.join(ROOT, make_oneshot.OUT))
OPEN = re.compile(r"^(cat|b64) > '([^']+)' <<'(OC_EOF_\d+_*)'$")
PLAIN = re.compile(r"^(?:(chmod \+x|chop|: >) '([^']+)'|mkdir -p(?: '[^']+')+)$")
SYNTHETIC = [
    ('bin/tool', b'#!/bin/sh\necho "$HOME" `date` \\n $(id) \'quoted\'\n', True),
    ('cr.txt', b'a\r\nb\r\n', False),
    ('deep/blank-lines.txt', b'x\n\n\n', False),
    ('deep/er/empty', b'', False),
    ('deep/no-newline.txt', b'first\n\nneedle-line\nlast', False),
    ('marks.txt', ('\n'.join(['OC_EOF_%d%s' % (n, tail) for n in range(10) for tail in ('', '_')]
                             + ['bad=0; n=0', 'mkdir -p "$dest"; cd "$dest"', "chmod +x '/bin/sh'"]) + '\n').encode('ascii'), False),
    ('pixels.bin', bytes(range(256)) * 3, False),
    ('utf8.txt', 'café → tab\there, trailing spaces  \n'.encode('utf-8'), False),
]


def head(text):
    """The lines before the first file: what the script says it needs and what it checks before it writes anything."""
    return text.split('\nmkdir -p "$dest"; cd "$dest"\n')[0]


def body(text):
    """[(verb, [paths])] of every command between the fixed head and the fixed tail; fails on any other kind of line."""
    lines = text.split('\n')
    i, found = lines.index('mkdir -p "$dest"; cd "$dest"') + 1, []
    while lines[i] != 'bad=0; n=0':
        opened, plain = OPEN.match(lines[i]), PLAIN.match(lines[i])
        if opened:
            found.append((opened.group(1), [opened.group(2)]))
            i = lines.index(opened.group(3), i + 1)
        elif plain:
            found.append((plain.group(1) or 'mkdir', re.findall(r"'([^']+)'", lines[i])))
        else:
            raise AssertionError('line %d does something else than write a file in the folder: %r' % (i + 1, lines[i][:80]))
        i += 1
    return found


def files_under(folder):
    found = {}
    for base, _, names in os.walk(folder):
        for name in names:
            full = os.path.join(base, name)
            with open(full, 'rb') as f:
                found[os.path.relpath(full, folder).replace(os.sep, '/')] = (f.read(), os.access(full, os.X_OK))
    return found


class Carries:
    """What must hold for any script build() gives; the two classes below say which rows."""
    rows = ()

    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix='oc-oneshot-')
        self.addCleanup(shutil.rmtree, self.tmp, True)
        self.work = os.path.join(self.tmp, 'work')
        os.mkdir(self.work)
        self.text = make_oneshot.build(self.rows)
        self.script = self.write('script.sh', self.text)

    def write(self, name, text):
        path = os.path.join(self.tmp, name)
        with open(path, 'wb') as f:
            f.write(text.encode('utf-8'))
        return path

    def run_script(self, *args, script=None, env=None):
        return subprocess.run([BASH, script or self.script] + list(args), cwd=self.work, env=env, stdin=subprocess.DEVNULL,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True, timeout=120)

    def test_writes_every_file_and_nothing_else(self):
        done = self.run_script('out')
        self.assertEqual(done.returncode, 0, done.stderr)
        want = {path: (data, executable) for path, data, executable in self.rows}
        got = files_under(os.path.join(self.work, 'out'))
        self.assertEqual(sorted(got), sorted(want))
        for path in want:
            self.assertEqual(got[path], want[path], path)
        self.assertEqual(os.listdir(self.work), ['out'])
        self.assertEqual(sorted(os.listdir(self.tmp)), ['script.sh', 'work'])
        self.assertIn('Wrote %d files' % len(want), done.stdout)

    def test_body_only_writes_the_files_it_names(self):
        found = body(self.text)
        named = [path for _, paths in found for path in paths]
        for path in named:
            self.assertTrue(make_oneshot.SAFE.match(path) and '..' not in path.split('/'), path)
        written = sorted(paths[0] for verb, paths in found if verb in ('cat', 'b64', ': >'))
        self.assertEqual(written, sorted(path for path, _, _ in self.rows))
        self.assertEqual(sorted(paths[0] for verb, paths in found if verb == 'chmod +x'), sorted(p for p, _, x in self.rows if x))
        self.assertEqual(sorted(p for p, d, _ in self.rows if d and not d.endswith(b'\n') and make_oneshot.is_text(d)),
                         sorted(paths[0] for verb, paths in found if verb == 'chop'))


@unittest.skipUnless(BASH, 'needs bash')
class Synthetic(Carries, unittest.TestCase):
    rows = SYNTHETIC

    def test_only_files_with_bytes_a_here_document_cannot_carry_are_base64(self):
        self.assertEqual(sorted(paths[0] for verb, paths in body(self.text) if verb == 'b64'), ['cr.txt', 'pixels.bin'])

    def test_a_damaged_copy_fails_loudly(self):
        self.assertEqual(self.text.count('needle-line'), 1)
        done = self.run_script('out', script=self.write('damaged.sh', self.text.replace('needle-line', 'needle-lime')))
        self.assertEqual(done.returncode, 1)
        self.assertEqual(done.stderr.splitlines(), ['opencode-cockpit.sh: deep/no-newline.txt is not what this script holds',
                                                    'opencode-cockpit.sh: 1 of %d files are wrong; do not use this folder' % len(SYNTHETIC)])
        self.assertNotIn('Wrote', done.stdout)

    def test_refuses_a_folder_that_holds_files(self):
        os.mkdir(os.path.join(self.work, 'out'))
        with open(os.path.join(self.work, 'out', 'mine.txt'), 'w') as f:
            f.write('keep')
        done = self.run_script('out')
        self.assertEqual(done.returncode, 2)
        self.assertIn('already holds files', done.stderr)
        self.assertEqual(files_under(os.path.join(self.work, 'out')), {'mine.txt': (b'keep', False)})

    def test_takes_an_empty_folder_and_a_default_name(self):
        os.mkdir(os.path.join(self.work, 'out'))
        self.assertEqual(self.run_script('out').returncode, 0)
        self.assertEqual(self.run_script().returncode, 0)
        self.assertEqual(sorted(os.listdir(self.work)), ['opencode-cockpit', 'out'])
        self.assertEqual(files_under(os.path.join(self.work, 'opencode-cockpit')), files_under(os.path.join(self.work, 'out')))

    def test_an_option_is_not_taken_as_a_folder(self):
        done = self.run_script('-x')
        self.assertEqual(done.returncode, 2)
        self.assertEqual(done.stderr.strip(), 'usage: bash opencode-cockpit.sh [FOLDER]')
        self.assertEqual(os.listdir(self.work), [])

    def test_says_which_program_is_missing_and_writes_nothing(self):
        bare = os.path.join(self.tmp, 'bare')
        os.mkdir(bare)
        done = self.run_script('out', env={'PATH': bare})
        self.assertEqual((done.returncode, done.stderr.strip()), (2, 'opencode-cockpit.sh: needs base64 to write the files that are not text'))
        os.symlink(shutil.which('base64'), os.path.join(bare, 'base64'))
        done = self.run_script('out', env={'PATH': bare})
        self.assertEqual((done.returncode, done.stderr.strip()), (2, 'opencode-cockpit.sh: needs sha256sum or shasum to check what it writes'))
        self.assertEqual(os.listdir(self.work), [])

    def test_refuses_to_build_with_a_path_that_could_leave_the_folder(self):
        for path in ('../up', 'a/../b', '/abs', '-dash', 'a b', "a'b", 'a/./b', 'a//b', 'a/', '$x', 'a\nb', 'a\n'):
            with self.assertRaises(SystemExit, msg=path):
                make_oneshot.build([(path, b'x\n', False)])


@unittest.skipUnless(BASH, 'needs bash')
class TextOnly(Carries, unittest.TestCase):
    rows = [row for row in SYNTHETIC if row[0] not in ('cr.txt', 'pixels.bin')]

    def test_asks_for_no_base64_and_runs_without_it(self):
        self.assertEqual([paths[0] for verb, paths in body(self.text) if verb == 'b64'], [])
        self.assertNotIn('base64', head(self.text))
        bare = os.path.join(self.tmp, 'bare')
        os.mkdir(bare)
        for tool in ('mkdir', 'cat', 'mv', 'chmod', 'cut', 'sha256sum', 'shasum'):
            if shutil.which(tool):
                os.symlink(shutil.which(tool), os.path.join(bare, tool))
        done = self.run_script('out', env={'PATH': bare})
        self.assertEqual((done.returncode, done.stderr), (0, ''))
        self.assertEqual(files_under(os.path.join(self.work, 'out')), {path: (data, x) for path, data, x in self.rows})


@unittest.skipUnless(BASH and CHECKOUT, 'needs bash and a git checkout that holds opencode-cockpit.sh (a folder written by that file is not one)')
class Repository(Carries, unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.rows = make_oneshot.tracked()

    def test_file_is_what_the_tracked_files_give(self):
        with open(os.path.join(ROOT, make_oneshot.OUT), 'rb') as f:
            self.assertEqual(f.read(), self.text.encode('utf-8'), 'run python3 tools/make_oneshot.py')

    def test_every_file_is_carried_as_text(self):
        self.assertEqual([paths[0] for verb, paths in body(self.text) if verb == 'b64'], [])
        self.assertNotIn('base64', head(self.text))


