"""The page files and the icons, read as text (no browser): what is served exists, nothing is fetched from elsewhere,
there is one light theme, text only ever enters the page as text, and web/icons.js is what icons/ gives."""
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
