        cases = [(0, 'launch', '0 launches'), (1, 'launch', '1 launch'), (2, 'launch', '2 launches'),
                 (1, 'file', '1 file'), (3, 'file', '3 files'), (1, 'order', '1 order'), (2, 'order', '2 orders'),
