            result = subprocess.run(['node', '-e', script], capture_output=True, text=True, check=True)
            self.assertEqual(json.loads(result.stdout), [c[2] for c in cases])

    def test_quiet_chrome_and_compact_layout_contracts(self):
        css = text('web', 'app.css')
        def rule(selector):
            return re.search(r'(?m)^' + re.escape(selector) + r'\s*\{([^}]+)\}', css).group(1)
        self.assertIn('background: var(--wash)', rule('.rail'))
        self.assertNotIn('height:', rule('.rail').replace('min-height:', ''))
        self.assertIn('background: transparent', rule('nav[data-nav]'))
