        self.assertIn('margin-top: 16px', rule('[data-order-proposed]'))
        self.assertIn('flex-direction: row', rule('#attention .empty'))
        self.assertNotIn('text-overflow', rule('.launch-order'))
        self.assertIn('font-variant-numeric: tabular-nums', rule('.activity time'))
        self.assertEqual(set(re.findall(r'--text-[\w-]+:\s*(\d+)px', css)), {'12', '13', '14', '16', '20', '28'})

    def test_every_text_colour_has_aa_contrast_on_every_surface_it_can_use(self):
        css = text('web', 'app.css')
        tokens = dict(re.findall(r'(--[\w-]+):\s*(#[0-9a-f]{6});', css))
        # Audit all inherited text colours against all pale surfaces, a superset of
        # actual pairs, including gradient endpoints, hover, disabled and state pills.
        foregrounds = {'--ink', '--ink-2', '--ink-3', '--accent', '--wait', '--run', '--ok', '--attention', '--bad'}
        surfaces = {'--paper', '--wash', '--accent-wash', '--hero-end', '--run-wash', '--ok-wash', '--attention-wash', '--bad-wash'}
        used_text = set(re.findall(r'(?:^|[;{])\s*(?:color|fill):\s*var\((--[\w-]+)\)', css))
        self.assertLessEqual(used_text, foregrounds | surfaces | {'--accent-ink'})
        used_background = set(re.findall(r'background(?:-color)?:\s*var\((--[\w-]+)\)', css))
        self.assertLessEqual(used_background, surfaces | {'--accent', '--skeleton', '--wait', '--run', '--ok', '--bad'})
        self.assertEqual(set(re.findall(r'(?<![\w-])#[0-9a-fA-F]{6}\b', css[css.index('* {'):])) - {'#ffffff'}, set())
        pairs = [(fg, bg) for fg in foregrounds for bg in surfaces] + [('--accent-ink', '--accent')]
        for fg, bg in pairs:
            light, dark = sorted((luminance(tokens[fg]), luminance(tokens[bg])), reverse=True)
            self.assertGreaterEqual((light + 0.05) / (dark + 0.05), 4.5, (fg, bg))
        # New team tiles/status/time, used-entry pills, group headings and arrows
        # inherit only these audited pairs, including their hover surfaces.
        for pair in (('--ink', '--wash'), ('--ink-2', '--wash'), ('--ink-3', '--wash'),
                     ('--ink-2', '--paper'), ('--ink-3', '--paper'),
                     ('--accent', '--accent-wash'), ('--accent', '--wash')):
            self.assertIn(pair, pairs)

    def test_controls_have_hover_focus_and_short_transitions(self):
        css = text('web', 'app.css')
        self.assertRegex(css, r'--motion:\s*1[2-8]0ms;')
        rules = re.findall(r'([^{}]+)\{([^{}]*)\}', css)
        for control in ('a', 'button', 'input', 'select', 'textarea', 'summary'):
            for state in (':hover', ':focus-visible'):
                self.assertTrue(any(re.search(r'(?<![\w.-])' + control + re.escape(state) + r'\b', selector) for selector, _ in rules), (control, state))
            self.assertTrue(any(control in [s.strip() for s in selector.split(',')] and 'transition:' in body for selector, body in rules), control)
        self.assertRegex(css, r'nav\[data-nav\][^{]*\{[^}]*position: sticky;[^}]*height: 100vh;')
        card = re.search(r'(?m)^\.card\s*\{([^}]+)', css).group(1)
        self.assertIn('border: 0', card)
        self.assertIn('box-shadow: var(--shadow)', card)
        self.assertIn('--radius-card: 12px', css)

    def test_state_words_and_long_hex_have_one_display_boundary(self):
        js = text('web', 'app.js')
        html = text('web', 'index.html')
        self.assertNotRegex(html, r'>\s*[A-Z]{4,}\s*<')
        for unsafe in ('LABEL[state] || state', "{'data-order-field': key}, o[key]", "? 'LIVE RUN' : 'PAST RUN'"):
            self.assertNotIn(unsafe, js)
        self.assertIn("key === 'state' ? badge(o.state)", js)
        self.assertEqual(js.count('function shortHex('), 1)
        self.assertIn("/[a-f0-9]{16,}/gi", js)
        self.assertIn("hex.slice(0, 8) + '…'", js)
        self.assertIn("e.setAttribute('title'", js)
        cases = [('abcdef012345678', 'abcdef012345678'), ('abcdef0123456789', 'abcdef01…'),
                 ('order-ABCDEF0123456789/note.txt', 'order-ABCDEF01…/note.txt'),
                 ('a' * 40 + ' / ' + '0' * 64, 'aaaaaaaa… / 00000000…')]
        for full, expected in cases:
            self.assertEqual(short_hex(full), expected)
        if shutil.which('node'):
            helper = re.search(r'function shortHex\(value, limit\) \{.*?\n', js).group(0)
            script = helper + '\nprocess.stdout.write(JSON.stringify(' + json.dumps([c[0] for c in cases]) + '.map(value => shortHex(value))));'
            result = subprocess.run(['node', '-e', script], capture_output=True, text=True, check=True)
            self.assertEqual(json.loads(result.stdout), [c[1] for c in cases])
            limited = ['order-' + 'a' * 40, 'order-' + 'a' * 40 + '.a-very-long-step-name', 'w' * 90]
            script = helper + '\nprocess.stdout.write(JSON.stringify(' + json.dumps(limited) + '.map(value => shortHex(value, 22))));'
            shown = json.loads(subprocess.run(['node', '-e', script], capture_output=True, text=True, check=True).stdout)
            self.assertEqual(shown[0], 'order-aaaaaaaa…')
            for value in shown:
                self.assertLessEqual(len(value), 22)
                self.assertEqual(value.count('…'), 1)


