        self.assertEqual(r.returncode, 0, r.stdout + r.stderr)

    def test_a_changed_file_or_anything_but_plain_paths_is_refused(self):
        d = tempfile.mkdtemp(prefix='icons-')
        self.addCleanup(shutil.rmtree, d, True)
        for _, name, _, _ in M.SOURCES:
            shutil.copy(os.path.join(ICONS, name), d)
        self.assertEqual(M.build(d), M.build(ICONS))
        family, name, _, sha = M.SOURCES[0]
        good = text('icons', name)
        for bad in (good.replace('</svg>', '<script>alert(1)</script></svg>'), good.replace('<path ', '<path onload="x()" ', 1),
                    good.replace('fill="#', 'fill="url(//elsewhere.example/x)#', 1), good.replace('<path d="', '<path d="javascript:', 1)):
            self.assertNotEqual(bad, good)
            with open(os.path.join(d, name), 'w', encoding='utf-8') as f:
                f.write(bad)
            self.assertRaises(ValueError, M.build, d)                                   # not the file ICONS.md names
            own = hashlib.sha256(bad.encode('utf-8')).hexdigest()
            self.assertRaises(ValueError, M.read, d, name, own)                         # and refused for what it holds, too
        os.remove(os.path.join(d, name))
        self.assertRaises(OSError, M.build, d)

    def test_every_source_file_is_named_with_its_checksum_in_icons_md(self):
        doc = text('ICONS.md')
        for _, name, _, sha in M.SOURCES:
            self.assertIn(name, doc)
            self.assertIn(sha, doc)
            with open(os.path.join(ICONS, name), 'rb') as f:
                self.assertEqual(hashlib.sha256(f.read()).hexdigest(), sha)
        self.assertTrue(os.path.isfile(os.path.join(ICONS, 'LICENSE')))


