#!/usr/bin/env python3
"""tools/privacy_scan.py: every class it names is hit by a sample, clean text is not, the git history is read too, and
this repository itself is clean.  Every sample is put together from pieces so that this file holds none of them."""
import os
import shutil
import struct
import subprocess
import sys
import tempfile
import unittest
import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'tools'))

import privacy_scan as P            # noqa: E402

AT = '@'
SAMPLES = {                         # class: lines that must be hit
    'home-path': ['open ' + '/' + 'Users' + '/' + 'someone/notes.txt', 'cd ' + '/' + 'home' + '/' + 'dev01/work', 'C:' + '\\' + 'Users' + '\\' + 'Dev' + '\\' + 'x'],
    'email': ['write to someone' + AT + 'corp-mail.com today', 'first.last+tag' + AT + 'mail.example-corp.io'],
    'private-net': ['http://box' + '.ts' + '.net/page', 'host tail' + '0a1b2c is up'],
    'session-link': ['see https://claude' + '.ai/' + 'code/session_x', 'https://chatgpt' + '.com/' + 'share/abc'],
    'attribution': ['Co-Authored' + '-By: Some Tool <x>', 'Claude' + '-Session: y', 'Generated' + ' with [Claude' + ' Code]'],
    'secret': ['key sk' + '-' + 'a1B2' * 6, 'gh' + 'p_' + 'A1b2' * 9, '-----BEGIN RSA ' + 'PRIVATE KEY-----', 'AK' + 'IA' + 'ABCD1234' * 2,
               'api' + '_key = "' + 'Zx9' * 9 + '"'],
    'paid-kit': ['import x from "affect' + 'ui/pro"', 'the Affect' + 'UI kit'],
    'other-cli': ['run claude' + ' -p "hi"', 'run codex' + ' exec "hi"'],
    'not-english': ['title: ' + chr(0x4e2d) + chr(0x6587), 'kana ' + chr(0x30a2), 'wide ' + chr(0xff01)],
}
CLEAN = ['opencode run --format json -m deepseek/deepseek-chat', 'mail first' + AT + 'example.com or 1+someone' + AT + 'users.noreply.github.com',
         'adapter' + AT + 'dispatch.invalid', 'http://127.0.0.1:8800/', 'OPENCODE_DISABLE_CLAUDE_CODE=1', 'DEEPSEEK_API_KEY', 'tests/fake_bin/opencode',
         'the budget is 6 and the token is short', 'a dash ' + chr(0x2014) + ' and a dot ' + chr(0xb7)]
IDENT = {'GIT_AUTHOR_NAME': 'tester', 'GIT_COMMITTER_NAME': 'tester', 'GIT_AUTHOR_EMAIL': 'tester' + AT + 'example.com', 'GIT_COMMITTER_EMAIL': 'tester' + AT + 'example.com'}


def kinds(hits):
    return sorted({h[0] for h in hits})


def png(*chunks):
    out = b'\x89PNG\r\n\x1a\n'
    for kind, body in (('IHDR', struct.pack('>IIBBBBB', 1, 1, 8, 0, 0, 0, 0)),) + chunks + (('IEND', b''),):
        k = kind.encode('ascii')
        out += struct.pack('>I', len(body)) + k + body + struct.pack('>I', zlib.crc32(k + body) & 0xffffffff)
    return out


class Repo:
    """A throwaway git repository whose commits carry a harmless identity unless one is given."""

    def __init__(self):
        self.root = tempfile.mkdtemp(prefix='scan-')
        self.home = tempfile.mkdtemp(prefix='scan-home-')
        self.git('init', '-q', '-b', 'main')

    def git(self, *args, **env):
        e = dict({'PATH': os.environ.get('PATH', ''), 'HOME': self.home}, **IDENT)
        e.update(env)
        r = subprocess.run(('git', '-C', self.root, '-c', 'commit.gpgsign=false') + args, env=e, capture_output=True)
        assert r.returncode == 0, r.stderr.decode('utf-8', 'replace')

    def put(self, name, text):
        with open(os.path.join(self.root, name), 'w', encoding='utf-8') as f:
            f.write(text)
        self.git('add', name)

    def commit(self, message, **env):
        self.git('commit', '-q', '--allow-empty', '-m', message, **env)

    def close(self):
        shutil.rmtree(self.root, ignore_errors=True)
        shutil.rmtree(self.home, ignore_errors=True)


class Classes(unittest.TestCase):
    def test_every_sample_is_hit_as_its_own_class(self):
        for kind, lines in SAMPLES.items():
            for line in lines:
                self.assertIn(kind, kinds(P.scan_bytes(line.encode('utf-8'), 'x')), (kind, P.mask(line)))

    def test_clean_lines_are_not_hit(self):
        for line in CLEAN:
            self.assertEqual(P.scan_bytes(line.encode('utf-8'), 'x'), [], line)

    def test_an_address_on_a_reserved_or_no_reply_domain_passes_and_any_other_does_not(self):
        ok = 'first' + AT + 'example.org and 42+name' + AT + 'users.noreply.github.com and a' + AT + 'b.invalid'
        self.assertEqual(P.scan_bytes(ok.encode(), 'x'), [])
        self.assertEqual(kinds(P.scan_bytes(('a' + AT + 'example.com.evil-corp.io').encode(), 'x')), ['email'])

    def test_the_local_account_and_the_extra_list(self):
        line = b'built by Zzlocalname on the Blueharbor machine'
        self.assertEqual(P.scan_bytes(line, 'x'), [])
        self.assertEqual(kinds(P.scan_bytes(line, 'x', names=('zzlocalname',))), ['local-user'])
        self.assertEqual(kinds(P.scan_bytes(line, 'x', extra=('blueHarbor',))), ['extra'])

    def test_generic_and_short_account_names_are_not_looked_for(self):
        for n in P.local_names():
            self.assertTrue(len(n) >= 4 and n not in P.GENERIC, n)

    def test_a_picture_with_a_text_chunk_and_an_unreadable_binary(self):
        self.assertEqual(P.scan_bytes(png(), 'a.png'), [])
        self.assertEqual(kinds(P.scan_bytes(png(('tEXt', b'Author\0somebody')), 'a.png')), ['image-metadata'])
        self.assertEqual(kinds(P.scan_bytes(png(('eXIf', b'II*\0')), 'a.png')), ['image-metadata'])
        self.assertEqual(kinds(P.scan_bytes(b'\x7fELF\0\0\1\2', 'a.bin')), ['binary'])

    def test_a_hit_is_printed_masked(self):
        line = SAMPLES['email'][0]
        (hit,) = P.scan_bytes(line.encode(), 'x')
        self.assertNotIn('corp-mail', hit[3])
        self.assertEqual(hit[2], 1)


class History(unittest.TestCase):
    def setUp(self):
        self.repo = Repo()
        self.addCleanup(self.repo.close)

    def test_a_clean_repository(self):
        self.repo.put('a.txt', 'nothing here\n')
        self.repo.commit('first')
        self.assertEqual(P.scan(self.repo.root, True, names=()), [])

    def test_a_file_that_was_deleted_is_still_found_in_the_history(self):
        self.repo.put('a.txt', SAMPLES['home-path'][0] + '\n')
        self.repo.commit('first')
        self.repo.git('rm', '-q', 'a.txt')
        self.repo.put('b.txt', 'fine\n')
        self.repo.commit('second')
        self.assertEqual(P.scan(self.repo.root, False, names=()), [])
        self.assertEqual(kinds(P.scan(self.repo.root, True, names=())), ['home-path'])

    def test_a_commit_message_and_a_commit_address_are_read(self):
        self.repo.put('a.txt', 'fine\n')
        self.repo.commit('first\n\n' + SAMPLES['attribution'][0])
        self.assertEqual(kinds(P.scan(self.repo.root, True, names=())), ['attribution'])
        self.repo.commit('second', GIT_AUTHOR_EMAIL='someone' + AT + 'corp-mail.com')
        self.assertEqual(kinds(P.scan(self.repo.root, True, names=())), ['attribution', 'email'])

    def test_an_untracked_file_is_not_this_scan_s_business_and_a_tracked_one_is(self):
        with open(os.path.join(self.repo.root, 'loose.txt'), 'w', encoding='utf-8') as f:
            f.write(SAMPLES['secret'][0])
        self.repo.put('a.txt', 'fine\n')
        self.repo.commit('first')
        self.assertEqual(P.scan(self.repo.root, True, names=()), [])
        self.repo.git('add', 'loose.txt')
        self.assertEqual(kinds(P.scan(self.repo.root, False, names=())), ['secret'])

    def test_history_of_a_folder_that_is_no_repository_is_an_error_not_a_pass(self):
        d = tempfile.mkdtemp(prefix='scan-plain-')
        self.addCleanup(shutil.rmtree, d, True)
        with open(os.path.join(d, 'a.txt'), 'w', encoding='utf-8') as f:
            f.write(SAMPLES['paid-kit'][0])
        self.assertEqual(kinds(P.scan(d, False, names=())), ['paid-kit'])
        self.assertRaises(RuntimeError, P.scan, d, True)
        self.assertEqual(P.main(['--history', d]), 2)


class CommandLine(unittest.TestCase):
    def run_scan(self, *args):
        r = subprocess.run([sys.executable, os.path.join(ROOT, 'tools', 'privacy_scan.py')] + list(args), capture_output=True, text=True)
        return r.returncode, r.stdout

    def test_exit_codes(self):
        d = tempfile.mkdtemp(prefix='scan-cli-')
        self.addCleanup(shutil.rmtree, d, True)
        with open(os.path.join(d, 'a.txt'), 'w', encoding='utf-8') as f:
            f.write('fine, at Blueharbor\n')
        self.assertEqual(self.run_scan(d)[0], 0)
        outside = tempfile.mkdtemp(prefix='scan-list-')         # the list is kept outside what is scanned, or it would hit itself
        self.addCleanup(shutil.rmtree, outside, True)
        extra = os.path.join(outside, 'list')
        with open(extra, 'w', encoding='utf-8') as f:
            f.write('nothing-like-it\n')
        self.assertEqual(self.run_scan('--extra', extra, d)[0], 0)
        with open(extra, 'w', encoding='utf-8') as f:
            f.write('blueharbor\n')
        rc, out = self.run_scan('--extra', extra, d)
        self.assertEqual(rc, 1)
        self.assertIn('extra', out)
        self.assertNotIn('blueharbor', out.lower().replace('fine, at blueharbor', ''))
        self.assertEqual(self.run_scan('--extra', os.path.join(outside, 'missing'), d)[0], 2)
        self.assertEqual(self.run_scan('--no-such-flag')[0], 2)

    def test_this_repository_is_clean(self):
        hits = P.scan(ROOT, P.is_repo(ROOT))
        self.assertEqual(hits, [], hits[:5])


