#!/usr/bin/env python3
"""Rebuild web/icons.js from the three SVG files named in ICONS.md.

    python3 tools/make_icons.py [FOLDER]     FOLDER (default: icons/) holds deepseek-color.svg, kimi-color.svg, qwen-color.svg
    python3 tools/make_icons.py --check      exit 1 when web/icons.js is not what those files give

Only path data and fill colours are taken out of a file.  A file that is not exactly the one ICONS.md names (by SHA-256),
or that holds anything but <svg>, <title> and <path d fill>, is refused: nothing of it is ever run or copied as markup."""
import hashlib
import json
import os
import re
import sys

SOURCES = (     # family, file, display name, SHA-256 of the file in @lobehub/icons-static-svg 1.104.0
    ('deepseek', 'deepseek-color.svg', 'DeepSeek', 'deba5f98a5c1796e20fcac3149bcd7eb8a32f0bdd04d048819400b1f28bd1439'),
    ('kimi', 'kimi-color.svg', 'Kimi', '0bdb95375d7c6e90a1850e91cd36770da2bc98fa33ec2d783f4a8fed027da85f'),
    ('qwen', 'qwen-color.svg', 'Qwen', 'a158a0e3ed5b541e4f91384ece02c3acf0a0d81b7b11a46d77bafb248b09e32c'),
)
# drawn for this project (a plain hexagon ring), for a model of any other family
OTHER = {'name': 'Other model', 'box': '0 0 24 24', 'rule': 'evenodd', 'paths': [['#64748b', 'M12 2l8.66 5v10L12 22l-8.66-5V7zM12 5.46L6.34 8.73v6.54L12 18.54l5.66-3.27V8.73z']]}
WHOLE = re.compile(r'^<svg height="1em" style="flex:none;line-height:1" viewBox="(0 0 \d+ \d+)" width="1em" xmlns="http://www\.w3\.org/2000/svg">'
                   r'<title>([A-Za-z0-9 ]+)</title>((?:<path d="[^"<>]*" fill="[^"<>]*"></path>)+)</svg>\s*$')
PATH = re.compile(r'<path d="([^"]*)" fill="([^"]*)"></path>')
D = re.compile(r'^[MmLlHhVvCcSsQqTtAaZz0-9 .,eE-]+$')
FILL = re.compile(r'^(#[0-9a-fA-F]{3,8}|currentColor)$')
HEAD = '/* Generated by tools/make_icons.py from @lobehub/icons-static-svg 1.104.0 (MIT, Copyright (c) 2023 LobeHub). See ICONS.md. Do not edit by hand. */\n'


def read(folder, name, sha):
    with open(os.path.join(folder, name), 'rb') as f:
        data = f.read()
    got = hashlib.sha256(data).hexdigest()
    if got != sha:
        raise ValueError('%s is not the file ICONS.md names (sha256 %s)' % (name, got))
    m = WHOLE.match(data.decode('utf-8'))
    if not m:
        raise ValueError('%s holds something other than <svg>, <title> and <path d fill>' % name)
    paths = PATH.findall(m.group(3))
    for d, fill in paths:
        if not D.match(d) or not FILL.match(fill):
            raise ValueError('%s: a path or a fill is not plain path data / a plain colour' % name)
    return {'name': None, 'box': m.group(1), 'paths': [[fill, d] for d, fill in paths]}


def build(folder):
    icons = {}
    for family, name, title, sha in SOURCES:
        icons[family] = dict(read(folder, name, sha), name=title)
    icons['other'] = OTHER
    return HEAD + 'window.MODEL_ICONS = ' + json.dumps(icons, indent=1) + ';\n'


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(ROOT, 'web', 'icons.js')


def main(argv):
    check = '--check' in argv
    rest = [a for a in argv if a != '--check']
    if len(rest) > 1 or any(a.startswith('-') for a in rest):
        sys.stderr.write(__doc__)
        return 2
    try:
        text = build(rest[0] if rest else os.path.join(ROOT, 'icons'))
    except (OSError, ValueError) as e:
        sys.stderr.write('ERROR %s\n' % e)
        return 1
    if check:
        try:
            with open(OUT, encoding='utf-8') as f:
                same = f.read() == text
        except OSError:
            same = False
        print('web/icons.js is %s' % ('up to date' if same else 'NOT what the files in icons/ give: run tools/make_icons.py'))
        return 0 if same else 1
    with open(OUT, 'w', encoding='utf-8') as f:
        f.write(text)
    print('wrote web/icons.js (%d bytes)' % len(text))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
