#!/usr/bin/env python3
"""Build opencode-cockpit.sh: one bash file that writes every other tracked file of this repository into a folder.

    python3 tools/make_oneshot.py            write opencode-cockpit.sh
    python3 tools/make_oneshot.py --check    exit 1 when opencode-cockpit.sh is not what the tracked files give

A file that is UTF-8 text is carried as a quoted here-document, so the bash file can be read before it is run; a file
with a NUL or carriage-return byte, or that is not UTF-8, is carried as base64.  The bash file calls no git and opens no
connection, refuses a folder that already holds files, writes nothing outside that folder, and ends by checking the
SHA-256 of every file it wrote."""
import base64
import hashlib
import os
import re
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = 'opencode-cockpit.sh'
SAFE = re.compile(r'^[A-Za-z0-9._][A-Za-z0-9._/-]*\Z')     # a path the bash file may write: no quote, space, leading - or /

HEAD = '''#!/usr/bin/env bash
# OpenCode Cockpit as one file.  Generated by tools/make_oneshot.py from the tracked files of the repository: do not edit.
#
#     bash opencode-cockpit.sh [FOLDER]     write the %(n)d files into FOLDER (default: opencode-cockpit)
#
# Needs %(needs)s.  It calls no git and opens no connection, refuses a FOLDER that already holds
# files, writes nothing outside FOLDER, and ends by checking the SHA-256 of every file it wrote.
# %(carried)s
set -eu
dest=${1:-opencode-cockpit}
case "$dest" in -*) echo "usage: bash opencode-cockpit.sh [FOLDER]" >&2; exit 2;; esac
if [ -e "$dest" ] && [ -n "$(ls -A "$dest" 2>/dev/null)" ]; then
  echo "opencode-cockpit.sh: $dest already holds files; give a new or empty folder" >&2; exit 2
fi
%(b64)sif command -v sha256sum >/dev/null 2>&1; then sum256() { sha256sum "$1" | cut -d' ' -f1; }
elif command -v shasum >/dev/null 2>&1; then sum256() { shasum -a 256 "$1" | cut -d' ' -f1; }
else echo "opencode-cockpit.sh: needs sha256sum or shasum to check what it writes" >&2; exit 2; fi
chop() { printf '%%s' "$(cat "$1")" > "$1.oc-tmp" && mv "$1.oc-tmp" "$1"; }     # drop the newline a here-document adds
mkdir -p "$dest"; cd "$dest"
'''

B64 = '''if printf 'QQ==' | base64 --decode >/dev/null 2>&1; then b64() { base64 --decode; }
elif printf 'QQ==' | base64 -d >/dev/null 2>&1; then b64() { base64 -d; }
else echo "opencode-cockpit.sh: needs base64 to write the files that are not text" >&2; exit 2; fi
'''     # in the head only when a file is carried as base64

TAIL = '''bad=0; n=0
while read -r want path; do
  n=$((n+1)); [ -f "$path" ] && got=$(sum256 "$path") || got=missing
  [ "$got" = "$want" ] || { echo "opencode-cockpit.sh: $path is not what this script holds" >&2; bad=$((bad+1)); }
done <<'%(mark)s'
%(sums)s
%(mark)s
if [ "$bad" -ne 0 ]; then echo "opencode-cockpit.sh: $bad of $n files are wrong; do not use this folder" >&2; exit 1; fi
echo "Wrote $n files into $(pwd) and checked each one."
echo "Next: read README.md there (\\"Try it without a model\\")."
'''


def tracked():
    """(path, bytes, executable) of every tracked file but the bash file itself."""
    out = subprocess.run(['git', '-C', ROOT, 'ls-files', '-s', '-z'], check=True, stdout=subprocess.PIPE).stdout.decode('utf-8')
    rows = []
    for entry in filter(None, out.split('\0')):
        meta, path = entry.split('\t', 1)
        mode = meta.split()[0]
        if path == OUT:
            continue
        if mode not in ('100644', '100755'):
            raise SystemExit('make_oneshot: cannot carry %s (mode %s): only plain files' % (path, mode))
        with open(os.path.join(ROOT, path), 'rb') as f:
            rows.append((path, f.read(), mode == '100755'))
    return rows


def is_text(data):
    if b'\0' in data or b'\r' in data:
        return False
    try:
        data.decode('utf-8')
    except UnicodeDecodeError:
        return False
    return True


def mark_for(lines, n):
    """A here-document end mark that is no line of the body."""
    mark = 'OC_EOF_%d' % n
    while mark in lines:
        mark += '_'
    return mark


def block(n, path, data, executable):
    if not data:
        out = [": > '%s'" % path]
    elif is_text(data):
        text = data.decode('utf-8')
        whole = text.endswith('\n')
        lines = (text if whole else text + '\n').split('\n')[:-1]
        mark = mark_for(lines, n)
        out = ["cat > '%s' <<'%s'" % (path, mark)] + lines + [mark] + ([] if whole else ["chop '%s'" % path])
    else:
        b = base64.b64encode(data).decode('ascii')
        out = ["b64 > '%s' <<'OC_EOF_%d'" % (path, n)] + [b[i:i + 76] for i in range(0, len(b), 76)] + ['OC_EOF_%d' % n]
    return out + (["chmod +x '%s'" % path] if executable else [])


def build(rows=None):
    """The text of the bash file for rows of (path, bytes, executable); the tracked files when rows is None."""
    rows = sorted(tracked() if rows is None else rows)
    for path, _, _ in rows:
        if not SAFE.match(path) or any(part in ('', '.', '..') for part in path.split('/')):
            raise SystemExit('make_oneshot: cannot carry %r: only simple relative paths' % path)
    dirs = sorted({os.path.dirname(p) for p, _, _ in rows} - {''})
    body = ['mkdir -p ' + ' '.join("'%s'" % d for d in dirs)] if dirs else []
    for n, (path, data, executable) in enumerate(rows):
        body += block(n, path, data, executable)
    sums = ['%s %s' % (hashlib.sha256(data).hexdigest(), path) for path, data, _ in rows]
    binary = sum(1 for _, d, _ in rows if d and not is_text(d))
    head = HEAD % {'n': len(rows), 'b64': B64 if binary else '',
                   'needs': 'bash, base64, and sha256sum or shasum' if binary else 'bash, and sha256sum or shasum',
                   'carried': 'Text files below are plain here-documents, so this file can be read before it is run; the %d that are\n'
                              '# not text are base64.' % binary if binary
                   else 'Every file below is a plain here-document, so this file can be read before it is run.'}
    return head + '\n'.join(body) + '\n' + TAIL % {'mark': mark_for(sums, len(rows)), 'sums': '\n'.join(sums)}


def main(argv):
    text, path = build().encode('utf-8'), os.path.join(ROOT, OUT)
    if '--check' in argv:
        same = os.path.exists(path) and open(path, 'rb').read() == text
        print('%s is %s' % (OUT, 'up to date' if same else 'NOT what the tracked files give: run python3 tools/make_oneshot.py'))
        return 0 if same else 1
    with open(path, 'wb') as f:
        f.write(text)
    print('%s: %d bytes' % (OUT, len(text)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
