#!/usr/bin/env python3
"""Look for things that must not be in a public repository: in the tracked files, and with --history in every file and
every commit the repository has ever had.

    python3 tools/privacy_scan.py [--history] [--extra FILE] [FOLDER]

Exit 0: nothing found.  1: something found (one line per hit: class, where, a masked excerpt).  2: could not scan.

What counts as a hit:
  home-path       a path inside somebody's home folder
  local-user      the account name or the machine name of whoever runs the scan (skipped for generic names)
  email           any address that is not on a reserved or no-reply domain
  private-net     a private network host name
  session-link    a link into an assistant session
  attribution     a co-author or "generated with" line of an AI tool
  secret          something shaped like an API key, an access token or a private key
  paid-kit        the name of a paid UI kit this project must not contain
  other-cli       a command line of an agent CLI other than OpenCode (this backend starts OpenCode only)
  not-english     a CJK character (the interface and the documents are in English)
  image-metadata  a PNG that carries a text or EXIF chunk
  binary          a binary file of a kind this scan cannot read (so nothing unread gets in quietly)
  extra           a line of the --extra file (your own list of strings; it stays outside the repository)

Limits: it reads text, not pictures, so it cannot see what a screenshot shows; and a class above is a pattern, not proof.
The patterns below are written so that this file does not match itself."""
import getpass
import os
import re
import socket
import struct
import subprocess
import sys

GENERIC = {'root', 'runner', 'runneradmin', 'user', 'ubuntu', 'admin', 'vscode', 'codespace', 'nobody', 'localhost', 'build', 'home', 'test'}
OK_MAIL = re.compile(r'(@|\.)(example\.(com|org|net)|[a-z0-9.-]+\.(invalid|example|test|localhost)|users\.noreply\.github\.com)$', re.I)
CJK = ((0x3000, 0x303f), (0x3040, 0x30ff), (0x3400, 0x4dbf), (0x4e00, 0x9fff), (0xac00, 0xd7af), (0xff00, 0xffef))     # code points, so that this file stays ASCII
RULES = (
    ('home-path', re.compile(r'(?:/(?:Users|home)/|[A-Z]:\\Users\\)[A-Za-z0-9._-]+[/\\]')),
    ('email', re.compile(r'[A-Za-z0-9._+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}')),
    ('private-net', re.compile(r'[a-z0-9-]+\.ts\.net\b|\btail[0-9a-f]{5,8}\b', re.I)),
    ('session-link', re.compile(r'claude\.ai/|chatgpt\.com/(?:c|share)/', re.I)),
    ('attribution', re.compile(r'co-authore[d]-by|claud[e]-session|generate[d] with \[?(?:claud[e]|code[x]|copilo[t])', re.I)),
    ('secret', re.compile(r'\bsk-[A-Za-z0-9_-]{20,}|\bgh[pousr]_[A-Za-z0-9]{30,}|\bgithub_pat_[A-Za-z0-9_]{20,}|\bAKIA[0-9A-Z]{16}\b|\bxox[baprs]-[A-Za-z0-9-]{10,}'
                          r'|\bAIza[0-9A-Za-z_-]{35}|-----BEGIN [A-Z ]*PRIVATE KEY-----'
                          r'|(?:api[_-]?key|secret|token|passw(?:or)?d)["\']?\s*[:=]\s*["\']?[A-Za-z0-9_+/-]{24,}', re.I)),
    ('paid-kit', re.compile(r'affec[t]ui', re.I)),
    ('other-cli', re.compile(r'claud[e] -p\b|code[x] exec\b')),
    ('not-english', re.compile('[%s]' % ''.join('%s-%s' % (chr(a), chr(b)) for a, b in CJK))),
)
PNG_TEXT = (b'tEXt', b'zTXt', b'iTXt', b'eXIf')
SKIP_DIRS = {'.git', '__pycache__', 'runs', 'node_modules'}


def mask(s):
    s = s.strip()
    return (s[:4] + '...(%d chars)' % len(s)) if len(s) > 8 else s[:2] + '...'


def local_names():
    names = set()
    for get in (getpass.getuser, lambda: os.path.basename(os.path.expanduser('~')), lambda: socket.gethostname().split('.')[0]):
        try:
            n = get().strip().lower()
        except Exception:               # no such account entry, no host name: then there is no name to look for
            continue
        if len(n) >= 4 and n not in GENERIC:
            names.add(n)
    return sorted(names)


def png_chunks(data):
    pos, out = 8, []
    while pos + 8 <= len(data):
        n, kind = struct.unpack('>I4s', data[pos:pos + 8])
        out.append(kind)
        pos += 12 + n
    return out


def scan_bytes(data, where, extra=(), names=()):
    """[(class, where, line, masked excerpt)] for one file's bytes (or one commit's text)."""
    if data[:8] == b'\x89PNG\r\n\x1a\n':
        return [('image-metadata', where, 0, k.decode('ascii', 'replace')) for k in png_chunks(data) if k in PNG_TEXT]
    if b'\0' in data:
        return [('binary', where, 0, '%d bytes' % len(data))]
    hits = []
    for n, line in enumerate(data.decode('utf-8', 'replace').splitlines(), 1):
        for kind, rx in RULES:
            for m in rx.finditer(line):
                if kind == 'email' and OK_MAIL.search(m.group(0)):
                    continue
                hits.append((kind, where, n, mask(m.group(0))))
        low = line.lower()
        hits += [('local-user', where, n, mask(x)) for x in names if x in low]
        hits += [('extra', where, n, mask(x)) for x in extra if x.lower() in low]
    return hits


def git(root, *args, **kw):
    r = subprocess.run(['git', '-C', root] + list(args), capture_output=True, **kw)
    if r.returncode:
        raise RuntimeError('git %s: %s' % (args[0], r.stderr.decode('utf-8', 'replace').strip()[:200]))
    return r.stdout


def is_repo(root):
    return subprocess.run(['git', '-C', root, 'rev-parse', '--git-dir'], capture_output=True).returncode == 0


def tracked(root):
    """{path: bytes} of the tracked files (of every file when the folder is not a git repository)."""
    if is_repo(root):
        names = [n for n in git(root, 'ls-files', '-z').decode('utf-8').split('\0') if n]
    else:
        names = []
        for d, dirs, files in os.walk(root):
            dirs[:] = sorted(x for x in dirs if x not in SKIP_DIRS)
            names += [os.path.relpath(os.path.join(d, f), root) for f in sorted(files)]
    out = {}
    for n in names:
        p = os.path.join(root, n)
        if os.path.isfile(p) and not os.path.islink(p):
            with open(p, 'rb') as f:
                out[n] = f.read()
    return out


def history(root):
    """[(where, bytes)]: every blob any commit of any ref reaches, and every commit's names, addresses and message."""
    out, seen = [], set()
    if not git(root, 'rev-list', '--all', '-n', '1').strip():
        return out
    for line in git(root, 'rev-list', '--all', '--objects').decode('utf-8', 'replace').splitlines():
        sha, _, path = line.partition(' ')
        if sha in seen:
            continue
        seen.add(sha)
        kind = git(root, 'cat-file', '-t', sha).decode().strip()
        if kind == 'blob':
            out.append(('%s@%s' % (path, sha[:10]), git(root, 'cat-file', 'blob', sha)))
        elif kind in ('commit', 'tag'):
            out.append(('%s %s' % (kind, sha[:10]), git(root, 'cat-file', kind, sha)))
    return out


def scan(root, with_history=False, extra=(), names=None):
    names = local_names() if names is None else names
    hits = []
    for path, data in sorted(tracked(root).items()):
        hits += scan_bytes(data, path, extra, names)
    if with_history:
        if not is_repo(root):
            raise RuntimeError('%s is not a git repository, so it has no history to scan' % root)
        for where, data in history(root):
            hits += scan_bytes(data, where, extra, names)
    return hits


def main(argv):
    args, with_history, extra = [], False, []
    it = iter(argv)
    for a in it:
        if a == '--history':
            with_history = True
        elif a == '--extra':
            try:
                with open(next(it), encoding='utf-8') as f:
                    extra = [x.strip() for x in f if x.strip()]
            except (OSError, StopIteration) as e:
                sys.stderr.write('ERROR the --extra file cannot be read: %r\n' % e)
                return 2
        elif a.startswith('-'):
            sys.stderr.write(__doc__)
            return 2
        else:
            args.append(a)
    root = os.path.abspath(args[0] if args else os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    try:
        hits = scan(root, with_history, extra)
    except (OSError, RuntimeError) as e:
        sys.stderr.write('ERROR could not scan: %s\n' % e)
        return 2
    for kind, where, line, text in hits:
        print('%-15s %s:%d  %s' % (kind, where, line, text))
    print('%d hit(s) in %s%s' % (len(hits), 'the tracked files' if is_repo(root) else 'the files', ' and the history' if with_history else ''))
    return 1 if hits else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
